CREATE OR REPLACE FUNCTION app_private.setting(p_key text) RETURNS integer
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT value_int FROM public.pricing_settings WHERE key = p_key;
$$;

-- ───────────────────────── The price calculator (single source of truth) ─────────────────────────
-- p_weekly_pattern: [{"weekday": 1, "kind": "body"}, ...]  (weekday 0 = Sunday)
-- Returns the full, explicit breakdown. Every rupee of discount appears as a labelled line.
CREATE OR REPLACE FUNCTION app_private.compute_membership_quote(p_vehicle_type public.vehicle_type, p_weekly_pattern jsonb, p_duration_months integer)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_freq integer;
  v_weeks integer := app_private.setting('weeks_per_month');
  v_cap_bp integer := app_private.setting('max_total_discount_bp');
  v_bodies integer;
  v_deeps integer;
  v_lines jsonb := '[]'::jsonb;
  v_subtotal bigint := 0;
  v_freq_bp integer;
  v_dur_bp integer;
  v_freq_cents bigint;
  v_dur_cents bigint;
  v_combined bigint;
  v_cap_cents bigint;
  v_cap_adj bigint := 0;
  v_total_discount bigint;
  rec record;
BEGIN
  IF p_weekly_pattern IS NULL OR jsonb_typeof(p_weekly_pattern) <> 'array' THEN
    RAISE EXCEPTION 'Choose your washes for the week';
  END IF;
  v_freq := jsonb_array_length(p_weekly_pattern);
  IF v_freq NOT BETWEEN 1 AND 3 THEN
    RAISE EXCEPTION 'A membership has 1, 2 or 3 washes a week';
  END IF;

  IF (SELECT count(DISTINCT (e->>'weekday')) FROM jsonb_array_elements(p_weekly_pattern) e) <> v_freq THEN
    RAISE EXCEPTION 'Choose a different day for each wash';
  END IF;
  IF EXISTS (SELECT 1 FROM jsonb_array_elements(p_weekly_pattern) e
              WHERE (e->>'weekday') IS NULL OR (e->>'weekday') !~ '^[0-6]$' OR (e->>'kind') NOT IN ('body', 'deep') OR (e->>'kind') IS NULL) THEN
    RAISE EXCEPTION 'Each wash needs a weekday (0-6) and a kind (body or deep)';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.membership_discount_rules WHERE active AND kind = 'duration' AND key_value = p_duration_months) THEN
    RAISE EXCEPTION 'Membership length must be 1, 3, 6 or 12 months';
  END IF;

  SELECT count(*) FILTER (WHERE e->>'kind' = 'body'), count(*) FILTER (WHERE e->>'kind' = 'deep')
    INTO v_bodies, v_deeps FROM jsonb_array_elements(p_weekly_pattern) e;

  -- Composition rules
  IF p_vehicle_type = 'bike' THEN
    IF v_deeps > 0 THEN RAISE EXCEPTION 'Bikes have one wash type'; END IF;
  ELSIF v_freq = 2 AND NOT (v_bodies = 1 AND v_deeps = 1) THEN
    RAISE EXCEPTION '2 washes a week is 1 body wash + 1 deep cleaning';
  ELSIF v_freq = 3 AND (v_bodies < 1 OR v_deeps < 1) THEN
    RAISE EXCEPTION '3 washes a week mixes body washes and deep cleanings';
  END IF;

  -- Lines: one per service
  FOR rec IN
    SELECT o.service_id, s.code, s.name, k.kind, k.n AS per_week
      FROM (SELECT e->>'kind' AS kind, count(*)::int AS n FROM jsonb_array_elements(p_weekly_pattern) e GROUP BY 1) k
      LEFT JOIN public.membership_service_options o ON o.vehicle_type = p_vehicle_type AND o.wash_kind = k.kind
      LEFT JOIN public.services s ON s.id = o.service_id
     ORDER BY k.kind
  LOOP
    IF rec.service_id IS NULL THEN
      RAISE EXCEPTION 'No % wash is offered for this vehicle', rec.kind;
    END IF;
    DECLARE
      v_unit integer := app_private.unit_price_cents(rec.service_id, p_vehicle_type);
      v_qty integer := rec.per_week * v_weeks * p_duration_months;
    BEGIN
      IF v_unit IS NULL THEN RAISE EXCEPTION 'No price is set for % on this vehicle', rec.name; END IF;
      v_lines := v_lines || jsonb_build_array(jsonb_build_object(
        'service_id', rec.service_id, 'code', rec.code, 'name', rec.name, 'kind', rec.kind,
        'per_week', rec.per_week, 'quantity', v_qty, 'unit_cents', v_unit, 'line_cents', v_unit::bigint * v_qty));
      v_subtotal := v_subtotal + v_unit::bigint * v_qty;
    END;
  END LOOP;

  SELECT discount_bp INTO v_freq_bp FROM public.membership_discount_rules WHERE active AND kind = 'frequency' AND key_value = v_freq;
  SELECT discount_bp INTO v_dur_bp  FROM public.membership_discount_rules WHERE active AND kind = 'duration'  AND key_value = p_duration_months;
  v_freq_bp := COALESCE(v_freq_bp, 0);
  v_dur_bp := COALESCE(v_dur_bp, 0);

  -- Sequential: frequency off the subtotal, then duration off what remains. Half-up rounding to the paisa.
  v_freq_cents := round(v_subtotal::numeric * v_freq_bp / 10000);
  v_dur_cents  := round((v_subtotal - v_freq_cents)::numeric * v_dur_bp / 10000);
  v_combined   := v_freq_cents + v_dur_cents;
  v_cap_cents  := round(v_subtotal::numeric * v_cap_bp / 10000);

  IF v_combined > v_cap_cents THEN
    v_cap_adj := v_combined - v_cap_cents;   -- the part of the discount the cap takes back
    v_total_discount := v_cap_cents;
  ELSE
    v_total_discount := v_combined;
  END IF;

  RETURN jsonb_build_object(
    'vehicle_type', p_vehicle_type,
    'frequency_per_week', v_freq,
    'duration_months', p_duration_months,
    'weeks_per_month', v_weeks,
    'washes_total', v_freq * v_weeks * p_duration_months,
    'lines', v_lines,
    'subtotal_cents', v_subtotal,
    'frequency_discount', jsonb_build_object('bp', v_freq_bp, 'cents', v_freq_cents, 'label', (SELECT label FROM public.membership_discount_rules WHERE active AND kind='frequency' AND key_value=v_freq)),
    'duration_discount',  jsonb_build_object('bp', v_dur_bp,  'cents', v_dur_cents,  'label', (SELECT label FROM public.membership_discount_rules WHERE active AND kind='duration'  AND key_value=p_duration_months)),
    'cap', jsonb_build_object('max_bp', v_cap_bp, 'applied', v_cap_adj > 0, 'adjustment_cents', v_cap_adj),
    'total_discount_cents', v_total_discount,
    'final_cents', v_subtotal - v_total_discount,
    'rounding', 'half_up_to_paisa'
  );
END;
$$;
REVOKE ALL ON FUNCTION app_private.compute_membership_quote(public.vehicle_type, jsonb, integer) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION app_private.compute_membership_quote(public.vehicle_type, jsonb, integer) TO service_role;
REVOKE ALL ON FUNCTION app_private.unit_price_cents(uuid, public.vehicle_type) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION app_private.unit_price_cents(uuid, public.vehicle_type) TO service_role;
REVOKE ALL ON FUNCTION app_private.setting(text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION app_private.setting(text) TO service_role;

-- ───────────────────────── Public catalogue (marketing site needs prices without a login) ─────────────────────────
CREATE OR REPLACE FUNCTION public.get_public_catalog() RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT jsonb_build_object(
    'services', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', s.id, 'code', s.code, 'name', s.name, 'description', s.description, 'tagline', s.tagline,
        'vehicle_type', s.vehicle_type, 'wash_kind', s.wash_kind, 'duration_minutes', s.duration_minutes,
        'includes', s.includes,
        'unit_prices', (SELECT jsonb_agg(jsonb_build_object('vehicle_type', r.vehicle_type, 'price_cents', r.base_amount_cents) ORDER BY r.vehicle_type)
                          FROM public.pricing_rules r
                         WHERE r.service_id = s.id AND r.duration_months = 1 AND r.quantity_tier = 1 AND r.active
                           AND r.valid_from <= now() AND (r.valid_to IS NULL OR r.valid_to > now()))
      ) ORDER BY s.sort_order, s.name) FROM public.services s WHERE s.is_active), '[]'::jsonb),
    'membership_options', COALESCE((SELECT jsonb_agg(jsonb_build_object('vehicle_type', o.vehicle_type, 'wash_kind', o.wash_kind, 'service_code', s.code) ORDER BY o.vehicle_type, o.wash_kind)
                                      FROM public.membership_service_options o JOIN public.services s ON s.id = o.service_id WHERE s.is_active), '[]'::jsonb),
    'discounts', COALESCE((SELECT jsonb_agg(jsonb_build_object('kind', kind, 'key', key_value, 'discount_bp', discount_bp, 'label', label) ORDER BY kind, key_value)
                             FROM public.membership_discount_rules WHERE active), '[]'::jsonb),
    'max_total_discount_bp', (SELECT value_int FROM public.pricing_settings WHERE key = 'max_total_discount_bp'),
    'weeks_per_month', (SELECT value_int FROM public.pricing_settings WHERE key = 'weeks_per_month')
  );
$$;
REVOKE ALL ON FUNCTION public.get_public_catalog() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_public_catalog() TO anon, authenticated, service_role;

-- ═════════════ 20261004000003_schema_additions.sql ═════════════
-- 20261004000003_schema_additions.sql
-- SAFE / additive: new columns, new tables, new indexes. No data is changed or removed, and nothing
-- here changes behaviour the mobile app relies on.
--
--   profiles            + email, signup_source (write-once)
--   vehicles            make becomes optional; normalised plate with a unique index
--   bookings            + reference_code, source, price_cents, cancel_reason; one live wash per vehicle per day
--   payments            + intent, payment_kind, membership_request_id, receipt, expires_at, fulfilment_status
--   memberships         + membership_request_id (a membership is only ever created from a PAID request)
--   membership_requests NEW: the customer -> WASHO review -> accept -> pay flow
--   website_leads       NEW: legacy marketing-site leads, preserved read-only
--   washo_api           NEW: the least-privilege role the Render web API connects as

-- ───────────────────────── helpers ─────────────────────────
CREATE OR REPLACE FUNCTION app_private.gen_ref(p_prefix text) RETURNS text
LANGUAGE plpgsql VOLATILE AS $$
DECLARE
  alphabet constant text := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'; -- no 0/O/1/I: readable over a phone call
  out text := '';
  i int;
BEGIN
  FOR i IN 1..6 LOOP
    out := out || substr(alphabet, 1 + floor(random() * length(alphabet))::int, 1);
  END LOOP;
  RETURN p_prefix || '-' || out;
END $$;
REVOKE ALL ON FUNCTION app_private.gen_ref(text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION app_private.gen_ref(text) TO service_role;

-- ───────────────────────── profiles ─────────────────────────
ALTER TABLE public.profiles
  ADD COLUMN IF NOT EXISTS email text,
  ADD COLUMN IF NOT EXISTS signup_source text;

ALTER TABLE public.profiles DROP CONSTRAINT IF EXISTS profiles_signup_source_check;
ALTER TABLE public.profiles ADD CONSTRAINT profiles_signup_source_check
  CHECK (signup_source IS NULL OR signup_source ~ '^[a-z0-9_-]{1,32}$');

-- signup_source records where a customer came from (?source=nfc|qr|whatsapp...). Set once, never rewritten.
CREATE OR REPLACE FUNCTION app_private.protect_signup_source() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF OLD.signup_source IS NOT NULL AND NEW.signup_source IS DISTINCT FROM OLD.signup_source AND NOT public.is_admin() THEN
    RAISE EXCEPTION 'Signup source cannot be changed';
  END IF;
  RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS profiles_protect_signup_source ON public.profiles;
CREATE TRIGGER profiles_protect_signup_source BEFORE UPDATE OF signup_source ON public.profiles
  FOR EACH ROW EXECUTE FUNCTION app_private.protect_signup_source();

CREATE OR REPLACE FUNCTION public.record_signup_source(p_source text) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501'; END IF;
  IF p_source IS NULL OR lower(p_source) !~ '^[a-z0-9_-]{1,32}$' THEN RETURN; END IF; -- ignore junk quietly
  UPDATE public.profiles SET signup_source = lower(p_source), updated_at = now()
   WHERE auth_user_id = auth.uid() AND signup_source IS NULL;
END $$;
REVOKE ALL ON FUNCTION public.record_signup_source(text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.record_signup_source(text) TO authenticated, service_role;

-- ───────────────────────── vehicles ─────────────────────────
-- The website asks for model + registration only. (The mobile form keeps collecting make.)
ALTER TABLE public.vehicles ALTER COLUMN make DROP NOT NULL;

ALTER TABLE public.vehicles
  ADD COLUMN IF NOT EXISTS registration_normalized text
  GENERATED ALWAYS AS (upper(regexp_replace(registration_number, '[^A-Za-z0-9]', '', 'g'))) STORED;

-- "MH12AB1234" and "MH 12 AB 1234" are the same plate. Create the unique index only if existing data allows it;
-- otherwise warn and expose the duplicates for cleanup instead of failing the whole migration.
DO $$
DECLARE dupes integer;
BEGIN
  SELECT count(*) INTO dupes FROM (
    SELECT 1 FROM public.vehicles WHERE is_active GROUP BY customer_profile_id, registration_normalized HAVING count(*) > 1
  ) d;
  IF dupes = 0 THEN
    CREATE UNIQUE INDEX IF NOT EXISTS ux_vehicles_customer_plate_active
      ON public.vehicles (customer_profile_id, registration_normalized) WHERE is_active;
  ELSE
    RAISE WARNING 'Skipped ux_vehicles_customer_plate_active: % customer(s) have the same plate saved twice. See view public.v_duplicate_vehicle_plates.', dupes;
  END IF;
END $$;
CREATE OR REPLACE VIEW public.v_duplicate_vehicle_plates WITH (security_invoker = true) AS
  SELECT customer_profile_id, registration_normalized, count(*) AS copies, array_agg(id) AS vehicle_ids
    FROM public.vehicles WHERE is_active GROUP BY 1, 2 HAVING count(*) > 1;
REVOKE ALL ON public.v_duplicate_vehicle_plates FROM anon, authenticated;

-- ───────────────────────── bookings ─────────────────────────
ALTER TABLE public.bookings
  ADD COLUMN IF NOT EXISTS reference_code text,
  ADD COLUMN IF NOT EXISTS source text NOT NULL DEFAULT 'mobile_app',
  ADD COLUMN IF NOT EXISTS price_cents integer,
  ADD COLUMN IF NOT EXISTS cancel_reason text,
  -- set when the worker has spoken to the customer; cleared when the wash is moved or the call is not picked up
  ADD COLUMN IF NOT EXISTS customer_confirmed_at timestamptz;

ALTER TABLE public.bookings DROP CONSTRAINT IF EXISTS bookings_source_check;
ALTER TABLE public.bookings ADD CONSTRAINT bookings_source_check
  CHECK (source IN ('mobile_app', 'website', 'admin', 'membership_schedule'));
ALTER TABLE public.bookings DROP CONSTRAINT IF EXISTS bookings_price_cents_check;
ALTER TABLE public.bookings ADD CONSTRAINT bookings_price_cents_check CHECK (price_cents IS NULL OR price_cents >= 0);

CREATE UNIQUE INDEX IF NOT EXISTS ux_bookings_reference_code ON public.bookings (reference_code) WHERE reference_code IS NOT NULL;

CREATE OR REPLACE FUNCTION app_private.set_booking_reference() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE tries int := 0;
BEGIN
  IF NEW.reference_code IS NULL THEN
    LOOP
      NEW.reference_code := app_private.gen_ref('WSH');
      EXIT WHEN NOT EXISTS (SELECT 1 FROM public.bookings WHERE reference_code = NEW.reference_code);
      tries := tries + 1;
      IF tries > 10 THEN RAISE EXCEPTION 'Could not allocate a booking reference'; END IF;
    END LOOP;
  END IF;
  RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION app_private.set_booking_reference() FROM PUBLIC, anon, authenticated;
DROP TRIGGER IF EXISTS bookings_set_reference ON public.bookings;
CREATE TRIGGER bookings_set_reference BEFORE INSERT ON public.bookings FOR EACH ROW EXECUTE FUNCTION app_private.set_booking_reference();

-- One live wash per vehicle per day (same rule the mobile app implicitly assumes). Skipped with a
-- warning if existing data already breaks it, so it can be cleaned up first.
DO $$
DECLARE dupes integer;
BEGIN
  SELECT count(*) INTO dupes FROM (
    SELECT 1 FROM public.bookings
     WHERE status IN ('pending', 'confirmed', 'worker_assigned', 'worker_called', 'in_progress')
     GROUP BY vehicle_id, scheduled_date HAVING count(*) > 1
  ) d;
  IF dupes = 0 THEN
    CREATE UNIQUE INDEX IF NOT EXISTS ux_bookings_vehicle_day_live ON public.bookings (vehicle_id, scheduled_date)
      WHERE status IN ('pending', 'confirmed', 'worker_assigned', 'worker_called', 'in_progress');
  ELSE
    RAISE WARNING 'Skipped ux_bookings_vehicle_day_live: % vehicle-day(s) already have more than one live booking. See view public.v_duplicate_live_bookings.', dupes;
  END IF;
END $$;
CREATE OR REPLACE VIEW public.v_duplicate_live_bookings WITH (security_invoker = true) AS
  SELECT vehicle_id, scheduled_date, count(*) AS bookings, array_agg(id) AS booking_ids
    FROM public.bookings
   WHERE status IN ('pending', 'confirmed', 'worker_assigned', 'worker_called', 'in_progress')
   GROUP BY 1, 2 HAVING count(*) > 1;
REVOKE ALL ON public.v_duplicate_live_bookings FROM anon, authenticated;

-- ───────────────────────── membership_requests ─────────────────────────
CREATE TABLE IF NOT EXISTS public.membership_requests (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  reference_code text NOT NULL UNIQUE DEFAULT app_private.gen_ref('MR'),
  customer_profile_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE RESTRICT,
  vehicle_id uuid NOT NULL REFERENCES public.vehicles(id) ON DELETE RESTRICT,
  address_id uuid REFERENCES public.customer_addresses(id) ON DELETE SET NULL,
  parking_location text,
  frequency_per_week smallint NOT NULL CHECK (frequency_per_week BETWEEN 1 AND 3),
  duration_months smallint NOT NULL CHECK (duration_months IN (1, 3, 6, 12)),
  weekly_pattern jsonb NOT NULL CHECK (jsonb_typeof(weekly_pattern) = 'array'),
  time_slot public.time_slot NOT NULL,
  target_completion_time text,
  start_date date NOT NULL,
  customer_notes text CHECK (customer_notes IS NULL OR char_length(customer_notes) <= 500),
  status text NOT NULL DEFAULT 'submitted'
    CHECK (status IN ('submitted', 'quoted', 'accepted', 'active', 'rejected', 'declined', 'expired', 'cancelled')),
  -- What the rate card says at request time. Admin-only: the customer is never shown a price before WASHO approves.
  system_quote jsonb,
  -- WASHO's decision.
  adjustment_cents integer NOT NULL DEFAULT 0,
  adjustment_reason text,
  quoted_amount_cents integer CHECK (quoted_amount_cents IS NULL OR quoted_amount_cents >= 100),
  quoted_breakdown jsonb,
  quote_expires_at timestamptz,
  reviewed_by_profile_id uuid REFERENCES public.profiles(id),
  reviewed_at timestamptz,
  rejection_reason text,
  accepted_at timestamptz,
  payment_id uuid,
  membership_id uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_membership_requests_customer ON public.membership_requests (customer_profile_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_membership_requests_status ON public.membership_requests (status, created_at);
-- One open request per vehicle keeps WASHO's review queue sane.
CREATE UNIQUE INDEX IF NOT EXISTS ux_membership_requests_open_per_vehicle
  ON public.membership_requests (vehicle_id) WHERE status IN ('submitted', 'quoted', 'accepted');

ALTER TABLE public.membership_requests ENABLE ROW LEVEL SECURITY;
-- Customers have NO direct table access: they read through functions that hide the price until it is approved.
DROP POLICY IF EXISTS membership_requests_admin_all ON public.membership_requests;
CREATE POLICY membership_requests_admin_all ON public.membership_requests FOR ALL TO authenticated
  USING (public.is_admin()) WITH CHECK (public.is_admin());
REVOKE ALL ON public.membership_requests FROM anon, authenticated;
GRANT SELECT ON public.membership_requests TO authenticated; -- RLS: admins only

-- ───────────────────────── memberships ─────────────────────────
ALTER TABLE public.memberships ADD COLUMN IF NOT EXISTS membership_request_id uuid REFERENCES public.membership_requests(id);
-- The specialist who normally serves this membership. Washes that are moved return to this worker's queue.
ALTER TABLE public.memberships ADD COLUMN IF NOT EXISTS assigned_worker_profile_id uuid REFERENCES public.profiles(id) ON DELETE SET NULL;
CREATE UNIQUE INDEX IF NOT EXISTS ux_memberships_request ON public.memberships (membership_request_id) WHERE membership_request_id IS NOT NULL;

-- ───────────────────────── payments ─────────────────────────
ALTER TABLE public.payments
  ADD COLUMN IF NOT EXISTS payment_kind text,
  ADD COLUMN IF NOT EXISTS intent jsonb,
  ADD COLUMN IF NOT EXISTS membership_request_id uuid REFERENCES public.membership_requests(id),
  ADD COLUMN IF NOT EXISTS receipt text,
  ADD COLUMN IF NOT EXISTS expires_at timestamptz,
  ADD COLUMN IF NOT EXISTS fulfilment_status text;

ALTER TABLE public.payments DROP CONSTRAINT IF EXISTS payments_payment_kind_check;
ALTER TABLE public.payments ADD CONSTRAINT payments_payment_kind_check CHECK (payment_kind IS NULL OR payment_kind IN ('on_demand', 'membership'));
ALTER TABLE public.payments DROP CONSTRAINT IF EXISTS payments_fulfilment_status_check;
ALTER TABLE public.payments ADD CONSTRAINT payments_fulfilment_status_check
  CHECK (fulfilment_status IS NULL OR fulfilment_status IN ('pending', 'fulfilled', 'unfulfilled'));

-- A paid payment must point at exactly one thing it bought. Exceptions: money was taken but the
-- slot/dates were no longer available -> 'unfulfilled' (which always gets a refund request), and a
-- 'failed' (abandoned/superseded) payment, which never bought anything.
ALTER TABLE public.payments DROP CONSTRAINT IF EXISTS payments_booking_id_membership_id_check;
ALTER TABLE public.payments ADD CONSTRAINT payments_booking_id_membership_id_check CHECK (
     (status = 'pending' AND booking_id IS NULL AND membership_id IS NULL)
  OR (status <> 'pending' AND ((booking_id IS NOT NULL) <> (membership_id IS NOT NULL)))
  OR (status <> 'pending' AND fulfilment_status = 'unfulfilled' AND booking_id IS NULL AND membership_id IS NULL)
  OR (status = 'failed' AND booking_id IS NULL AND membership_id IS NULL)
);

-- Idempotency anchors: one payment row per Razorpay order, and one captured payment is never applied twice.
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.payments WHERE provider_order_id IS NOT NULL GROUP BY provider_order_id HAVING count(*) > 1) THEN
    CREATE UNIQUE INDEX IF NOT EXISTS ux_payments_provider_order ON public.payments (provider_order_id) WHERE provider_order_id IS NOT NULL;
  ELSE
    RAISE WARNING 'Skipped ux_payments_provider_order: duplicate provider_order_id values exist';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.payments WHERE provider_payment_id IS NOT NULL GROUP BY provider_payment_id HAVING count(*) > 1) THEN
    CREATE UNIQUE INDEX IF NOT EXISTS ux_payments_provider_payment ON public.payments (provider_payment_id) WHERE provider_payment_id IS NOT NULL;
  ELSE
    RAISE WARNING 'Skipped ux_payments_provider_payment: duplicate provider_payment_id values exist';
  END IF;
END $$;
CREATE INDEX IF NOT EXISTS idx_payments_membership_request ON public.payments (membership_request_id) WHERE membership_request_id IS NOT NULL;

ALTER TABLE public.membership_requests DROP CONSTRAINT IF EXISTS membership_requests_payment_fk;
ALTER TABLE public.membership_requests ADD CONSTRAINT membership_requests_payment_fk FOREIGN KEY (payment_id) REFERENCES public.payments(id);
ALTER TABLE public.membership_requests DROP CONSTRAINT IF EXISTS membership_requests_membership_fk;
ALTER TABLE public.membership_requests ADD CONSTRAINT membership_requests_membership_fk FOREIGN KEY (membership_id) REFERENCES public.memberships(id);

-- ───────────────────────── website_leads (legacy, read-only) ─────────────────────────
-- The marketing site's old lead form captured these before the web app existed. Kept, not deleted.
CREATE TABLE IF NOT EXISTS public.website_leads (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  legacy_id integer UNIQUE,                       -- id in the old Render database, for idempotent import
  name text NOT NULL,
  email text,
  mobile text NOT NULL,
  vehicle_type text,
  vehicle_model text,
  vehicle_registration_number text,
  location text,
  flat_number text,
  preferred_service text,
  status text,
  source text,
  legacy_payment_image_url text,                  -- path on the old server; the image itself is NOT migrated
  legacy_created_at timestamptz,
  imported_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_website_leads_mobile ON public.website_leads (mobile);
ALTER TABLE public.website_leads ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS website_leads_admin_read ON public.website_leads;
CREATE POLICY website_leads_admin_read ON public.website_leads FOR SELECT TO authenticated USING (public.is_admin());
REVOKE ALL ON public.website_leads FROM anon, authenticated;
GRANT SELECT ON public.website_leads TO authenticated; -- RLS: admins only
GRANT INSERT, SELECT ON public.website_leads TO service_role;

-- ───────────────────────── washo_api: the website server's database role ─────────────────────────
-- Not a superuser, not service_role. It can run the specific functions granted to it, and (inside one
-- transaction) act as a signed-in customer via SET LOCAL ROLE authenticated, so RLS and auth.uid()
-- behave exactly as they do for the mobile app. An operator must give it a password out of band:
--   ALTER ROLE washo_api WITH LOGIN PASSWORD '<random>';
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'washo_api') THEN
    CREATE ROLE washo_api NOLOGIN NOINHERIT NOBYPASSRLS;
  END IF;
END $$;
GRANT authenticated TO washo_api;
GRANT anon TO washo_api;            -- the public catalogue is read as anon
GRANT USAGE ON SCHEMA public TO washo_api;
GRANT USAGE ON SCHEMA app_private TO washo_api;

-- ═════════════ 20261004000004_membership_request_flow.sql ═════════════
-- 20261004000004_membership_request_flow.sql
-- SAFE / additive. The custom membership flow up to (not including) payment:
--
--   customer: create_membership_request  ->  WASHO: admin_review_membership_request (quote | reject)
--   customer: accept_membership_quote (creates a PENDING payment)  or  decline_membership_quote
--
-- Rules enforced here, in the database, for every client (website and mobile):
--   * the customer is never shown a price before WASHO has approved one
--   * a quote is a snapshot that expires (pricing_settings.quote_validity_days)
--   * any WASHO adjustment is a labelled line with a reason; nothing is hidden
--   * accepting a quote creates a pending payment ONLY; no membership exists until payment is verified

-- ───────────────────────── create ─────────────────────────
CREATE OR REPLACE FUNCTION public.create_membership_request(
  p_vehicle_id uuid,
  p_weekly_pattern jsonb,
  p_duration_months integer,
  p_time_slot public.time_slot,
  p_start_date date,
  p_address_id uuid DEFAULT NULL,
  p_parking_location text DEFAULT NULL,
  p_customer_notes text DEFAULT NULL,
  p_target_completion_time text DEFAULT NULL
) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_profile uuid := public.current_profile_id();
  v_vehicle public.vehicles%ROWTYPE;
  v_addr uuid := p_address_id;
  v_pattern jsonb;
  v_quote jsonb;
  v_id uuid;
  v_today date := (now() AT TIME ZONE 'Asia/Kolkata')::date;
BEGIN
  IF v_profile IS NULL OR NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = v_profile AND role = 'customer') THEN
    RAISE EXCEPTION 'Customer profile not found' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_vehicle FROM public.vehicles WHERE id = p_vehicle_id AND customer_profile_id = v_profile AND is_active;
  IF NOT FOUND THEN RAISE EXCEPTION 'Vehicle not found'; END IF;

  IF v_addr IS NULL THEN v_addr := v_vehicle.address_id; END IF;
  IF v_addr IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.customer_addresses WHERE id = v_addr AND customer_profile_id = v_profile) THEN
    RAISE EXCEPTION 'Address not found';
  END IF;

  IF p_start_date IS NULL OR p_start_date < v_today + app_private.setting('membership_min_lead_days') THEN
    RAISE EXCEPTION 'Your membership can start from % at the earliest', v_today + app_private.setting('membership_min_lead_days');
  END IF;

  -- Validates the pattern, duration and vehicle rules; raises a customer-readable message if anything is off.
  v_quote := app_private.compute_membership_quote(v_vehicle.vehicle_type, p_weekly_pattern, p_duration_months);

  -- Store the pattern in a canonical, weekday-ordered form with integer weekdays.
  SELECT jsonb_agg(jsonb_build_object('weekday', (e->>'weekday')::int, 'kind', e->>'kind') ORDER BY (e->>'weekday')::int)
    INTO v_pattern FROM jsonb_array_elements(p_weekly_pattern) e;

  BEGIN
    INSERT INTO public.membership_requests (
      customer_profile_id, vehicle_id, address_id, parking_location, frequency_per_week, duration_months,
      weekly_pattern, time_slot, target_completion_time, start_date, customer_notes, system_quote
    ) VALUES (
      v_profile, p_vehicle_id, v_addr, COALESCE(NULLIF(trim(p_parking_location), ''), v_vehicle.parking_location),
      jsonb_array_length(v_pattern), p_duration_months, v_pattern, p_time_slot, p_target_completion_time,
      p_start_date, NULLIF(trim(p_customer_notes), ''), v_quote
    ) RETURNING id INTO v_id;
  EXCEPTION WHEN unique_violation THEN
    RAISE EXCEPTION 'You already have a membership request in progress for this vehicle';
  END;

  PERFORM app_private.audit('membership_request', v_id, 'membership_requested',
    jsonb_build_object('frequency_per_week', jsonb_array_length(v_pattern), 'duration_months', p_duration_months));
  RETURN v_id;
END $$;

-- ───────────────────────── read (customer): price hidden until WASHO approves ─────────────────────────
CREATE OR REPLACE FUNCTION public.my_membership_requests()
RETURNS TABLE (
  id uuid, reference_code text, status text, vehicle_id uuid, frequency_per_week smallint, duration_months smallint,
  weekly_pattern jsonb, time_slot public.time_slot, start_date date, customer_notes text,
  quoted_amount_cents integer, quoted_breakdown jsonb, quote_expires_at timestamptz,
  rejection_reason text, payment_id uuid, membership_id uuid, created_at timestamptz
) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT r.id, r.reference_code,
         CASE WHEN r.status = 'quoted' AND r.quote_expires_at < now() THEN 'expired' ELSE r.status END,
         r.vehicle_id, r.frequency_per_week, r.duration_months, r.weekly_pattern, r.time_slot, r.start_date, r.customer_notes,
         -- price fields exist only once WASHO has approved a price
         CASE WHEN r.status IN ('quoted', 'accepted', 'active') THEN r.quoted_amount_cents END,
         CASE WHEN r.status IN ('quoted', 'accepted', 'active') THEN r.quoted_breakdown END,
         CASE WHEN r.status = 'quoted' THEN r.quote_expires_at END,
         r.rejection_reason, r.payment_id, r.membership_id, r.created_at
    FROM public.membership_requests r
   WHERE r.customer_profile_id = public.current_profile_id()
   ORDER BY r.created_at DESC;
$$;

-- ───────────────────────── admin: review ─────────────────────────
CREATE OR REPLACE FUNCTION public.admin_list_membership_requests(p_status text DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'Unauthorized: admin access required' USING ERRCODE = '42501'; END IF;
  RETURN COALESCE((
    SELECT jsonb_agg(jsonb_build_object(
      'id', r.id, 'reference_code', r.reference_code, 'status', r.status,
      'customer', jsonb_build_object('profile_id', p.id, 'name', p.full_name, 'phone', p.phone),
      'vehicle', jsonb_build_object('id', v.id, 'type', v.vehicle_type, 'model', v.model, 'registration_number', v.registration_number),
      'address', CASE WHEN a.id IS NULL THEN NULL ELSE jsonb_build_object('society', a.society_name, 'block', a.building_block, 'flat', a.flat_number, 'parking', COALESCE(r.parking_location, a.parking_location)) END,
      'frequency_per_week', r.frequency_per_week, 'duration_months', r.duration_months, 'weekly_pattern', r.weekly_pattern,
      'time_slot', r.time_slot, 'start_date', r.start_date, 'customer_notes', r.customer_notes,
      'system_quote', r.system_quote, 'adjustment_cents', r.adjustment_cents, 'adjustment_reason', r.adjustment_reason,
      'quoted_amount_cents', r.quoted_amount_cents, 'quote_expires_at', r.quote_expires_at,
      'rejection_reason', r.rejection_reason, 'created_at', r.created_at
    ) ORDER BY (r.status = 'submitted') DESC, r.created_at DESC)
      FROM public.membership_requests r
      JOIN public.profiles p ON p.id = r.customer_profile_id
      JOIN public.vehicles v ON v.id = r.vehicle_id
      LEFT JOIN public.customer_addresses a ON a.id = r.address_id
     WHERE p_status IS NULL OR r.status = p_status), '[]'::jsonb);
END $$;

CREATE OR REPLACE FUNCTION public.admin_review_membership_request(
  p_request_id uuid,
  p_action text,
  p_adjustment_cents integer DEFAULT 0,
  p_adjustment_reason text DEFAULT NULL,
  p_rejection_reason text DEFAULT NULL
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_req public.membership_requests%ROWTYPE;
  v_vehicle_type public.vehicle_type;
  v_quote jsonb;
  v_final bigint;
  v_breakdown jsonb;
  v_expires timestamptz;
  v_admin uuid := public.current_profile_id();
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'Unauthorized: admin access required' USING ERRCODE = '42501'; END IF;

  SELECT * INTO v_req FROM public.membership_requests WHERE id = p_request_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Request not found'; END IF;

  IF p_action = 'reject' THEN
    IF v_req.status NOT IN ('submitted', 'quoted') THEN RAISE EXCEPTION 'This request can no longer be rejected (%).', v_req.status; END IF;
    IF p_rejection_reason IS NULL OR char_length(trim(p_rejection_reason)) < 3 THEN RAISE EXCEPTION 'Please give the customer a reason'; END IF;
    UPDATE public.membership_requests
       SET status = 'rejected', rejection_reason = trim(p_rejection_reason), reviewed_by_profile_id = v_admin, reviewed_at = now(), updated_at = now()
     WHERE id = p_request_id;
    PERFORM app_private.audit('membership_request', p_request_id, 'membership_rejected', jsonb_build_object('reason', p_rejection_reason));
    RETURN jsonb_build_object('request_id', p_request_id, 'status', 'rejected');
  END IF;

  IF p_action <> 'quote' THEN RAISE EXCEPTION 'Action must be quote or reject'; END IF;
  IF v_req.status NOT IN ('submitted', 'quoted') THEN RAISE EXCEPTION 'This request can no longer be quoted (%).', v_req.status; END IF;

  IF COALESCE(p_adjustment_cents, 0) <> 0 AND (p_adjustment_reason IS NULL OR char_length(trim(p_adjustment_reason)) < 5) THEN
    RAISE EXCEPTION 'An adjustment needs a reason the customer will see';
  END IF;

  -- Re-price from today's rate card (rates or discounts may have changed since the customer asked).
  SELECT vehicle_type INTO v_vehicle_type FROM public.vehicles WHERE id = v_req.vehicle_id;
  v_quote := app_private.compute_membership_quote(v_vehicle_type, v_req.weekly_pattern, v_req.duration_months);

  v_final := (v_quote->>'final_cents')::bigint + COALESCE(p_adjustment_cents, 0);
  IF v_final < 100 THEN RAISE EXCEPTION 'The final price must be at least ₹1'; END IF;

  v_breakdown := v_quote || jsonb_build_object(
    'adjustment', jsonb_build_object('cents', COALESCE(p_adjustment_cents, 0), 'reason', NULLIF(trim(p_adjustment_reason), '')),
    'final_cents', v_final);
  v_expires := now() + make_interval(days => app_private.setting('quote_validity_days'));

  UPDATE public.membership_requests
     SET status = 'quoted', system_quote = v_quote, adjustment_cents = COALESCE(p_adjustment_cents, 0),
         adjustment_reason = NULLIF(trim(p_adjustment_reason), ''), quoted_amount_cents = v_final::int,
         quoted_breakdown = v_breakdown, quote_expires_at = v_expires, reviewed_by_profile_id = v_admin, reviewed_at = now(), updated_at = now()
   WHERE id = p_request_id;

  PERFORM app_private.audit('membership_request', p_request_id, 'membership_quoted',
    jsonb_build_object('system_final_cents', (v_quote->>'final_cents')::bigint, 'adjustment_cents', COALESCE(p_adjustment_cents, 0),
                       'reason', p_adjustment_reason, 'quoted_amount_cents', v_final, 'expires_at', v_expires));
  RETURN jsonb_build_object('request_id', p_request_id, 'status', 'quoted', 'quoted_amount_cents', v_final, 'quote_expires_at', v_expires);
END $$;

-- ───────────────────────── customer: accept / decline ─────────────────────────
-- Accepting creates a PENDING payment and nothing else. The Razorpay order is created by the server for
-- exactly this amount and attached afterwards. No membership exists until settle_payment() verifies the money.
CREATE OR REPLACE FUNCTION public.accept_membership_quote(p_request_id uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_profile uuid := public.current_profile_id();
  v_req public.membership_requests%ROWTYPE;
  v_pay public.payments%ROWTYPE;
  v_minutes integer := app_private.setting('payment_intent_minutes');
BEGIN
  SELECT * INTO v_req FROM public.membership_requests WHERE id = p_request_id AND customer_profile_id = v_profile FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Request not found'; END IF;

  IF v_req.status = 'quoted' AND v_req.quote_expires_at < now() THEN
    UPDATE public.membership_requests SET status = 'expired', updated_at = now() WHERE id = p_request_id;
    RAISE EXCEPTION 'This quote has expired. Please ask WASHO for a new one.';
  END IF;
  IF v_req.status NOT IN ('quoted', 'accepted') THEN
    RAISE EXCEPTION 'This request is not waiting for your approval (%).', v_req.status;
  END IF;

  -- Retrying payment: reuse the open payment while it is fresh.
  IF v_req.status = 'accepted' AND v_req.payment_id IS NOT NULL THEN
    SELECT * INTO v_pay FROM public.payments WHERE id = v_req.payment_id FOR UPDATE;
    IF v_pay.status = 'pending' AND v_pay.expires_at > now() AND v_pay.amount_cents = v_req.quoted_amount_cents THEN
      RETURN jsonb_build_object('payment_id', v_pay.id, 'amount_cents', v_pay.amount_cents, 'currency', 'INR',
                                'receipt', v_pay.receipt, 'provider_order_id', v_pay.provider_order_id, 'expires_at', v_pay.expires_at);
    END IF;
    IF v_pay.status = 'pending' THEN
      UPDATE public.payments SET status = 'failed', updated_at = now() WHERE id = v_pay.id; -- superseded
    END IF;
  END IF;

  INSERT INTO public.payments (customer_profile_id, amount_cents, currency, provider, status, payment_kind,
                               membership_request_id, receipt, expires_at, fulfilment_status, intent)
  VALUES (v_profile, v_req.quoted_amount_cents, 'INR', 'razorpay', 'pending', 'membership',
          p_request_id, v_req.reference_code, now() + make_interval(mins => v_minutes), 'pending',
          jsonb_build_object('kind', 'membership_request', 'request_id', p_request_id))
  RETURNING * INTO v_pay;

  UPDATE public.membership_requests
     SET status = 'accepted', accepted_at = COALESCE(accepted_at, now()), payment_id = v_pay.id, updated_at = now()
   WHERE id = p_request_id;

  PERFORM app_private.audit('membership_request', p_request_id, 'membership_accepted',
    jsonb_build_object('payment_id', v_pay.id, 'amount_cents', v_pay.amount_cents));
  RETURN jsonb_build_object('payment_id', v_pay.id, 'amount_cents', v_pay.amount_cents, 'currency', 'INR',
                            'receipt', v_pay.receipt, 'provider_order_id', NULL, 'expires_at', v_pay.expires_at);
END $$;

CREATE OR REPLACE FUNCTION public.decline_membership_quote(p_request_id uuid) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE v_profile uuid := public.current_profile_id();
BEGIN
  UPDATE public.membership_requests SET status = 'declined', updated_at = now()
   WHERE id = p_request_id AND customer_profile_id = v_profile AND status = 'quoted';
  IF NOT FOUND THEN RAISE EXCEPTION 'This quote can no longer be declined'; END IF;
  PERFORM app_private.audit('membership_request', p_request_id, 'membership_declined');
END $$;

-- Housekeeping, run by a scheduled job (pg_cron) or the API: quotes nobody accepted in time.
CREATE OR REPLACE FUNCTION app_private.expire_membership_quotes() RETURNS integer
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE n integer;
BEGIN
  UPDATE public.membership_requests SET status = 'expired', updated_at = now()
   WHERE status = 'quoted' AND quote_expires_at < now();
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END $$;

-- ───────────────────────── grants ─────────────────────────
REVOKE ALL ON FUNCTION public.create_membership_request(uuid, jsonb, integer, public.time_slot, date, uuid, text, text, text) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.my_membership_requests() FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.admin_list_membership_requests(text) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.admin_review_membership_request(uuid, text, integer, text, text) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.accept_membership_quote(uuid) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.decline_membership_quote(uuid) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION app_private.expire_membership_quotes() FROM PUBLIC, anon, authenticated;

GRANT EXECUTE ON FUNCTION public.create_membership_request(uuid, jsonb, integer, public.time_slot, date, uuid, text, text, text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.my_membership_requests() TO authenticated;
GRANT EXECUTE ON FUNCTION public.admin_list_membership_requests(text) TO authenticated;      -- is_admin() inside
GRANT EXECUTE ON FUNCTION public.admin_review_membership_request(uuid, text, integer, text, text) TO authenticated; -- is_admin() inside
GRANT EXECUTE ON FUNCTION public.accept_membership_quote(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.decline_membership_quote(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION app_private.expire_membership_quotes() TO service_role, washo_api;

-- ═════════════ 20261004000005_payment_intents_and_settlement.sql ═════════════
-- 20261004000005_payment_intents_and_settlement.sql
-- SAFE / additive. The single, database-enforced payment pipeline for on-demand washes and memberships.
--
--   1. create_booking_payment_intent()   customer: validates everything, computes the amount ON THE SERVER,
--                                         stores the validated order as an immutable "intent". Creates NO booking.
--   2. attach_provider_order()            server: records the Razorpay order id for that exact amount.
--   3. settle_payment()                   server: called by the verify route AND the webhook. Checks ownership,
--                                         amount, currency, capture status and idempotency; then builds the
--                                         booking / membership FROM THE STORED INTENT (never from client input).
--
-- Guarantees:
--   * nothing is activated, scheduled or confirmed without a verified, captured payment of the exact amount
--   * calling settle_payment twice (browser verify + webhook) does the work once
--   * if money arrived but the order can no longer be fulfilled, the payment is kept as 'paid/unfulfilled' and a
--     refund request is created automatically; the transaction never silently rolls the payment record back
--   * every rejection and every settlement is written to audit_events

-- ───────────────────────── helpers ─────────────────────────
-- Slot start times (IST). Morning 07:00, Afternoon 12:00, Night 19:00.
CREATE OR REPLACE FUNCTION app_private.slot_start(p_date date, p_slot public.time_slot) RETURNS timestamptz
LANGUAGE sql IMMUTABLE AS $$
  SELECT ((p_date::timestamp + CASE p_slot WHEN 'morning' THEN interval '7 hours' WHEN 'afternoon' THEN interval '12 hours' ELSE interval '19 hours' END)
          AT TIME ZONE 'Asia/Kolkata');
$$;

-- A vehicle may be washed once a day. True if it already has a live booking on that date.
CREATE OR REPLACE FUNCTION app_private.vehicle_has_live_booking(p_vehicle_id uuid, p_date date) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT EXISTS (SELECT 1 FROM public.bookings WHERE vehicle_id = p_vehicle_id AND scheduled_date = p_date
                   AND status IN ('pending', 'confirmed', 'worker_assigned', 'worker_called', 'in_progress'));
$$;

-- ───────────────────────── 1. on-demand payment intent ─────────────────────────
CREATE OR REPLACE FUNCTION public.create_booking_payment_intent(
  p_vehicle_id uuid,
  p_service_id uuid,
  p_scheduled_date date,
  p_time_slot public.time_slot,
  p_address_id uuid DEFAULT NULL,
  p_parking_location text DEFAULT NULL,
  p_target_completion_time text DEFAULT NULL,
  p_source text DEFAULT 'website'
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_profile uuid := public.current_profile_id();
  v_vehicle public.vehicles%ROWTYPE;
  v_service public.services%ROWTYPE;
  v_addr uuid := p_address_id;
  v_price integer;
  v_pay public.payments%ROWTYPE;
BEGIN
  IF v_profile IS NULL OR NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = v_profile AND role = 'customer') THEN
    RAISE EXCEPTION 'Customer profile not found' USING ERRCODE = '42501';
  END IF;
  IF p_source NOT IN ('mobile_app', 'website') THEN RAISE EXCEPTION 'Unknown booking source'; END IF;

  SELECT * INTO v_vehicle FROM public.vehicles WHERE id = p_vehicle_id AND customer_profile_id = v_profile AND is_active;
  IF NOT FOUND THEN RAISE EXCEPTION 'Vehicle not found'; END IF;

  SELECT * INTO v_service FROM public.services WHERE id = p_service_id AND is_active;
  IF NOT FOUND THEN RAISE EXCEPTION 'Service not found'; END IF;
  IF NOT (v_service.vehicle_type = v_vehicle.vehicle_type OR (v_vehicle.vehicle_type = 'suv' AND v_service.vehicle_type = 'car')) THEN
    RAISE EXCEPTION 'This service is not available for your vehicle';
  END IF;

  IF v_addr IS NULL THEN v_addr := v_vehicle.address_id; END IF;
  IF v_addr IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.customer_addresses WHERE id = v_addr AND customer_profile_id = v_profile) THEN
    RAISE EXCEPTION 'Address not found';
  END IF;

  IF p_scheduled_date IS NULL OR app_private.slot_start(p_scheduled_date, p_time_slot)
       < now() + make_interval(hours => app_private.setting('on_demand_min_lead_hours')) THEN
    RAISE EXCEPTION 'That slot starts too soon. Please choose a later one.';
  END IF;
  IF app_private.vehicle_has_live_booking(p_vehicle_id, p_scheduled_date) THEN
    RAISE EXCEPTION 'This vehicle already has a wash booked that day';
  END IF;

  v_price := app_private.unit_price_cents(v_service.id, v_vehicle.vehicle_type);
  IF v_price IS NULL OR v_price < 100 THEN RAISE EXCEPTION 'No price is set for this service'; END IF;

  INSERT INTO public.payments (customer_profile_id, amount_cents, currency, provider, status, payment_kind, receipt, expires_at, fulfilment_status, intent)
  VALUES (v_profile, v_price, 'INR', 'razorpay', 'pending', 'on_demand', app_private.gen_ref('INT'),
          now() + make_interval(mins => app_private.setting('payment_intent_minutes')), 'pending',
          jsonb_build_object('kind', 'on_demand', 'vehicle_id', p_vehicle_id, 'service_id', p_service_id,
                             'scheduled_date', p_scheduled_date, 'time_slot', p_time_slot, 'address_id', v_addr,
                             'parking_location', COALESCE(NULLIF(trim(p_parking_location), ''), v_vehicle.parking_location),
                             'target_completion_time', p_target_completion_time, 'source', p_source, 'unit_price_cents', v_price))
  RETURNING * INTO v_pay;

  RETURN jsonb_build_object('payment_id', v_pay.id, 'amount_cents', v_pay.amount_cents, 'currency', 'INR',
                            'receipt', v_pay.receipt, 'expires_at', v_pay.expires_at);
END $$;

-- ───────────────────────── 2. attach the Razorpay order ─────────────────────────
CREATE OR REPLACE FUNCTION app_private.attach_provider_order(p_payment_id uuid, p_provider_order_id text, p_expected_profile_id uuid DEFAULT NULL)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE v_pay public.payments%ROWTYPE;
BEGIN
  SELECT * INTO v_pay FROM public.payments WHERE id = p_payment_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Payment not found'; END IF;
  IF p_expected_profile_id IS NOT NULL AND v_pay.customer_profile_id <> p_expected_profile_id THEN
    RAISE EXCEPTION 'Payment not found';
  END IF;
  IF v_pay.status <> 'pending' THEN RAISE EXCEPTION 'This payment is no longer open'; END IF;
  IF v_pay.provider_order_id IS NOT NULL AND v_pay.provider_order_id <> p_provider_order_id THEN
    RAISE EXCEPTION 'This payment already has an order';
  END IF;
  UPDATE public.payments SET provider_order_id = p_provider_order_id, provider = 'razorpay', updated_at = now() WHERE id = p_payment_id;
END $$;

-- ───────────────────────── fulfilment: on-demand booking ─────────────────────────
CREATE OR REPLACE FUNCTION app_private.fulfil_on_demand(p_pay public.payments) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  i jsonb := p_pay.intent;
  v_vehicle public.vehicles%ROWTYPE;
  v_service public.services%ROWTYPE;
  v_date date := (i->>'scheduled_date')::date;
  v_slot public.time_slot := (i->>'time_slot')::public.time_slot;
  v_booking uuid;
BEGIN
  SELECT * INTO v_vehicle FROM public.vehicles WHERE id = (i->>'vehicle_id')::uuid AND customer_profile_id = p_pay.customer_profile_id AND is_active;
  IF NOT FOUND THEN RAISE EXCEPTION 'vehicle_unavailable'; END IF;
  SELECT * INTO v_service FROM public.services WHERE id = (i->>'service_id')::uuid AND is_active;
  IF NOT FOUND THEN RAISE EXCEPTION 'service_unavailable'; END IF;
  IF v_date < (now() AT TIME ZONE 'Asia/Kolkata')::date THEN RAISE EXCEPTION 'date_passed'; END IF;
  IF app_private.vehicle_has_live_booking(v_vehicle.id, v_date) THEN RAISE EXCEPTION 'vehicle_already_booked'; END IF;

  INSERT INTO public.bookings (customer_profile_id, vehicle_id, service_id, booking_type, scheduled_date, time_slot, status,
                               notes, address_id, parking_location, target_completion_time, source, price_cents)
  VALUES (p_pay.customer_profile_id, v_vehicle.id, v_service.id, 'on_demand', v_date, v_slot, 'confirmed',
          COALESCE('Target Completion: ' || NULLIF(i->>'target_completion_time', '') || E'\n' || NULLIF(i->>'parking_location', ''),
                   NULLIF(i->>'parking_location', ''), 'Doorstep on-demand wash'),
          NULLIF(i->>'address_id', '')::uuid, NULLIF(i->>'parking_location', ''), NULLIF(i->>'target_completion_time', ''),
          COALESCE(i->>'source', 'website'), p_pay.amount_cents)
  RETURNING id INTO v_booking;

  INSERT INTO public.booking_events (booking_id, event_type, actor_profile_id, event_metadata) VALUES
    (v_booking, 'booking_created', p_pay.customer_profile_id, jsonb_build_object('booking_type', 'on_demand', 'source', i->>'source', 'payment_id', p_pay.id)),
    (v_booking, 'payment_received', NULL, jsonb_build_object('payment_id', p_pay.id, 'provider', 'razorpay', 'amount_cents', p_pay.amount_cents));

  INSERT INTO public.notifications (profile_id, category, title, body, reference_id) VALUES
    (p_pay.customer_profile_id, 'booking_confirmed', 'Booking confirmed',
     v_service.name || ' on ' || to_char(v_date, 'Dy DD Mon') || ' (' || v_slot || ')', v_booking),
    (p_pay.customer_profile_id, 'payment_successful', 'Payment received', 'We received your payment. Thank you!', v_booking);
  RETURN v_booking;
END $$;

-- ───────────────────────── fulfilment: membership + generated washes ─────────────────────────
CREATE OR REPLACE FUNCTION app_private.fulfil_membership(p_pay public.payments) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_req public.membership_requests%ROWTYPE;
  v_vehicle public.vehicles%ROWTYPE;
  v_b jsonb;
  v_today date := (now() AT TIME ZONE 'Asia/Kolkata')::date;
  v_start date;
  v_start_at timestamptz;
  v_end_at timestamptz;
  v_weeks integer := app_private.setting('weeks_per_month');
  v_total integer;
  v_subtotal integer;
  v_total_discount integer;
  v_adj integer;
  v_base integer;
  v_discount integer;
  v_membership uuid;
  v_schedule uuid;
  v_occ uuid;
  v_booking uuid;
  v_created integer := 0;
  v_skipped integer := 0;
  v_date date;
  v_kind text;
  v_service uuid;
  line jsonb;
BEGIN
  SELECT * INTO v_req FROM public.membership_requests
   WHERE id = (p_pay.intent->>'request_id')::uuid AND payment_id = p_pay.id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'request_not_found'; END IF;
  IF v_req.status <> 'accepted' THEN RAISE EXCEPTION 'request_not_accepted'; END IF;
  IF v_req.customer_profile_id <> p_pay.customer_profile_id THEN RAISE EXCEPTION 'request_owner_mismatch'; END IF;
  IF v_req.quoted_amount_cents IS DISTINCT FROM p_pay.amount_cents THEN RAISE EXCEPTION 'request_amount_mismatch'; END IF;

  SELECT * INTO v_vehicle FROM public.vehicles WHERE id = v_req.vehicle_id AND customer_profile_id = v_req.customer_profile_id AND is_active;
  IF NOT FOUND THEN RAISE EXCEPTION 'vehicle_unavailable'; END IF;

  v_b := v_req.quoted_breakdown;
  v_subtotal := (v_b->>'subtotal_cents')::integer;
  v_total_discount := (v_b->>'total_discount_cents')::integer;
  v_adj := COALESCE((v_b->'adjustment'->>'cents')::integer, 0);
  v_base := v_subtotal + GREATEST(v_adj, 0);          -- a surcharge is part of the base
  v_discount := v_total_discount + GREATEST(-v_adj, 0); -- an extra WASHO discount is part of the discount
  IF v_base - v_discount <> v_req.quoted_amount_cents THEN RAISE EXCEPTION 'breakdown_does_not_add_up'; END IF;

  -- Never start in the past if the customer paid late.
  v_start := GREATEST(v_req.start_date, v_today + app_private.setting('membership_min_lead_days'));
  v_start_at := (v_start::timestamp AT TIME ZONE 'Asia/Kolkata');
  v_end_at := v_start_at + make_interval(months => v_req.duration_months) - interval '1 day'; -- same formula the table trigger enforces
  v_total := v_req.frequency_per_week * v_weeks * v_req.duration_months;

  INSERT INTO public.memberships (customer_profile_id, status, duration_months, quantity_per_period, start_at, end_at,
                                  base_amount_cents, discount_amount_cents, final_amount_cents, pricing_snapshot, membership_request_id)
  VALUES (v_req.customer_profile_id, 'active', v_req.duration_months, v_req.frequency_per_week * v_weeks, v_start_at, v_end_at,
          v_base, v_discount, v_req.quoted_amount_cents,
          v_b || jsonb_build_object('request_id', v_req.id, 'payment_id', p_pay.id, 'effective_start_date', v_start, 'requested_start_date', v_req.start_date),
          v_req.id)
  RETURNING id INTO v_membership;

  FOR line IN SELECT * FROM jsonb_array_elements(v_b->'lines') LOOP
    INSERT INTO public.membership_services (membership_id, service_id, vehicle_id, quantity_per_period)
    VALUES (v_membership, (line->>'service_id')::uuid, v_vehicle.id, (line->>'per_week')::integer * v_weeks);
  END LOOP;

  INSERT INTO public.membership_schedules (membership_id, schedule_name, timezone_name, schedule_pattern, is_active)
  VALUES (v_membership, 'default', 'Asia/Kolkata',
          jsonb_build_object('weekly_pattern', v_req.weekly_pattern, 'time_slot', v_req.time_slot,
                             'start_date', v_start, 'target_completion_time', v_req.target_completion_time),
          true)
  RETURNING id INTO v_schedule;

  -- Lay out exactly v_total washes on the customer's chosen weekdays. A date that already has a live
  -- wash for this vehicle is skipped (the wash moves to the next pattern day), so the customer always gets
  -- every wash they paid for.
  v_date := v_start;
  WHILE v_created < v_total LOOP
    IF v_date > v_end_at::date THEN RAISE EXCEPTION 'schedule_does_not_fit'; END IF;
    SELECT p->>'kind' INTO v_kind FROM jsonb_array_elements(v_req.weekly_pattern) p
     WHERE (p->>'weekday')::int = extract(dow FROM v_date)::int;
    IF v_kind IS NOT NULL THEN
      IF app_private.vehicle_has_live_booking(v_vehicle.id, v_date) THEN
        v_skipped := v_skipped + 1;
      ELSE
        SELECT service_id INTO v_service FROM public.membership_service_options WHERE vehicle_type = v_vehicle.vehicle_type AND wash_kind = v_kind;
        INSERT INTO public.membership_schedule_occurrences (membership_schedule_id, original_date, "current_date", time_slot, status)
        VALUES (v_schedule, v_date, v_date, v_req.time_slot, 'scheduled') RETURNING id INTO v_occ;
        INSERT INTO public.bookings (customer_profile_id, vehicle_id, service_id, membership_id, membership_schedule_occurrence_id, booking_type,
                                     scheduled_date, time_slot, status, notes, address_id, parking_location, target_completion_time, source)
        VALUES (v_req.customer_profile_id, v_vehicle.id, v_service, v_membership, v_occ, 'membership', v_date, v_req.time_slot, 'confirmed',
                'Membership wash', v_req.address_id, v_req.parking_location, v_req.target_completion_time, 'membership_schedule')
        RETURNING id INTO v_booking;
        INSERT INTO public.booking_events (booking_id, event_type, event_metadata)
        VALUES (v_booking, 'booking_created', jsonb_build_object('booking_type', 'membership', 'source', 'membership_schedule', 'membership_id', v_membership));
        v_created := v_created + 1;
      END IF;
    END IF;
    v_date := v_date + 1;
  END LOOP;

  UPDATE public.membership_requests SET status = 'active', membership_id = v_membership, updated_at = now() WHERE id = v_req.id;

  INSERT INTO public.notifications (profile_id, category, title, body, reference_id) VALUES
    (v_req.customer_profile_id, 'membership_approved', 'Your WASHO membership is active',
     v_total || ' washes are scheduled, starting ' || to_char(v_start, 'Dy DD Mon') || '.', v_membership),
    (v_req.customer_profile_id, 'payment_successful', 'Payment received', 'We received your payment. Thank you!', v_membership);

  PERFORM app_private.audit('membership', v_membership, 'membership_activated',
    jsonb_build_object('request_id', v_req.id, 'payment_id', p_pay.id, 'washes', v_created, 'skipped_dates', v_skipped, 'start', v_start));
  RETURN v_membership;
END $$;

-- ───────────────────────── 3. settle_payment ─────────────────────────
-- Expected rejections are RETURNED (not raised) so that their audit rows are committed.
CREATE OR REPLACE FUNCTION app_private.settle_payment(
  p_provider_order_id text,
  p_provider_payment_id text,
  p_amount_cents integer,
  p_currency text,
  p_provider_status text,
  p_expected_profile_id uuid DEFAULT NULL,
  p_source text DEFAULT 'api'
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_pay public.payments%ROWTYPE;
  v_booking uuid;
  v_membership uuid;
  v_err text;
  v_reason text;
BEGIN
  IF p_provider_order_id IS NULL OR p_provider_payment_id IS NULL THEN
    RETURN jsonb_build_object('status', 'rejected', 'reason', 'missing_ids');
  END IF;

  SELECT * INTO v_pay FROM public.payments WHERE provider_order_id = p_provider_order_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('status', 'unknown_order'); END IF;

  IF p_expected_profile_id IS NOT NULL AND v_pay.customer_profile_id <> p_expected_profile_id THEN
    PERFORM app_private.audit('payment', v_pay.id, 'payment_rejected', jsonb_build_object('reason', 'ownership', 'source', p_source));
    RETURN jsonb_build_object('status', 'rejected', 'reason', 'not_your_payment');
  END IF;

  IF lower(COALESCE(p_provider_status, '')) <> 'captured' THEN
    PERFORM app_private.audit('payment', v_pay.id, 'payment_not_captured', jsonb_build_object('provider_status', p_provider_status, 'source', p_source));
    RETURN jsonb_build_object('status', 'not_captured');
  END IF;

  IF v_pay.status = 'paid' THEN
    IF v_pay.provider_payment_id = p_provider_payment_id THEN
      RETURN jsonb_build_object('status', CASE WHEN v_pay.fulfilment_status = 'unfulfilled' THEN 'unfulfilled' ELSE 'already_settled' END,
                                'payment_id', v_pay.id, 'booking_id', v_pay.booking_id, 'membership_id', v_pay.membership_id);
    END IF;
    PERFORM app_private.audit('payment', v_pay.id, 'duplicate_capture',
      jsonb_build_object('existing_provider_payment_id', v_pay.provider_payment_id, 'new_provider_payment_id', p_provider_payment_id, 'amount_cents', p_amount_cents, 'source', p_source));
    RETURN jsonb_build_object('status', 'duplicate_payment', 'payment_id', v_pay.id);
  END IF;

  IF p_amount_cents IS DISTINCT FROM v_pay.amount_cents OR upper(COALESCE(p_currency, '')) <> 'INR' THEN
    PERFORM app_private.audit('payment', v_pay.id, 'payment_amount_mismatch',
      jsonb_build_object('expected_cents', v_pay.amount_cents, 'got_cents', p_amount_cents, 'currency', p_currency, 'source', p_source));
    RETURN jsonb_build_object('status', 'rejected', 'reason', 'amount_mismatch');
  END IF;

  IF EXISTS (SELECT 1 FROM public.payments WHERE provider_payment_id = p_provider_payment_id AND id <> v_pay.id) THEN
    PERFORM app_private.audit('payment', v_pay.id, 'payment_rejected', jsonb_build_object('reason', 'provider_payment_reused', 'source', p_source));
    RETURN jsonb_build_object('status', 'rejected', 'reason', 'payment_id_reused');
  END IF;

  -- A payment we had already abandoned (superseded by a newer attempt) can still be captured late.
  IF v_pay.status <> 'pending' OR v_pay.intent IS NULL THEN
    v_reason := CASE WHEN v_pay.intent IS NULL THEN 'legacy_payment_without_intent' ELSE 'payment_superseded' END;
    UPDATE public.payments SET status = 'paid', provider_payment_id = p_provider_payment_id, paid_at = now(), updated_at = now(),
           fulfilment_status = 'unfulfilled', booking_id = NULL, membership_id = NULL WHERE id = v_pay.id;
    INSERT INTO public.refunds (payment_id, customer_profile_id, amount_cents, reason, status)
    VALUES (v_pay.id, v_pay.customer_profile_id, v_pay.amount_cents, 'Order could not be fulfilled: ' || v_reason, 'requested');
    PERFORM app_private.audit('payment', v_pay.id, 'payment_unfulfilled', jsonb_build_object('reason', v_reason, 'source', p_source));
    RETURN jsonb_build_object('status', 'unfulfilled', 'payment_id', v_pay.id, 'reason', v_reason);
  END IF;

  -- Fulfil in a sub-transaction. If anything fails, only the fulfilment is undone; the payment is recorded below.
  BEGIN
    IF v_pay.payment_kind = 'on_demand' THEN
      v_booking := app_private.fulfil_on_demand(v_pay);
    ELSIF v_pay.payment_kind = 'membership' THEN
      v_membership := app_private.fulfil_membership(v_pay);
    ELSE
      RAISE EXCEPTION 'unknown_payment_kind';
    END IF;

    UPDATE public.payments SET status = 'paid', provider_payment_id = p_provider_payment_id, paid_at = now(), updated_at = now(),
           booking_id = v_booking, membership_id = v_membership, fulfilment_status = 'fulfilled'
     WHERE id = v_pay.id;
  EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_err = MESSAGE_TEXT;
    UPDATE public.payments SET status = 'paid', provider_payment_id = p_provider_payment_id, paid_at = now(), updated_at = now(),
           fulfilment_status = 'unfulfilled', booking_id = NULL, membership_id = NULL WHERE id = v_pay.id;
    INSERT INTO public.refunds (payment_id, customer_profile_id, amount_cents, reason, status)
    VALUES (v_pay.id, v_pay.customer_profile_id, v_pay.amount_cents, 'Order could not be fulfilled: ' || v_err, 'requested');
    PERFORM app_private.audit('payment', v_pay.id, 'payment_unfulfilled', jsonb_build_object('error', v_err, 'source', p_source));
    RETURN jsonb_build_object('status', 'unfulfilled', 'payment_id', v_pay.id, 'reason', v_err);
  END;

  PERFORM app_private.audit('payment', v_pay.id, 'payment_settled',
    jsonb_build_object('kind', v_pay.payment_kind, 'booking_id', v_booking, 'membership_id', v_membership, 'amount_cents', v_pay.amount_cents, 'source', p_source));
  RETURN jsonb_build_object('status', 'fulfilled', 'payment_id', v_pay.id, 'booking_id', v_booking, 'membership_id', v_membership);
END $$;

-- ───────────────────────── customer: poll a payment ─────────────────────────
CREATE OR REPLACE FUNCTION public.my_payment_status(p_payment_id uuid) RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT jsonb_build_object('payment_id', p.id, 'status', p.status, 'fulfilment_status', p.fulfilment_status,
                            'amount_cents', p.amount_cents, 'booking_id', p.booking_id, 'membership_id', p.membership_id,
                            'provider_order_id', p.provider_order_id)
    FROM public.payments p WHERE p.id = p_payment_id AND p.customer_profile_id = public.current_profile_id();
$$;

-- ───────────────────────── grants ─────────────────────────
REVOKE ALL ON FUNCTION app_private.slot_start(date, public.time_slot) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION app_private.vehicle_has_live_booking(uuid, date) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION app_private.attach_provider_order(uuid, text, uuid) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION app_private.fulfil_on_demand(public.payments) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION app_private.fulfil_membership(public.payments) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION app_private.settle_payment(text, text, integer, text, text, uuid, text) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.create_booking_payment_intent(uuid, uuid, date, public.time_slot, uuid, text, text, text) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.my_payment_status(uuid) FROM PUBLIC, anon;

-- The server (edge functions as service_role, or the Render API as washo_api) may settle and attach.
GRANT EXECUTE ON FUNCTION app_private.slot_start(date, public.time_slot) TO service_role, washo_api;
GRANT EXECUTE ON FUNCTION app_private.attach_provider_order(uuid, text, uuid) TO service_role, washo_api;
GRANT EXECUTE ON FUNCTION app_private.settle_payment(text, text, integer, text, text, uuid, text) TO service_role, washo_api;
-- fulfil_* are only ever reached through settle_payment (SECURITY DEFINER), so nobody needs direct access.
GRANT EXECUTE ON FUNCTION public.create_booking_payment_intent(uuid, uuid, date, public.time_slot, uuid, text, text, text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.my_payment_status(uuid) TO authenticated;

-- ═════════════ 20261004000006_reschedule_membership_wash.sql ═════════════
-- 20261004000006_reschedule_membership_wash.sql
-- SAFE: same signature the mobile app already calls; strictly more correct.
--
-- What was wrong with the live function:
--   * changing the TIME SLOT always failed ("Booking date and time slot must match the schedule occurrence"):
--     the occurrence trigger and the booking trigger each demanded the other be updated first
--   * a wash could be moved outside the membership's own term, onto a day the vehicle was already booked,
--     or on a membership that is no longer active
--   * a worker who had already claimed the wash stayed assigned to the old date
--
-- Membership washes can be RESCHEDULED but not cancelled by the customer (WASHO rule). Moving a wash
-- consumes nothing: there are no credits; the wash simply happens on its new date.
--
-- One core (app_private.reschedule_wash) serves the customer and WASHO's admins, so both follow the same rules.
--
-- Worker queue behaviour: the moved wash is released from whoever held it. If the membership has a regular
-- specialist (memberships.assigned_worker_profile_id) the wash goes straight back into THAT worker's queue on
-- its new date; otherwise it returns to the pool. A 'rescheduled' booking event records old and new date/slot,
-- which is what the worker queue shows as "moved from ...".

CREATE OR REPLACE FUNCTION app_private.reschedule_wash(
  p_occurrence_id uuid, p_new_date date, p_new_slot public.time_slot,
  p_actor uuid,            -- profile making the change
  p_customer uuid,         -- non-null: the caller must own the membership (customer path); null: admin path
  p_min_date date,         -- earliest date allowed for this caller
  p_reason text DEFAULT NULL
) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  o public.membership_schedule_occurrences%ROWTYPE;
  v_membership public.memberships%ROWTYPE;
  v_booking public.bookings%ROWTYPE;
  v_worker uuid;
BEGIN
  SELECT * INTO o FROM public.membership_schedule_occurrences WHERE id = p_occurrence_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Wash not found'; END IF;

  SELECT m.* INTO v_membership
    FROM public.membership_schedules ms JOIN public.memberships m ON m.id = ms.membership_id
   WHERE ms.id = o.membership_schedule_id;
  IF p_customer IS NOT NULL AND v_membership.customer_profile_id <> p_customer THEN RAISE EXCEPTION 'Wash not found'; END IF;
  IF v_membership.status <> 'active' THEN RAISE EXCEPTION 'This membership is not active'; END IF;

  SELECT * INTO v_booking FROM public.bookings WHERE membership_schedule_occurrence_id = p_occurrence_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Wash not found'; END IF;
  IF v_booking.status NOT IN ('pending', 'confirmed', 'worker_assigned', 'worker_called', 'call_not_picked_up', 'rescheduled') THEN
    RAISE EXCEPTION 'This wash is % and cannot be rescheduled', v_booking.status;
  END IF;

  IF p_new_date IS NULL OR p_new_date < p_min_date THEN
    RAISE EXCEPTION 'Washes need at least 1 day of preparation. The earliest date is %', p_min_date;
  END IF;
  IF p_new_date < o.original_date THEN
    RAISE EXCEPTION 'A wash cannot be moved earlier than its original date (%)', o.original_date;
  END IF;
  IF p_new_date > (v_membership.end_at AT TIME ZONE 'Asia/Kolkata')::date THEN
    RAISE EXCEPTION 'Please choose a date within your membership, which ends on %', (v_membership.end_at AT TIME ZONE 'Asia/Kolkata')::date;
  END IF;
  IF p_new_date = o."current_date" AND p_new_slot = o.time_slot THEN
    RAISE EXCEPTION 'That is already the date and time of this wash';
  END IF;
  IF EXISTS (SELECT 1 FROM public.bookings
              WHERE vehicle_id = v_booking.vehicle_id AND scheduled_date = p_new_date AND id <> v_booking.id
                AND status IN ('pending', 'confirmed', 'worker_assigned', 'worker_called', 'in_progress')) THEN
    RAISE EXCEPTION 'This vehicle already has a wash on that date';
  END IF;

  -- The two validation triggers require booking and occurrence to agree at every step, so move them in an
  -- order where they always do: (1) the date (the occurrence trigger carries the booking along), then
  -- (2) the slot on the occurrence, then (3) the same slot on the booking.
  IF p_new_date <> o."current_date" THEN
    UPDATE public.membership_schedule_occurrences
       SET "current_date" = p_new_date, status = 'rescheduled', updated_at = now() WHERE id = p_occurrence_id;
  END IF;
  IF p_new_slot <> o.time_slot THEN
    UPDATE public.membership_schedule_occurrences
       SET time_slot = p_new_slot, status = 'rescheduled', updated_at = now() WHERE id = p_occurrence_id;
  END IF;

  UPDATE public.bookings
     SET time_slot = p_new_slot, status = 'confirmed', customer_confirmed_at = NULL, updated_at = now(),
         notes = COALESCE(notes, '') || E'\nRescheduled from ' || v_booking.scheduled_date::text || ' to ' || p_new_date::text
   WHERE id = v_booking.id;

  -- Whoever held the old date no longer does.
  UPDATE public.worker_assignments SET is_active = false, unassigned_at = now() WHERE booking_id = v_booking.id AND is_active;

  -- A membership with a regular specialist keeps that specialist on its washes.
  SELECT p.id INTO v_worker FROM public.profiles p WHERE p.id = v_membership.assigned_worker_profile_id AND p.role = 'worker';
  IF v_worker IS NOT NULL THEN
    INSERT INTO public.worker_assignments (booking_id, worker_profile_id, is_active, assigned_at) VALUES (v_booking.id, v_worker, true, now());
    UPDATE public.bookings SET status = 'worker_assigned' WHERE id = v_booking.id;
  END IF;

  INSERT INTO public.booking_events (booking_id, event_type, actor_profile_id, event_metadata)
  VALUES (v_booking.id, 'rescheduled', p_actor,
          jsonb_build_object('old_date', v_booking.scheduled_date, 'old_slot', v_booking.time_slot,
                             'new_date', p_new_date, 'new_slot', p_new_slot,
                             'by', CASE WHEN p_customer IS NULL THEN 'admin' ELSE 'customer' END,
                             'reason', NULLIF(trim(p_reason), ''),
                             'worker_profile_id', v_worker));
  RETURN true;
END $$;
REVOKE ALL ON FUNCTION app_private.reschedule_wash(uuid, date, public.time_slot, uuid, uuid, date, text) FROM PUBLIC, anon, authenticated;

CREATE OR REPLACE FUNCTION public.reschedule_booking_occurrence(p_occurrence_id uuid, p_new_date date, p_new_slot public.time_slot)
RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_customer uuid := public.current_profile_id();
  v_min_date date := (now() AT TIME ZONE 'Asia/Kolkata')::date + 2;
BEGIN
  IF v_customer IS NULL THEN RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501'; END IF;
  RETURN app_private.reschedule_wash(p_occurrence_id, p_new_date, p_new_slot, v_customer, v_customer, v_min_date, NULL);
END $$;

REVOKE ALL ON FUNCTION public.reschedule_booking_occurrence(uuid, date, public.time_slot) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.reschedule_booking_occurrence(uuid, date, public.time_slot) TO authenticated;

-- ═════════════ 20261004000007_fix_worker_call_and_start.sql ═════════════
-- 20261004000007_fix_worker_call_and_start.sql
-- SAFE: same signatures, strictly more correct.
--
-- Found in the production schema:
--   * worker_call_customer ALWAYS failed: it assigned a text CASE expression to an enum column
--     ("column status is of type booking_status but expression is of type text").
--   * worker_call_customer and worker_start_wash let ANY worker take over a job: if the caller was not the
--     active worker they deactivated whoever was and assigned themselves (start_wash only refused once the
--     wash was already in progress). With worker privacy tightened, that would be a way to read customer details.
--   * worker_start_wash would start a wash in any status except completed/cancelled, including an UNPAID
--     ('pending') booking.
--
-- Rule now (one place): a worker may act on a booking only if they are its active worker, or it is an
-- unclaimed CONFIRMED booking, in which case acting on it claims it (so "call customer" before "claim" still works).

CREATE OR REPLACE FUNCTION app_private.ensure_worker_assignment(p_booking_id uuid, p_worker uuid) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_status public.booking_status;
  v_existing uuid;
BEGIN
  SELECT status INTO v_status FROM public.bookings WHERE id = p_booking_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Booking not found'; END IF;

  SELECT worker_profile_id INTO v_existing FROM public.worker_assignments WHERE booking_id = p_booking_id AND is_active LIMIT 1;
  IF v_existing = p_worker THEN RETURN; END IF;
  IF v_existing IS NOT NULL THEN RAISE EXCEPTION 'This wash is already assigned to another specialist'; END IF;
  IF v_status <> 'confirmed' THEN RAISE EXCEPTION 'This wash is not available to claim (it is %)', v_status; END IF;

  INSERT INTO public.worker_assignments (booking_id, worker_profile_id, is_active, assigned_at) VALUES (p_booking_id, p_worker, true, now());
  UPDATE public.bookings SET status = 'worker_assigned', updated_at = now() WHERE id = p_booking_id;
  INSERT INTO public.booking_events (booking_id, event_type, actor_profile_id, event_metadata)
  VALUES (p_booking_id, 'worker_assigned', p_worker, jsonb_build_object('worker_id', p_worker));
END $$;
REVOKE ALL ON FUNCTION app_private.ensure_worker_assignment(uuid, uuid) FROM PUBLIC, anon, authenticated;

CREATE OR REPLACE FUNCTION public.worker_call_customer(p_booking_id uuid) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE v_worker uuid := public.current_profile_id();
BEGIN
  IF NOT public.is_worker() THEN RAISE EXCEPTION 'Only authenticated workers can log customer calls'; END IF;
  PERFORM app_private.ensure_worker_assignment(p_booking_id, v_worker);

  UPDATE public.bookings
     SET status = CASE WHEN status = 'in_progress' THEN 'in_progress'::public.booking_status ELSE 'worker_called'::public.booking_status END,
         updated_at = now()
   WHERE id = p_booking_id AND status IN ('worker_assigned', 'worker_called', 'call_not_picked_up', 'in_progress');
  IF NOT FOUND THEN RAISE EXCEPTION 'This wash can no longer be updated'; END IF;

  INSERT INTO public.booking_events (booking_id, event_type, actor_profile_id) VALUES (p_booking_id, 'worker_called', v_worker);
  RETURN true;
END $$;

CREATE OR REPLACE FUNCTION public.worker_start_wash(p_booking_id uuid) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_worker uuid := public.current_profile_id();
  v_status public.booking_status;
BEGIN
  IF NOT public.is_worker() THEN RAISE EXCEPTION 'Only authenticated workers may start a wash'; END IF;
  PERFORM app_private.ensure_worker_assignment(p_booking_id, v_worker);

  SELECT status INTO v_status FROM public.bookings WHERE id = p_booking_id;
  IF v_status = 'in_progress' THEN RETURN true; END IF; -- already started by this worker
  IF v_status NOT IN ('worker_assigned', 'worker_called', 'call_not_picked_up') THEN
    RAISE EXCEPTION 'This wash cannot be started (it is %)', v_status;
  END IF;

  UPDATE public.bookings SET status = 'in_progress', updated_at = now() WHERE id = p_booking_id;
  INSERT INTO public.booking_events (booking_id, event_type, actor_profile_id) VALUES (p_booking_id, 'wash_started', v_worker);
  RETURN true;
END $$;

REVOKE ALL ON FUNCTION public.worker_call_customer(uuid), public.worker_start_wash(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.worker_call_customer(uuid), public.worker_start_wash(uuid) TO authenticated;

-- ═════════════ 20261004000008_service_rpc_wrappers.sql ═════════════
-- 20261004000008_service_rpc_wrappers.sql
-- SAFE / additive. Supabase edge functions reach the database through PostgREST, which only exposes the
-- `public` schema. The payment functions live in the private `app_private` schema on purpose, so these thin
-- wrappers make them callable by the SERVICE ROLE (and the Render API role) and nobody else.
-- Customers, workers and anonymous visitors get "permission denied".

CREATE OR REPLACE FUNCTION public.svc_attach_provider_order(p_payment_id uuid, p_provider_order_id text, p_expected_profile_id uuid DEFAULT NULL)
RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path = public AS $$
  SELECT app_private.attach_provider_order(p_payment_id, p_provider_order_id, p_expected_profile_id);
$$;

CREATE OR REPLACE FUNCTION public.svc_settle_payment(
  p_provider_order_id text, p_provider_payment_id text, p_amount_cents integer, p_currency text,
  p_provider_status text, p_expected_profile_id uuid DEFAULT NULL, p_source text DEFAULT 'api')
RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path = public AS $$
  SELECT app_private.settle_payment(p_provider_order_id, p_provider_payment_id, p_amount_cents, p_currency, p_provider_status, p_expected_profile_id, p_source);
$$;

CREATE OR REPLACE FUNCTION public.svc_profile_id_for_auth_user(p_auth_user_id uuid)
RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT id FROM public.profiles WHERE auth_user_id = p_auth_user_id AND role = 'customer';
$$;

REVOKE ALL ON FUNCTION public.svc_attach_provider_order(uuid, text, uuid) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.svc_settle_payment(text, text, integer, text, text, uuid, text) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.svc_profile_id_for_auth_user(uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.svc_attach_provider_order(uuid, text, uuid) TO service_role, washo_api;
GRANT EXECUTE ON FUNCTION public.svc_settle_payment(text, text, integer, text, text, uuid, text) TO service_role, washo_api;
GRANT EXECUTE ON FUNCTION public.svc_profile_id_for_auth_user(uuid) TO service_role, washo_api;

-- ═════════════ 20261004000009_worker_workflow.sql ═════════════
-- 20261004000009_worker_workflow.sql
-- SAFE / additive. The membership-wash workflow for specialists (workers), built on the EXISTING tables:
-- bookings, worker_assignments, booking_events, booking_photos. No new worker system.
--
--   membership paid -> washes generated -> assigned (admin, or the worker claims from the pool)
--   -> worker queue -> CALL customer -> confirmed | not picked up (stays scheduled)
--   -> START -> before photos -> after photos -> COMPLETE -> next wash is already in the queue
--
-- Rules enforced here for every client (website and mobile):
--   * a worker can act on a wash only if they hold it (or it is an unclaimed, paid and confirmed wash)
--   * a worker sees customer name/phone/address/vehicle ONLY for washes they currently hold; nothing else
--   * "not picked up" never completes or charges anything and the wash stays scheduled
--   * completing needs a before AND an after photo (worker_complete_wash)
--   * every step is a booking_events row, so WASHO can see exactly what happened
--
-- worker_pool() used to live in the cutover set; it is additive and safe, so it ships here.

-- ───────────────────────── the pool (unclaimed upcoming washes, no customer details) ─────────────────────────
CREATE OR REPLACE FUNCTION public.worker_pool(p_days integer DEFAULT 14)
RETURNS TABLE (
  booking_id uuid, scheduled_date date, time_slot public.time_slot, booking_type public.booking_type,
  service_name text, vehicle_type public.vehicle_type, society_name text, area_locality text, city text
) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF NOT public.is_worker() AND NOT public.is_admin() THEN
    RAISE EXCEPTION 'Only workers can view the pool' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY
  SELECT b.id, b.scheduled_date, b.time_slot, b.booking_type, s.name, v.vehicle_type,
         COALESCE(a.society_name, va.society_name), COALESCE(a.area_locality, va.area_locality), COALESCE(a.city, va.city)
    FROM public.bookings b
    JOIN public.services s ON s.id = b.service_id
    JOIN public.vehicles v ON v.id = b.vehicle_id
    LEFT JOIN public.customer_addresses a ON a.id = b.address_id
    LEFT JOIN public.customer_addresses va ON va.id = v.address_id
   WHERE b.status = 'confirmed'
     AND b.scheduled_date BETWEEN (now() AT TIME ZONE 'Asia/Kolkata')::date AND (now() AT TIME ZONE 'Asia/Kolkata')::date + GREATEST(p_days, 1)
     AND NOT EXISTS (SELECT 1 FROM public.worker_assignments wa WHERE wa.booking_id = b.id AND wa.is_active)
   ORDER BY b.scheduled_date, b.time_slot;
END $$;
REVOKE ALL ON FUNCTION public.worker_pool(integer) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.worker_pool(integer) TO authenticated;

-- ───────────────────────── claim: only a paid, confirmed, unclaimed wash ─────────────────────────
-- (the original accepted any status except completed/cancelled, including unpaid 'pending' bookings)
CREATE OR REPLACE FUNCTION public.worker_claim_booking(p_booking_id uuid) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF NOT public.is_worker() THEN RAISE EXCEPTION 'Only authenticated workers may claim a booking'; END IF;
  PERFORM app_private.ensure_worker_assignment(p_booking_id, public.current_profile_id());
  RETURN true;
END $$;
REVOKE ALL ON FUNCTION public.worker_claim_booking(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.worker_claim_booking(uuid) TO authenticated;

-- ───────────────────────── the worker's queue ─────────────────────────
-- One call returns everything the worker dashboard needs. `bucket` says which tab a row belongs to:
--   today        washes due today (or overdue) that the worker holds and has not started
--   in_progress  started, not finished
--   upcoming     the next p_days days
--   completed    finished in the last 30 days
--   changed      cancelled, or moved/released away from this worker in the last 14 days (no customer details)
-- `change` (jsonb) is set when the wash was rescheduled / cancelled / released recently, so the queue can say
-- "moved from Mon 6 Oct, morning".
CREATE OR REPLACE FUNCTION public.worker_queue(p_days integer DEFAULT 7)
RETURNS TABLE (
  booking_id uuid, reference_code text, status text, bucket text, is_overdue boolean,
  booking_type text, scheduled_date date, time_slot text,
  service_name text, wash_kind text,
  vehicle_type text, vehicle_make text, vehicle_model text, registration_number text, vehicle_color text,
  customer_name text, customer_phone text,
  address_label text, society_name text, building_block text, flat_number text, area_locality text, city text,
  parking_location text, instructions text, target_completion_time text,
  membership_id uuid, membership_reference text, membership_label text, wash_number integer, washes_total integer,
  customer_confirmed_at timestamptz, calls_made integer, last_call_at timestamptz,
  photos_before integer, photos_after integer, started_at timestamptz, completed_at timestamptz,
  change jsonb
) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_worker uuid := public.current_profile_id();
  v_today date := (now() AT TIME ZONE 'Asia/Kolkata')::date;
  v_days integer := LEAST(GREATEST(COALESCE(p_days, 7), 1), 60);
BEGIN
  IF NOT public.is_worker() THEN RAISE EXCEPTION 'Only workers can view the worker queue' USING ERRCODE = '42501'; END IF;

  RETURN QUERY
  WITH mine AS (
    SELECT b.id, true AS holds FROM public.bookings b
      JOIN public.worker_assignments wa ON wa.booking_id = b.id AND wa.worker_profile_id = v_worker AND wa.is_active
  ), released AS (
    SELECT DISTINCT b.id, false AS holds FROM public.bookings b
      JOIN public.worker_assignments wa ON wa.booking_id = b.id AND wa.worker_profile_id = v_worker
       AND NOT wa.is_active AND wa.unassigned_at > now() - interval '14 days'
     WHERE b.status NOT IN ('completed')
       AND NOT EXISTS (SELECT 1 FROM public.worker_assignments x WHERE x.booking_id = b.id AND x.worker_profile_id = v_worker AND x.is_active)
  ), picked AS (
    SELECT * FROM mine UNION ALL SELECT * FROM released
  ), seq AS (   -- "wash 7 of 24" within a membership
    SELECT x.id, row_number() OVER (PARTITION BY x.membership_id ORDER BY x.scheduled_date, x.created_at)::int AS n,
           count(*) OVER (PARTITION BY x.membership_id)::int AS total
      FROM public.bookings x
     WHERE x.membership_id IN (SELECT b.membership_id FROM public.bookings b JOIN picked p ON p.id = b.id WHERE b.membership_id IS NOT NULL)
       AND x.status <> 'cancelled'
  ), base AS (
    SELECT b.*, p.holds,
           CASE
             WHEN NOT p.holds THEN 'changed'
             WHEN b.status = 'completed' THEN 'completed'
             WHEN b.status IN ('cancelled', 'refund_requested', 'refunded', 'no_show') THEN 'changed'
             WHEN b.status = 'in_progress' THEN 'in_progress'
             WHEN b.scheduled_date <= v_today THEN 'today'
             ELSE 'upcoming'
           END AS bk
      FROM public.bookings b JOIN picked p ON p.id = b.id
  )
  SELECT b.id, b.reference_code, b.status::text, b.bk, (b.bk = 'today' AND b.scheduled_date < v_today),
         b.booking_type::text, b.scheduled_date, b.time_slot::text,
         s.name, s.wash_kind,
         v.vehicle_type::text,
         CASE WHEN b.bk = 'changed' THEN NULL ELSE v.make END,
         CASE WHEN b.bk = 'changed' THEN NULL ELSE v.model END,
         CASE WHEN b.bk = 'changed' THEN NULL ELSE v.registration_number END,
         CASE WHEN b.bk = 'changed' THEN NULL ELSE v.color END,
         CASE WHEN b.bk = 'changed' THEN NULL ELSE cp.full_name END,
         CASE WHEN b.bk IN ('today', 'upcoming', 'in_progress') THEN cp.phone END,
         CASE WHEN b.bk = 'changed' THEN NULL ELSE a.label END,
         CASE WHEN b.bk = 'changed' THEN NULL ELSE a.society_name END,
         CASE WHEN b.bk = 'changed' THEN NULL ELSE a.building_block END,
         CASE WHEN b.bk = 'changed' THEN NULL ELSE a.flat_number END,
         CASE WHEN b.bk = 'changed' THEN NULL ELSE a.area_locality END,
         CASE WHEN b.bk = 'changed' THEN NULL ELSE a.city END,
         CASE WHEN b.bk = 'changed' THEN NULL ELSE COALESCE(b.parking_location, v.parking_location, a.parking_location) END,
         CASE WHEN b.bk = 'changed' THEN NULL ELSE mr.customer_notes END,
         b.target_completion_time,
         b.membership_id, mr.reference_code,
         CASE WHEN b.membership_id IS NULL THEN NULL
              ELSE COALESCE(mr.frequency_per_week::text || ' wash' || CASE WHEN mr.frequency_per_week > 1 THEN 'es' ELSE '' END || ' a week · ' || mr.duration_months::text || ' month' || CASE WHEN mr.duration_months > 1 THEN 's' ELSE '' END,
                            'Membership') END,
         sq.n, sq.total,
         b.customer_confirmed_at,
         (SELECT count(*)::int FROM public.booking_events e WHERE e.booking_id = b.id AND e.event_type = 'worker_called' AND e.actor_profile_id = v_worker),
         (SELECT max(e.created_at) FROM public.booking_events e WHERE e.booking_id = b.id AND e.event_type = 'worker_called' AND e.actor_profile_id = v_worker),
         (SELECT count(*)::int FROM public.booking_photos ph WHERE ph.booking_id = b.id AND ph.phase = 'before'),
         (SELECT count(*)::int FROM public.booking_photos ph WHERE ph.booking_id = b.id AND ph.phase = 'after'),
         (SELECT max(e.created_at) FROM public.booking_events e WHERE e.booking_id = b.id AND e.event_type = 'wash_started'),
         b.completed_at,
         (SELECT CASE
                   WHEN ch.event_type = 'rescheduled' THEN jsonb_build_object('kind', 'rescheduled', 'at', ch.created_at,
                          'from_date', ch.event_metadata->>'old_date', 'from_slot', ch.event_metadata->>'old_slot', 'by', ch.event_metadata->>'by')
                   WHEN ch.event_type IN ('cancelled', 'booking_cancelled') THEN jsonb_build_object('kind', 'cancelled', 'at', ch.created_at,
                          'reason', ch.event_metadata->>'reason')
                   ELSE jsonb_build_object('kind', 'reassigned', 'at', ch.created_at)
                 END
            FROM (SELECT e.* FROM public.booking_events e
                   WHERE e.booking_id = b.id AND e.created_at > now() - interval '14 days'
                     AND (e.event_type IN ('rescheduled', 'cancelled', 'booking_cancelled')
                          OR (NOT b.holds AND e.event_type IN ('worker_assigned', 'membership_worker_assigned')))
                   -- newest first; if several events share a timestamp, a move or cancellation wins over a reassignment
                   -- (the original schema's sync trigger also logs a bare 'rescheduled' event; prefer ours, which carries old/new date and who moved it)
                   ORDER BY e.created_at DESC, (e.event_type IN ('rescheduled', 'cancelled', 'booking_cancelled')) DESC, (e.event_metadata ? 'old_date') DESC LIMIT 1) ch)
    FROM base b
    JOIN public.services s ON s.id = b.service_id
    JOIN public.vehicles v ON v.id = b.vehicle_id
    JOIN public.profiles cp ON cp.id = b.customer_profile_id
    LEFT JOIN public.customer_addresses a ON a.id = COALESCE(b.address_id, v.address_id,
         (SELECT d.id FROM public.customer_addresses d WHERE d.customer_profile_id = b.customer_profile_id AND d.is_default LIMIT 1))
    LEFT JOIN public.memberships m ON m.id = b.membership_id
    LEFT JOIN public.membership_requests mr ON mr.id = m.membership_request_id
    LEFT JOIN seq sq ON sq.id = b.id
   WHERE CASE b.bk
           WHEN 'upcoming'  THEN b.scheduled_date <= v_today + v_days
           WHEN 'completed' THEN b.completed_at > now() - interval '30 days'
           WHEN 'changed'   THEN b.updated_at > now() - interval '30 days'
           ELSE true
         END
   ORDER BY b.scheduled_date, b.time_slot, b.created_at;
END $$;
REVOKE ALL ON FUNCTION public.worker_queue(integer) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.worker_queue(integer) TO authenticated;

-- ───────────────────────── step: customer confirmed ─────────────────────────
CREATE OR REPLACE FUNCTION public.worker_confirm_customer(p_booking_id uuid) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_worker uuid := public.current_profile_id();
  v_status public.booking_status;
BEGIN
  IF NOT public.is_worker() THEN RAISE EXCEPTION 'Only authenticated workers can confirm with a customer'; END IF;
  PERFORM app_private.ensure_worker_assignment(p_booking_id, v_worker);

  SELECT status INTO v_status FROM public.bookings WHERE id = p_booking_id;
  IF v_status NOT IN ('worker_assigned', 'worker_called', 'call_not_picked_up') THEN
    RAISE EXCEPTION 'This wash cannot be confirmed now (it is %)', v_status;
  END IF;

  UPDATE public.bookings SET status = 'worker_called', customer_confirmed_at = now(), updated_at = now() WHERE id = p_booking_id;
  UPDATE public.membership_schedule_occurrences o SET status = 'scheduled', updated_at = now()
    FROM public.bookings b WHERE b.id = p_booking_id AND o.id = b.membership_schedule_occurrence_id AND o.status = 'call_not_picked_up';
  INSERT INTO public.booking_events (booking_id, event_type, actor_profile_id) VALUES (p_booking_id, 'customer_confirmed', v_worker);
  RETURN true;
END $$;
REVOKE ALL ON FUNCTION public.worker_confirm_customer(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.worker_confirm_customer(uuid) TO authenticated;

-- ───────────────────────── step: call not picked up ─────────────────────────
-- The wash stays SCHEDULED. Nothing is completed, consumed, charged or refunded; the worker simply tries again
-- (worker_call_customer works from this status) or WASHO moves the wash.
CREATE OR REPLACE FUNCTION public.worker_customer_unavailable(p_booking_id uuid, p_notes text DEFAULT 'Customer did not pick up / unavailable')
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_worker uuid := public.current_profile_id();
  v_status public.booking_status;
  v_note text := COALESCE(NULLIF(trim(p_notes), ''), 'Customer did not pick up / unavailable');
BEGIN
  IF NOT public.is_worker() OR NOT public.is_current_worker_assignment(p_booking_id) THEN
    RAISE EXCEPTION 'Not authorized for this wash assignment';
  END IF;
  SELECT status INTO v_status FROM public.bookings WHERE id = p_booking_id FOR UPDATE;
  IF v_status = 'in_progress' THEN RAISE EXCEPTION 'The wash has already started. Report the problem as an issue instead.'; END IF;
  IF v_status NOT IN ('worker_assigned', 'worker_called', 'call_not_picked_up') THEN
    RAISE EXCEPTION 'This wash cannot be updated now (it is %)', v_status;
  END IF;

  UPDATE public.bookings
     SET status = 'call_not_picked_up', customer_confirmed_at = NULL, updated_at = now(),
         notes = COALESCE(notes || E'\n', '') || 'Worker report: ' || v_note
   WHERE id = p_booking_id;
  UPDATE public.membership_schedule_occurrences o SET status = 'call_not_picked_up', updated_at = now()
    FROM public.bookings b WHERE b.id = p_booking_id AND o.id = b.membership_schedule_occurrence_id;
  INSERT INTO public.booking_events (booking_id, event_type, actor_profile_id, event_metadata)
  VALUES (p_booking_id, 'call_not_picked_up', v_worker, jsonb_build_object('notes', v_note, 'wash_completed', false, 'charged', false));
  RETURN true;
END $$;
REVOKE ALL ON FUNCTION public.worker_customer_unavailable(uuid, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.worker_customer_unavailable(uuid, text) TO authenticated;

-- ───────────────────────── notes and issues ─────────────────────────
CREATE OR REPLACE FUNCTION public.worker_add_note(p_booking_id uuid, p_note text) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_worker uuid := public.current_profile_id();
  v_note text := trim(COALESCE(p_note, ''));
BEGIN
  IF NOT public.is_worker() OR NOT public.is_current_worker_assignment(p_booking_id) THEN
    RAISE EXCEPTION 'Not authorized for this wash assignment';
  END IF;
  IF char_length(v_note) < 2 THEN RAISE EXCEPTION 'Write a short note first'; END IF;
  IF char_length(v_note) > 1000 THEN RAISE EXCEPTION 'Please keep the note under 1000 characters'; END IF;
  INSERT INTO public.booking_events (booking_id, event_type, actor_profile_id, event_metadata)
  VALUES (p_booking_id, 'worker_note', v_worker, jsonb_build_object('note', v_note));
  RETURN true;
END $$;
REVOKE ALL ON FUNCTION public.worker_add_note(uuid, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.worker_add_note(uuid, text) TO authenticated;

-- kinds: customer_unavailable | vehicle_not_accessible | no_water_or_power | damage_noticed | safety_concern | other
CREATE OR REPLACE FUNCTION public.worker_report_issue(p_booking_id uuid, p_kind text, p_notes text DEFAULT NULL) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_worker uuid := public.current_profile_id();
  v_status public.booking_status;
  v_notes text := NULLIF(trim(COALESCE(p_notes, '')), '');
BEGIN
  IF NOT public.is_worker() OR NOT public.is_current_worker_assignment(p_booking_id) THEN
    RAISE EXCEPTION 'Not authorized for this wash assignment';
  END IF;
  IF p_kind NOT IN ('customer_unavailable', 'vehicle_not_accessible', 'no_water_or_power', 'damage_noticed', 'safety_concern', 'other') THEN
    RAISE EXCEPTION 'Unknown issue type';
  END IF;
  IF p_kind <> 'customer_unavailable' AND (v_notes IS NULL OR char_length(v_notes) < 3) THEN
    RAISE EXCEPTION 'Please describe the problem';
  END IF;
  IF v_notes IS NOT NULL AND char_length(v_notes) > 1000 THEN RAISE EXCEPTION 'Please keep the note under 1000 characters'; END IF;

  SELECT status INTO v_status FROM public.bookings WHERE id = p_booking_id;
  IF v_status IN ('cancelled', 'refunded', 'refund_requested') THEN RAISE EXCEPTION 'This wash is %', v_status; END IF;

  -- Customer unavailable before the wash starts is the "not picked up" step: same rules, same status.
  IF p_kind = 'customer_unavailable' AND v_status IN ('worker_assigned', 'worker_called', 'call_not_picked_up') THEN
    RETURN public.worker_customer_unavailable(p_booking_id, COALESCE(v_notes, 'Customer unavailable'));
  END IF;

  INSERT INTO public.booking_events (booking_id, event_type, actor_profile_id, event_metadata)
  VALUES (p_booking_id, 'worker_issue', v_worker, jsonb_build_object('kind', p_kind, 'notes', v_notes, 'status_at_report', v_status));
  RETURN true;
END $$;
REVOKE ALL ON FUNCTION public.worker_report_issue(uuid, text, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.worker_report_issue(uuid, text, text) TO authenticated;

-- ───────────────────────── photos ─────────────────────────
-- Tightened: only while the wash is live (not once completed / cancelled), only into that booking's folder.
CREATE OR REPLACE FUNCTION public.save_booking_photo(p_booking_id uuid, p_phase text, p_photo_type text, p_storage_path text, p_metadata jsonb DEFAULT '{}'::jsonb)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_worker uuid := public.current_profile_id();
  v_status public.booking_status;
  v_photo uuid;
BEGIN
  IF NOT public.is_current_worker_assignment(p_booking_id) THEN
    RAISE EXCEPTION 'Not authorized to save photos for this booking';
  END IF;
  SELECT status INTO v_status FROM public.bookings WHERE id = p_booking_id;
  IF v_status NOT IN ('worker_assigned', 'worker_called', 'call_not_picked_up', 'in_progress') THEN
    RAISE EXCEPTION 'Photos can only be added while the wash is open (it is %)', v_status;
  END IF;
  IF p_storage_path IS NULL OR left(p_storage_path, length(p_booking_id::text) + 1) <> p_booking_id::text || '/' OR p_storage_path ~ '\.\.' THEN
    RAISE EXCEPTION 'Photo path must be inside this booking''s folder';
  END IF;
  INSERT INTO public.booking_photos (booking_id, worker_profile_id, phase, photo_type, storage_path, metadata)
  VALUES (p_booking_id, v_worker, p_phase, p_photo_type, p_storage_path, COALESCE(p_metadata, '{}'::jsonb))
  RETURNING id INTO v_photo;
  RETURN v_photo;
END $$;
REVOKE ALL ON FUNCTION public.save_booking_photo(uuid, text, text, text, jsonb) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.save_booking_photo(uuid, text, text, text, jsonb) TO authenticated;

-- Who may see a wash's photos: its customer, the worker holding it, and admins. (One rule for the website's signed
-- URLs and for anything else that asks.)
CREATE OR REPLACE FUNCTION public.booking_photos_for_viewer(p_booking_id uuid)
RETURNS TABLE (id uuid, phase text, photo_type text, storage_path text, created_at timestamptz)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF NOT (public.is_admin() OR public.is_current_customer_booking(p_booking_id) OR public.is_current_worker_assignment(p_booking_id)) THEN
    RAISE EXCEPTION 'Not found' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY SELECT p.id, p.phase, p.photo_type, p.storage_path, p.created_at
                 FROM public.booking_photos p WHERE p.booking_id = p_booking_id ORDER BY p.created_at;
END $$;
REVOKE ALL ON FUNCTION public.booking_photos_for_viewer(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.booking_photos_for_viewer(uuid) TO authenticated;

-- ───────────────────────── admin: assignment and rescheduling ─────────────────────────
CREATE OR REPLACE FUNCTION public.admin_assign_worker(p_booking_id uuid, p_worker_profile_id uuid) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_admin uuid := public.current_profile_id();
  v_status public.booking_status;
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'Unauthorized: admin access required' USING ERRCODE = '42501'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = p_worker_profile_id AND role = 'worker') THEN RAISE EXCEPTION 'Specialist not found'; END IF;
  SELECT status INTO v_status FROM public.bookings WHERE id = p_booking_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Booking not found'; END IF;
  IF v_status NOT IN ('confirmed', 'worker_assigned', 'worker_called', 'call_not_picked_up') THEN
    RAISE EXCEPTION 'A wash that is % cannot be assigned', v_status;
  END IF;

  IF EXISTS (SELECT 1 FROM public.worker_assignments WHERE booking_id = p_booking_id AND is_active AND worker_profile_id = p_worker_profile_id) THEN
    RETURN true;
  END IF;
  UPDATE public.worker_assignments SET is_active = false, unassigned_at = now() WHERE booking_id = p_booking_id AND is_active;
  INSERT INTO public.worker_assignments (booking_id, worker_profile_id, is_active, assigned_at) VALUES (p_booking_id, p_worker_profile_id, true, now());
  UPDATE public.bookings SET status = 'worker_assigned', customer_confirmed_at = NULL, updated_at = now() WHERE id = p_booking_id;
  INSERT INTO public.booking_events (booking_id, event_type, actor_profile_id, event_metadata)
  VALUES (p_booking_id, 'worker_assigned', v_admin, jsonb_build_object('worker_id', p_worker_profile_id, 'by', 'admin'));
  RETURN true;
END $$;

-- Assigns a worker to every remaining wash of a membership (from p_from on) and makes them its regular
-- specialist, so washes that are moved later return to the same worker. NULL worker = release them to the pool.
CREATE OR REPLACE FUNCTION public.admin_assign_membership_worker(p_membership_id uuid, p_worker_profile_id uuid, p_from date DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_admin uuid := public.current_profile_id();
  v_from date := COALESCE(p_from, (now() AT TIME ZONE 'Asia/Kolkata')::date);
  b record;
  n integer := 0;
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'Unauthorized: admin access required' USING ERRCODE = '42501'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.memberships WHERE id = p_membership_id) THEN RAISE EXCEPTION 'Membership not found'; END IF;
  IF p_worker_profile_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = p_worker_profile_id AND role = 'worker') THEN
    RAISE EXCEPTION 'Specialist not found';
  END IF;

  UPDATE public.memberships SET assigned_worker_profile_id = p_worker_profile_id, updated_at = now() WHERE id = p_membership_id;

  FOR b IN
    SELECT id, status FROM public.bookings
     WHERE membership_id = p_membership_id AND scheduled_date >= v_from
       AND status IN ('confirmed', 'worker_assigned', 'worker_called', 'call_not_picked_up')
     ORDER BY scheduled_date
     FOR UPDATE
  LOOP
    CONTINUE WHEN p_worker_profile_id IS NOT NULL AND EXISTS (
      SELECT 1 FROM public.worker_assignments WHERE booking_id = b.id AND is_active AND worker_profile_id = p_worker_profile_id);
    UPDATE public.worker_assignments SET is_active = false, unassigned_at = now() WHERE booking_id = b.id AND is_active;
    IF p_worker_profile_id IS NOT NULL THEN
      INSERT INTO public.worker_assignments (booking_id, worker_profile_id, is_active, assigned_at) VALUES (b.id, p_worker_profile_id, true, now());
    END IF;
    UPDATE public.bookings SET status = CASE WHEN p_worker_profile_id IS NULL THEN 'confirmed'::public.booking_status ELSE 'worker_assigned'::public.booking_status END,
                               customer_confirmed_at = NULL, updated_at = now() WHERE id = b.id;
    INSERT INTO public.booking_events (booking_id, event_type, actor_profile_id, event_metadata)
    VALUES (b.id, 'membership_worker_assigned', v_admin, jsonb_build_object('worker_id', p_worker_profile_id, 'membership_id', p_membership_id));
    n := n + 1;
  END LOOP;

  PERFORM app_private.audit('membership', p_membership_id, 'membership_worker_assigned',
    jsonb_build_object('worker_id', p_worker_profile_id, 'washes_updated', n, 'from', v_from));
  RETURN jsonb_build_object('membership_id', p_membership_id, 'worker_profile_id', p_worker_profile_id, 'washes_updated', n);
END $$;

-- Admin moves a membership wash (customer called WASHO, bad weather, ...). Same rules as the customer's own
-- reschedule except the customer's 2-day notice, and the reason is recorded.
CREATE OR REPLACE FUNCTION public.admin_reschedule_wash(p_booking_id uuid, p_new_date date, p_new_slot public.time_slot, p_reason text DEFAULT NULL)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE v_occ uuid;
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'Unauthorized: admin access required' USING ERRCODE = '42501'; END IF;
  SELECT membership_schedule_occurrence_id INTO v_occ FROM public.bookings WHERE id = p_booking_id;
  IF v_occ IS NULL THEN RAISE EXCEPTION 'Only membership washes can be moved here'; END IF;
  RETURN app_private.reschedule_wash(v_occ, p_new_date, p_new_slot, public.current_profile_id(), NULL, (now() AT TIME ZONE 'Asia/Kolkata')::date, p_reason);
END $$;

REVOKE ALL ON FUNCTION public.admin_assign_worker(uuid, uuid) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.admin_assign_membership_worker(uuid, uuid, date) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.admin_reschedule_wash(uuid, date, public.time_slot, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.admin_assign_worker(uuid, uuid) TO authenticated;                          -- is_admin() inside
GRANT EXECUTE ON FUNCTION public.admin_assign_membership_worker(uuid, uuid, date) TO authenticated;         -- is_admin() inside
GRANT EXECUTE ON FUNCTION public.admin_reschedule_wash(uuid, date, public.time_slot, text) TO authenticated; -- is_admin() inside

-- ───────────────────────── admin: refunds ─────────────────────────
-- Refund requests (a cancelled paid wash, or money that arrived but could not be fulfilled) were invisible to admins:
-- the table only had customer policies. WASHO pays the money back in the Razorpay dashboard, then records it here.
DROP POLICY IF EXISTS refunds_admin_read ON public.refunds;
CREATE POLICY refunds_admin_read ON public.refunds FOR SELECT TO authenticated USING (public.is_admin());

CREATE OR REPLACE FUNCTION public.admin_resolve_refund(p_refund_id uuid, p_status public.refund_status, p_provider_refund_id text DEFAULT NULL)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE v_old public.refund_status;
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'Unauthorized: admin access required' USING ERRCODE = '42501'; END IF;
  IF p_status NOT IN ('approved', 'processed', 'failed') THEN RAISE EXCEPTION 'A refund can be marked approved, processed or failed'; END IF;
  IF p_status = 'processed' AND (p_provider_refund_id IS NULL OR char_length(trim(p_provider_refund_id)) < 4) THEN
    RAISE EXCEPTION 'Enter the Razorpay refund id so the payout can be traced';
  END IF;
  SELECT status INTO v_old FROM public.refunds WHERE id = p_refund_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Refund not found'; END IF;
  IF v_old IN ('processed', 'reversed') THEN RAISE EXCEPTION 'This refund is already %', v_old; END IF;
  UPDATE public.refunds SET status = p_status, provider_refund_id = COALESCE(NULLIF(trim(p_provider_refund_id), ''), provider_refund_id), updated_at = now() WHERE id = p_refund_id;
  PERFORM app_private.audit('refund', p_refund_id, 'refund_' || p_status::text, jsonb_build_object('from', v_old, 'provider_refund_id', p_provider_refund_id));
  RETURN true;
END $$;
REVOKE ALL ON FUNCTION public.admin_resolve_refund(uuid, public.refund_status, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.admin_resolve_refund(uuid, public.refund_status, text) TO authenticated; -- is_admin() inside

-- ═════════════ 20261004000010_membership_up_to_7_and_estimate.sql ═════════════
-- 20261004000010_membership_up_to_7_and_estimate.sql
-- SAFE / additive and re-runnable. Two product changes:
--
--  1. A membership can have 1 to 7 washes a week (was 1 to 3). One wash per vehicle per day still holds, so the chosen
--     weekdays are all different. Rules for the mix: bikes have one wash type; 1 a week is either kind; 2 a week is one Body +
--     one Deep; 3 or more a week mixes Body and Deep.
--     Frequency discount for 4-7 a week is set to 10%, the same as the 3-a-week rate (ASSUMPTION: it is a data row in
--     membership_discount_rules, so WASHO can change it without a deploy).
--  2. Customers can see an ESTIMATE while they build a plan: estimate_membership_price() runs the same calculator WASHO's
--     quote starts from (rate card x washes, explicit discounts, the cap). It is only an estimate: WASHO still reviews the
--     request and confirms the final price, and the price stored on the request stays hidden from the customer until then.

-- the request table only allowed 1-3 a week
DO $$
DECLARE c text;
BEGIN
  FOR c IN SELECT con.conname FROM pg_constraint con JOIN pg_class t ON t.oid = con.conrelid
            WHERE t.relname = 'membership_requests' AND con.contype = 'c' AND pg_get_constraintdef(con.oid) ILIKE '%frequency_per_week%'
  LOOP
    EXECUTE format('ALTER TABLE public.membership_requests DROP CONSTRAINT %I', c);
  END LOOP;
  ALTER TABLE public.membership_requests ADD CONSTRAINT membership_requests_frequency_per_week_check CHECK (frequency_per_week BETWEEN 1 AND 7);
END $$;

INSERT INTO public.membership_discount_rules (kind, key_value, discount_bp, label)
SELECT 'frequency', n, 1000, n || ' washes a week' FROM generate_series(4, 7) n
 WHERE NOT EXISTS (SELECT 1 FROM public.membership_discount_rules r WHERE r.kind = 'frequency' AND r.key_value = n AND r.active);

-- the calculator (same as before, with the 1-7 range and the "3 or more mixes" rule)
CREATE OR REPLACE FUNCTION app_private.compute_membership_quote(p_vehicle_type public.vehicle_type, p_weekly_pattern jsonb, p_duration_months integer)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_freq integer;
  v_weeks integer := app_private.setting('weeks_per_month');
  v_cap_bp integer := app_private.setting('max_total_discount_bp');
  v_bodies integer;
  v_deeps integer;
  v_lines jsonb := '[]'::jsonb;
  v_subtotal bigint := 0;
  v_freq_bp integer;
  v_dur_bp integer;
  v_freq_cents bigint;
  v_dur_cents bigint;
  v_combined bigint;
  v_cap_cents bigint;
  v_cap_adj bigint := 0;
  v_total_discount bigint;
  rec record;
BEGIN
  IF p_weekly_pattern IS NULL OR jsonb_typeof(p_weekly_pattern) <> 'array' THEN
    RAISE EXCEPTION 'Choose your washes for the week';
  END IF;
  v_freq := jsonb_array_length(p_weekly_pattern);
  IF v_freq NOT BETWEEN 1 AND 7 THEN
    RAISE EXCEPTION 'A membership has 1 to 7 washes a week';
  END IF;

  IF (SELECT count(DISTINCT (e->>'weekday')) FROM jsonb_array_elements(p_weekly_pattern) e) <> v_freq THEN
    RAISE EXCEPTION 'Choose a different day for each wash';
  END IF;
  IF EXISTS (SELECT 1 FROM jsonb_array_elements(p_weekly_pattern) e
              WHERE (e->>'weekday') IS NULL OR (e->>'weekday') !~ '^[0-6]$' OR (e->>'kind') NOT IN ('body', 'deep') OR (e->>'kind') IS NULL) THEN
    RAISE EXCEPTION 'Each wash needs a weekday (0-6) and a kind (body or deep)';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.membership_discount_rules WHERE active AND kind = 'duration' AND key_value = p_duration_months) THEN
    RAISE EXCEPTION 'Membership length must be 1, 3, 6 or 12 months';
  END IF;

  SELECT count(*) FILTER (WHERE e->>'kind' = 'body'), count(*) FILTER (WHERE e->>'kind' = 'deep')
    INTO v_bodies, v_deeps FROM jsonb_array_elements(p_weekly_pattern) e;

  -- Composition rules
  IF p_vehicle_type = 'bike' THEN
    IF v_deeps > 0 THEN RAISE EXCEPTION 'Bikes have one wash type'; END IF;
  ELSIF v_freq = 2 AND NOT (v_bodies = 1 AND v_deeps = 1) THEN
    RAISE EXCEPTION '2 washes a week is 1 body wash + 1 deep cleaning';
  ELSIF v_freq >= 3 AND (v_bodies < 1 OR v_deeps < 1) THEN
    RAISE EXCEPTION '% washes a week mixes body washes and deep cleanings', v_freq;
  END IF;

  -- Lines: one per service
  FOR rec IN
    SELECT o.service_id, s.code, s.name, k.kind, k.n AS per_week
      FROM (SELECT e->>'kind' AS kind, count(*)::int AS n FROM jsonb_array_elements(p_weekly_pattern) e GROUP BY 1) k
      LEFT JOIN public.membership_service_options o ON o.vehicle_type = p_vehicle_type AND o.wash_kind = k.kind
      LEFT JOIN public.services s ON s.id = o.service_id
     ORDER BY k.kind
  LOOP
    IF rec.service_id IS NULL THEN
      RAISE EXCEPTION 'No % wash is offered for this vehicle', rec.kind;
    END IF;
    DECLARE
      v_unit integer := app_private.unit_price_cents(rec.service_id, p_vehicle_type);
      v_qty integer := rec.per_week * v_weeks * p_duration_months;
    BEGIN
      IF v_unit IS NULL THEN RAISE EXCEPTION 'No price is set for % on this vehicle', rec.name; END IF;
      v_lines := v_lines || jsonb_build_array(jsonb_build_object(
        'service_id', rec.service_id, 'code', rec.code, 'name', rec.name, 'kind', rec.kind,
        'per_week', rec.per_week, 'quantity', v_qty, 'unit_cents', v_unit, 'line_cents', v_unit::bigint * v_qty));
      v_subtotal := v_subtotal + v_unit::bigint * v_qty;
    END;
  END LOOP;

  SELECT discount_bp INTO v_freq_bp FROM public.membership_discount_rules WHERE active AND kind = 'frequency' AND key_value = v_freq;
  SELECT discount_bp INTO v_dur_bp  FROM public.membership_discount_rules WHERE active AND kind = 'duration'  AND key_value = p_duration_months;
  v_freq_bp := COALESCE(v_freq_bp, 0);
  v_dur_bp := COALESCE(v_dur_bp, 0);

  -- Sequential: frequency off the subtotal, then duration off what remains. Half-up rounding to the paisa.
  v_freq_cents := round(v_subtotal::numeric * v_freq_bp / 10000);
  v_dur_cents  := round((v_subtotal - v_freq_cents)::numeric * v_dur_bp / 10000);
  v_combined   := v_freq_cents + v_dur_cents;
  v_cap_cents  := round(v_subtotal::numeric * v_cap_bp / 10000);

  IF v_combined > v_cap_cents THEN
    v_cap_adj := v_combined - v_cap_cents;   -- the part of the discount the cap takes back
    v_total_discount := v_cap_cents;
  ELSE
    v_total_discount := v_combined;
  END IF;

  RETURN jsonb_build_object(
    'vehicle_type', p_vehicle_type,
    'frequency_per_week', v_freq,
    'duration_months', p_duration_months,
    'weeks_per_month', v_weeks,
    'washes_total', v_freq * v_weeks * p_duration_months,
    'lines', v_lines,
    'subtotal_cents', v_subtotal,
    'frequency_discount', jsonb_build_object('bp', v_freq_bp, 'cents', v_freq_cents, 'label', (SELECT label FROM public.membership_discount_rules WHERE active AND kind='frequency' AND key_value=v_freq)),
    'duration_discount',  jsonb_build_object('bp', v_dur_bp,  'cents', v_dur_cents,  'label', (SELECT label FROM public.membership_discount_rules WHERE active AND kind='duration'  AND key_value=p_duration_months)),
    'cap', jsonb_build_object('max_bp', v_cap_bp, 'applied', v_cap_adj > 0, 'adjustment_cents', v_cap_adj),
    'total_discount_cents', v_total_discount,
    'final_cents', v_subtotal - v_total_discount,
    'rounding', 'half_up_to_paisa'
  );
END;
$$;
REVOKE ALL ON FUNCTION app_private.compute_membership_quote(public.vehicle_type, jsonb, integer) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION app_private.compute_membership_quote(public.vehicle_type, jsonb, integer) TO service_role;

-- ───────────────────────── customer-facing estimate ─────────────────────────
-- Anyone may ask "what would this plan cost?" (the rate card is public already). Returns the full breakdown, every discount as its own
-- line. Nothing is stored and nothing is created.
CREATE OR REPLACE FUNCTION public.estimate_membership_price(p_vehicle_type public.vehicle_type, p_weekly_pattern jsonb, p_duration_months integer)
RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT app_private.compute_membership_quote(p_vehicle_type, p_weekly_pattern, p_duration_months);
$$;
REVOKE ALL ON FUNCTION public.estimate_membership_price(public.vehicle_type, jsonb, integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.estimate_membership_price(public.vehicle_type, jsonb, integer) TO anon, authenticated, service_role;

-- ═════════════ 20261004000011_direct_membership_checkout.sql ═════════════
-- 20261004000011_direct_membership_checkout.sql
-- SAFE / additive and re-runnable. The customer now PAYS DIRECTLY for a membership: no waiting for WASHO to approve a quote.
--
--   start_membership_checkout()  validates the plan (same rules as create_membership_request), prices it from the rate card
--   (same calculator, every discount explicit), records the price on the request and opens the pending payment, all in one
--   call. The server then opens the Razorpay order for exactly payment.amount_cents; nothing is created for the customer
--   (no membership, no washes) until settle_payment() has verified the money, exactly as before.
--
-- The earlier request -> WASHO quote -> accept path still works for requests that already exist (admin_review_membership_request,
-- accept_membership_quote). A customer who starts a new checkout supersedes their own unfinished one for that vehicle; if money
-- for the superseded attempt still arrives, settle_payment() records it as unfulfilled and raises a refund request.

CREATE OR REPLACE FUNCTION public.start_membership_checkout(
  p_vehicle_id uuid,
  p_weekly_pattern jsonb,
  p_duration_months integer,
  p_time_slot public.time_slot,
  p_start_date date,
  p_address_id uuid DEFAULT NULL,
  p_parking_location text DEFAULT NULL,
  p_customer_notes text DEFAULT NULL,
  p_target_completion_time text DEFAULT NULL
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_profile uuid := public.current_profile_id();
  v_pattern jsonb;
  v_same uuid;
  v_id uuid;
  v_req public.membership_requests%ROWTYPE;
  v_final bigint;
  v_pay jsonb;
BEGIN
  IF v_profile IS NULL OR NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = v_profile AND role = 'customer') THEN
    RAISE EXCEPTION 'Customer profile not found' USING ERRCODE = '42501';
  END IF;

  -- Retrying the very same plan while its payment is still open: hand back that payment instead of making another.
  IF jsonb_typeof(p_weekly_pattern) = 'array' AND jsonb_array_length(p_weekly_pattern) > 0 THEN
    BEGIN
      SELECT jsonb_agg(jsonb_build_object('weekday', (e->>'weekday')::int, 'kind', e->>'kind') ORDER BY (e->>'weekday')::int)
        INTO v_pattern FROM jsonb_array_elements(p_weekly_pattern) e;
      SELECT r.id INTO v_same
        FROM public.membership_requests r JOIN public.payments pay ON pay.id = r.payment_id
        JOIN public.vehicles v ON v.id = r.vehicle_id
       WHERE r.customer_profile_id = v_profile AND r.vehicle_id = p_vehicle_id AND r.status = 'accepted'
         AND pay.status = 'pending' AND pay.expires_at > now()
         AND r.weekly_pattern = v_pattern AND r.duration_months = p_duration_months AND r.time_slot = p_time_slot AND r.start_date = p_start_date
         AND r.address_id IS NOT DISTINCT FROM COALESCE(p_address_id, v.address_id)
       LIMIT 1;
    EXCEPTION WHEN OTHERS THEN
      v_same := NULL; -- malformed input is reported by the validation below
    END;
    IF v_same IS NOT NULL THEN
      v_pay := public.accept_membership_quote(v_same);
      RETURN v_pay || jsonb_build_object('request_id', v_same);
    END IF;
  END IF;

  -- A different plan for the same vehicle replaces this customer's unfinished checkout (it must not block a fresh one).
  UPDATE public.payments SET status = 'failed', updated_at = now()
   WHERE status = 'pending' AND id IN (SELECT payment_id FROM public.membership_requests
                                        WHERE customer_profile_id = v_profile AND vehicle_id = p_vehicle_id
                                          AND status IN ('quoted', 'accepted') AND payment_id IS NOT NULL);
  UPDATE public.membership_requests SET status = 'cancelled', updated_at = now()
   WHERE customer_profile_id = v_profile AND vehicle_id = p_vehicle_id AND status IN ('submitted', 'quoted', 'accepted');

  -- Validates everything (vehicle ownership, address, start date, the mix, the length) and stores the rate-card price.
  v_id := public.create_membership_request(p_vehicle_id, p_weekly_pattern, p_duration_months, p_time_slot, p_start_date,
                                           p_address_id, p_parking_location, p_customer_notes, p_target_completion_time);

  SELECT * INTO v_req FROM public.membership_requests WHERE id = v_id FOR UPDATE;
  v_final := (v_req.system_quote->>'final_cents')::bigint;
  UPDATE public.membership_requests
     SET status = 'quoted', adjustment_cents = 0, adjustment_reason = NULL, quoted_amount_cents = v_final::int,
         quoted_breakdown = v_req.system_quote || jsonb_build_object('adjustment', jsonb_build_object('cents', 0, 'reason', NULL), 'final_cents', v_final),
         quote_expires_at = now() + make_interval(mins => app_private.setting('payment_intent_minutes') + 5),
         reviewed_at = now(), updated_at = now()
   WHERE id = v_id;

  PERFORM app_private.audit('membership_request', v_id, 'membership_checkout_started',
    jsonb_build_object('quoted_amount_cents', v_final, 'frequency_per_week', v_req.frequency_per_week, 'duration_months', v_req.duration_months));

  -- Opens the pending payment for exactly the stored price.
  v_pay := public.accept_membership_quote(v_id);
  RETURN v_pay || jsonb_build_object('request_id', v_id);
END $$;

REVOKE ALL ON FUNCTION public.start_membership_checkout(uuid, jsonb, integer, public.time_slot, date, uuid, text, text, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.start_membership_checkout(uuid, jsonb, integer, public.time_slot, date, uuid, text, text, text) TO authenticated;

-- ═════════════ 20261004000012_refund_workflow.sql ═════════════
-- 20261004000012_refund_workflow.sql
-- SAFE / additive and re-runnable. Cancelling a paid wash now ends in a full refund that only an ADMIN can release.
--
--   customer cancels a paid on-demand wash  ->  refunds row 'requested' for the FULL amount paid (no cutoff, no deduction)
--   admin presses "Approve and refund"      ->  admin_begin_refund() claims it ('approved'); the website server asks Razorpay to
--                                               refund the original payment; on success admin_finish_refund() records the
--                                               Razorpay refund id ('processed', booking event 'refunded'); if Razorpay
--                                               refuses, admin_fail_refund() keeps the reason and the admin can try again.
--
-- cancel_customer_booking() moves here from cutover/20261005000001 so it works before the cutover. The refund step is the
-- only new behaviour; it does not touch credits. (Production has no membership bookings or credit-paid washes today.)
-- Membership washes still cannot be cancelled by customers; they reschedule (admins may cancel).
--
-- Nothing here pays money out by itself: the database only records the decision. Razorpay is called by the server.

ALTER TABLE public.refunds ADD COLUMN IF NOT EXISTS approved_at timestamptz;
ALTER TABLE public.refunds ADD COLUMN IF NOT EXISTS failure_reason text;

-- ───────────────────────── cancellation (full refund request for a paid wash) ─────────────────────────
CREATE OR REPLACE FUNCTION public.cancel_customer_booking(p_booking_id uuid, p_reason text DEFAULT 'Customer requested cancellation')
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_actor uuid := public.current_profile_id();
  v_admin boolean := public.is_admin();
  v_booking public.bookings%ROWTYPE;
  v_pay public.payments%ROWTYPE;
  v_reason text := COALESCE(NULLIF(trim(p_reason), ''), 'Customer requested cancellation');
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501'; END IF;
  SELECT * INTO v_booking FROM public.bookings WHERE id = p_booking_id FOR UPDATE;
  IF NOT FOUND OR (v_booking.customer_profile_id <> v_actor AND NOT v_admin) THEN RAISE EXCEPTION 'Booking not found'; END IF;

  IF v_booking.status NOT IN ('pending', 'confirmed', 'worker_assigned', 'worker_called', 'call_not_picked_up') THEN
    RAISE EXCEPTION 'This booking can no longer be cancelled (it is %)', v_booking.status;
  END IF;
  IF v_booking.booking_type = 'membership' AND NOT v_admin THEN
    RAISE EXCEPTION 'Membership washes can be rescheduled but not cancelled. Please reschedule it, or contact WASHO.';
  END IF;

  UPDATE public.bookings
     SET status = 'cancelled', cancel_reason = v_reason, updated_at = now(),
         notes = COALESCE(notes || E'\n', '') || 'Cancelled: ' || v_reason
   WHERE id = p_booking_id;
  IF v_booking.membership_schedule_occurrence_id IS NOT NULL THEN
    UPDATE public.membership_schedule_occurrences SET status = 'cancelled', updated_at = now() WHERE id = v_booking.membership_schedule_occurrence_id;
  END IF;
  UPDATE public.worker_assignments SET is_active = false, unassigned_at = now() WHERE booking_id = p_booking_id AND is_active;

  INSERT INTO public.booking_events (booking_id, event_type, actor_profile_id, event_metadata)
  VALUES (p_booking_id, 'cancelled', v_actor, jsonb_build_object('reason', v_reason, 'cancelled_by', CASE WHEN v_admin THEN 'admin' ELSE 'customer' END));

  -- A paid on-demand wash that is cancelled raises a refund REQUEST for exactly what was paid. An admin approves it.
  SELECT * INTO v_pay FROM public.payments WHERE booking_id = p_booking_id AND status = 'paid' ORDER BY paid_at DESC LIMIT 1;
  IF FOUND AND NOT EXISTS (SELECT 1 FROM public.refunds WHERE payment_id = v_pay.id AND status <> 'reversed') THEN
    INSERT INTO public.refunds (payment_id, booking_id, customer_profile_id, amount_cents, reason, status)
    VALUES (v_pay.id, p_booking_id, v_pay.customer_profile_id, v_pay.amount_cents, 'Booking cancelled: ' || v_reason, 'requested');
    INSERT INTO public.booking_events (booking_id, event_type, actor_profile_id, event_metadata)
    VALUES (p_booking_id, 'refund_requested', v_actor, jsonb_build_object('payment_id', v_pay.id, 'amount_cents', v_pay.amount_cents));
  END IF;
  RETURN true;
END $$;
REVOKE ALL ON FUNCTION public.cancel_customer_booking(uuid, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.cancel_customer_booking(uuid, text) TO authenticated;

-- ───────────────────────── admin: approve and pay a refund ─────────────────────────
-- Step 1. Claims the refund so two admins cannot pay it twice, and hands the server what it needs to call Razorpay.
-- A refund already claimed less than two minutes ago is refused; an older claim means the server died mid-call, and the
-- server checks Razorpay for an existing refund before it creates another.
CREATE OR REPLACE FUNCTION public.admin_begin_refund(p_refund_id uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_r public.refunds%ROWTYPE;
  v_pay public.payments%ROWTYPE;
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'Unauthorized: admin access required' USING ERRCODE = '42501'; END IF;
  SELECT * INTO v_r FROM public.refunds WHERE id = p_refund_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Refund not found'; END IF;
  IF v_r.status IN ('processed', 'reversed') THEN RAISE EXCEPTION 'This refund is already %', v_r.status; END IF;
  IF v_r.status = 'approved' AND v_r.approved_at IS NOT NULL AND v_r.approved_at > now() - interval '2 minutes' THEN
    RAISE EXCEPTION 'This refund is already being paid out. Check again in a minute.';
  END IF;
  SELECT * INTO v_pay FROM public.payments WHERE id = v_r.payment_id;
  IF v_pay.provider IS DISTINCT FROM 'razorpay' OR v_pay.provider_payment_id IS NULL OR v_pay.status NOT IN ('paid', 'partially_refunded') THEN
    RAISE EXCEPTION 'This payment has no captured Razorpay payment to refund. Record the refund by hand instead.';
  END IF;

  UPDATE public.refunds SET status = 'approved', approved_at = now(), failure_reason = NULL, updated_at = now() WHERE id = p_refund_id;
  PERFORM app_private.audit('refund', p_refund_id, 'refund_approved', jsonb_build_object('from', v_r.status, 'amount_cents', v_r.amount_cents));
  RETURN jsonb_build_object(
    'refund_id', v_r.id, 'amount_cents', v_r.amount_cents, 'currency', v_pay.currency,
    'provider_payment_id', v_pay.provider_payment_id, 'booking_id', v_r.booking_id
  );
END $$;
REVOKE ALL ON FUNCTION public.admin_begin_refund(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.admin_begin_refund(uuid) TO authenticated; -- is_admin() inside

-- Step 2a. Razorpay accepted the refund: record its id, tell the customer's timeline, and mark the payment refunded.
CREATE OR REPLACE FUNCTION public.admin_finish_refund(p_refund_id uuid, p_provider_refund_id text)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_r public.refunds%ROWTYPE;
  v_pay public.payments%ROWTYPE;
  v_done integer;
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'Unauthorized: admin access required' USING ERRCODE = '42501'; END IF;
  IF p_provider_refund_id IS NULL OR char_length(trim(p_provider_refund_id)) < 4 THEN
    RAISE EXCEPTION 'Enter the Razorpay refund id so the payout can be traced';
  END IF;
  SELECT * INTO v_r FROM public.refunds WHERE id = p_refund_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Refund not found'; END IF;
  IF v_r.status = 'processed' AND v_r.provider_refund_id = trim(p_provider_refund_id) THEN RETURN true; END IF; -- idempotent
  IF v_r.status IN ('processed', 'reversed') THEN RAISE EXCEPTION 'This refund is already %', v_r.status; END IF;

  UPDATE public.refunds
     SET status = 'processed', provider_refund_id = trim(p_provider_refund_id), failure_reason = NULL, updated_at = now()
   WHERE id = p_refund_id;

  SELECT * INTO v_pay FROM public.payments WHERE id = v_r.payment_id FOR UPDATE;
  SELECT COALESCE(sum(amount_cents), 0) INTO v_done FROM public.refunds WHERE payment_id = v_r.payment_id AND status = 'processed';
  UPDATE public.payments
     SET status = CASE WHEN v_done >= v_pay.amount_cents THEN 'refunded'::public.payment_status ELSE 'partially_refunded'::public.payment_status END,
         updated_at = now()
   WHERE id = v_r.payment_id AND status IN ('paid', 'partially_refunded');

  IF v_r.booking_id IS NOT NULL THEN
    INSERT INTO public.booking_events (booking_id, event_type, actor_profile_id, event_metadata)
    VALUES (v_r.booking_id, 'refunded', public.current_profile_id(),
            jsonb_build_object('refund_id', v_r.id, 'amount_cents', v_r.amount_cents, 'provider_refund_id', trim(p_provider_refund_id)));
  END IF;
  PERFORM app_private.audit('refund', p_refund_id, 'refund_processed', jsonb_build_object('provider_refund_id', trim(p_provider_refund_id), 'amount_cents', v_r.amount_cents));
  RETURN true;
END $$;
REVOKE ALL ON FUNCTION public.admin_finish_refund(uuid, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.admin_finish_refund(uuid, text) TO authenticated; -- is_admin() inside

-- Step 2b. Razorpay refused (or could not be reached): keep why, leave it retryable.
CREATE OR REPLACE FUNCTION public.admin_fail_refund(p_refund_id uuid, p_reason text)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE v_old public.refund_status;
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'Unauthorized: admin access required' USING ERRCODE = '42501'; END IF;
  SELECT status INTO v_old FROM public.refunds WHERE id = p_refund_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Refund not found'; END IF;
  IF v_old IN ('processed', 'reversed') THEN RAISE EXCEPTION 'This refund is already %', v_old; END IF;
  UPDATE public.refunds
     SET status = 'failed', failure_reason = left(COALESCE(NULLIF(trim(p_reason), ''), 'Razorpay did not accept the refund'), 300), updated_at = now()
   WHERE id = p_refund_id;
  PERFORM app_private.audit('refund', p_refund_id, 'refund_failed', jsonb_build_object('from', v_old, 'reason', left(COALESCE(p_reason, ''), 300)));
  RETURN true;
END $$;
REVOKE ALL ON FUNCTION public.admin_fail_refund(uuid, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.admin_fail_refund(uuid, text) TO authenticated; -- is_admin() inside

-- Recording a refund you paid by hand in the Razorpay dashboard still works; 'processed' now goes through the same
-- bookkeeping as the automatic path (booking event, payment marked refunded).
CREATE OR REPLACE FUNCTION public.admin_resolve_refund(p_refund_id uuid, p_status public.refund_status, p_provider_refund_id text DEFAULT NULL)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE v_old public.refund_status;
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'Unauthorized: admin access required' USING ERRCODE = '42501'; END IF;
  IF p_status NOT IN ('approved', 'processed', 'failed') THEN RAISE EXCEPTION 'A refund can be marked approved, processed or failed'; END IF;
  IF p_status = 'processed' THEN RETURN public.admin_finish_refund(p_refund_id, p_provider_refund_id); END IF;
  SELECT status INTO v_old FROM public.refunds WHERE id = p_refund_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Refund not found'; END IF;
  IF v_old IN ('processed', 'reversed') THEN RAISE EXCEPTION 'This refund is already %', v_old; END IF;
  UPDATE public.refunds SET status = p_status, provider_refund_id = COALESCE(NULLIF(trim(p_provider_refund_id), ''), provider_refund_id), updated_at = now() WHERE id = p_refund_id;
  PERFORM app_private.audit('refund', p_refund_id, 'refund_' || p_status::text, jsonb_build_object('from', v_old, 'provider_refund_id', p_provider_refund_id));
  RETURN true;
END $$;
REVOKE ALL ON FUNCTION public.admin_resolve_refund(uuid, public.refund_status, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.admin_resolve_refund(uuid, public.refund_status, text) TO authenticated; -- is_admin() inside

-- ═════════════ 20261004000013_admin_management.sql ═════════════
-- 20261004000013_admin_management.sql
-- SAFE / additive and re-runnable. What the Admin page needs to create, edit and "delete" people, washes, services and prices.
--
-- Nothing here deletes data. "Delete" means ARCHIVE: the row stays (payments, refunds and wash history always point at something),
-- it disappears from the working lists, and it can be restored. The existing admin_delete_* functions (which hard-delete, and exist
-- for the mobile app) are not used by the website.
--
--   profiles.archived_at / customer_addresses.archived_at      NULL = in use
--   admin_update_customer_profile      name + email only (a customer's phone is their sign-in; they verify it themselves)
--   admin_set_profile_archived         archive/restore a customer or specialist, with the safety rules below
--   admin_save_vehicle / admin_set_vehicle_active
--   admin_save_address / admin_set_address_archived
--   admin_create_booking               a wash booked for a customer by WASHO (paid in cash, or complimentary)
--   admin_update_booking_details       address, parking spot, note
--   admin_save_service / admin_set_service_active / admin_set_service_price (versioned) / admin_set_discount / admin_remove_discount /
--   admin_set_pricing_setting
--
-- Rules the database enforces (not just the screens):
--   * a customer with scheduled washes or an active membership cannot be archived
--   * a specialist is archived by returning their upcoming washes to the pool; one with a wash in progress cannot be archived
--   * an archived specialist can never be assigned a wash or made a membership's regular specialist
--   * prices are never edited in place: the old rule is closed and a new one starts, so history stays readable
--   * every change writes an audit event

ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS archived_at timestamptz;
ALTER TABLE public.customer_addresses ADD COLUMN IF NOT EXISTS archived_at timestamptz;

CREATE OR REPLACE FUNCTION app_private.require_admin() RETURNS uuid
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'Unauthorized: admin access required' USING ERRCODE = '42501'; END IF;
  RETURN public.current_profile_id();
END $$;
REVOKE ALL ON FUNCTION app_private.require_admin() FROM PUBLIC, anon, authenticated;

-- ───────────────────────── an archived specialist is never given work ─────────────────────────
CREATE OR REPLACE FUNCTION app_private.refuse_archived_assignment() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM public.profiles WHERE id = NEW.worker_profile_id AND archived_at IS NOT NULL) THEN
    RAISE EXCEPTION 'That specialist is archived. Restore them first, or choose someone else.';
  END IF;
  RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION app_private.refuse_archived_assignment() FROM PUBLIC, anon, authenticated;

CREATE OR REPLACE FUNCTION app_private.refuse_archived_regular_specialist() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF NEW.assigned_worker_profile_id IS NOT NULL AND EXISTS (SELECT 1 FROM public.profiles WHERE id = NEW.assigned_worker_profile_id AND archived_at IS NOT NULL) THEN
    RAISE EXCEPTION 'That specialist is archived. Restore them first, or choose someone else.';
  END IF;
  RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION app_private.refuse_archived_regular_specialist() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS worker_assignments_not_archived ON public.worker_assignments;
CREATE TRIGGER worker_assignments_not_archived BEFORE INSERT ON public.worker_assignments
  FOR EACH ROW EXECUTE FUNCTION app_private.refuse_archived_assignment();
DROP TRIGGER IF EXISTS memberships_assignee_not_archived ON public.memberships;
CREATE TRIGGER memberships_assignee_not_archived BEFORE INSERT OR UPDATE OF assigned_worker_profile_id ON public.memberships
  FOR EACH ROW EXECUTE FUNCTION app_private.refuse_archived_regular_specialist();

-- ───────────────────────── customers ─────────────────────────
CREATE OR REPLACE FUNCTION public.admin_update_customer_profile(p_customer_id uuid, p_full_name text, p_email text DEFAULT NULL)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_name text := trim(COALESCE(p_full_name, ''));
  v_email text := NULLIF(lower(trim(COALESCE(p_email, ''))), '');
BEGIN
  PERFORM app_private.require_admin();
  IF char_length(v_name) < 2 OR char_length(v_name) > 80 THEN RAISE EXCEPTION 'Enter the customer''s full name'; END IF;
  IF v_email IS NOT NULL AND (char_length(v_email) > 160 OR v_email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$') THEN
    RAISE EXCEPTION 'Enter a valid email address';
  END IF;
  UPDATE public.profiles SET full_name = v_name, email = v_email, updated_at = now() WHERE id = p_customer_id AND role = 'customer';
  IF NOT FOUND THEN RAISE EXCEPTION 'Customer not found'; END IF;
  PERFORM app_private.audit('profile', p_customer_id, 'customer_updated', jsonb_build_object('full_name', v_name, 'email', v_email));
  RETURN true;
END $$;

CREATE OR REPLACE FUNCTION public.admin_set_profile_archived(p_profile_id uuid, p_archived boolean, p_reason text DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_me uuid := app_private.require_admin();
  v_p public.profiles%ROWTYPE;
  v_today date := (now() AT TIME ZONE 'Asia/Kolkata')::date;
  v_live integer;
  v_members integer;
  v_released integer := 0;
  v_released_members integer := 0;
  b record;
  m record;
BEGIN
  IF p_profile_id = v_me THEN RAISE EXCEPTION 'You cannot archive your own account'; END IF;
  SELECT * INTO v_p FROM public.profiles WHERE id = p_profile_id FOR UPDATE;
  IF NOT FOUND OR v_p.role NOT IN ('customer', 'worker') THEN RAISE EXCEPTION 'Person not found'; END IF;

  IF NOT p_archived THEN
    UPDATE public.profiles SET archived_at = NULL, updated_at = now() WHERE id = p_profile_id;
    PERFORM app_private.audit('profile', p_profile_id, 'profile_restored', jsonb_build_object('role', v_p.role));
    RETURN jsonb_build_object('archived', false, 'auth_user_id', v_p.auth_user_id);
  END IF;
  IF v_p.archived_at IS NOT NULL THEN RETURN jsonb_build_object('archived', true, 'released_washes', 0, 'released_memberships', 0, 'auth_user_id', v_p.auth_user_id); END IF;

  IF v_p.role = 'customer' THEN
    SELECT count(*) INTO v_live FROM public.bookings
     WHERE customer_profile_id = p_profile_id AND status IN ('pending', 'confirmed', 'worker_assigned', 'worker_called', 'call_not_picked_up', 'in_progress');
    SELECT count(*) INTO v_members FROM public.memberships WHERE customer_profile_id = p_profile_id AND status = 'active';
    IF v_live > 0 OR v_members > 0 THEN
      RAISE EXCEPTION 'This customer still has % scheduled wash(es) and % active membership(s). Cancel them first, then archive.', v_live, v_members;
    END IF;
  ELSE
    IF EXISTS (SELECT 1 FROM public.worker_assignments wa JOIN public.bookings bk ON bk.id = wa.booking_id
                WHERE wa.worker_profile_id = p_profile_id AND wa.is_active AND bk.status = 'in_progress') THEN
      RAISE EXCEPTION 'This specialist has a wash in progress. Wait until it is finished.';
    END IF;
    -- Regular specialist of memberships: release those washes to the pool (the existing function does the bookkeeping).
    FOR m IN SELECT id FROM public.memberships WHERE assigned_worker_profile_id = p_profile_id AND status = 'active' LOOP
      PERFORM public.admin_assign_membership_worker(m.id, NULL);
      v_released_members := v_released_members + 1;
    END LOOP;
    -- Everything else they were due to do goes back to the pool too.
    FOR b IN
      SELECT bk.id FROM public.worker_assignments wa JOIN public.bookings bk ON bk.id = wa.booking_id
       WHERE wa.worker_profile_id = p_profile_id AND wa.is_active AND bk.scheduled_date >= v_today
         AND bk.status IN ('confirmed', 'worker_assigned', 'worker_called', 'call_not_picked_up')
       FOR UPDATE OF bk
    LOOP
      UPDATE public.worker_assignments SET is_active = false, unassigned_at = now() WHERE booking_id = b.id AND is_active;
      UPDATE public.bookings SET status = 'confirmed', customer_confirmed_at = NULL, updated_at = now() WHERE id = b.id;
      INSERT INTO public.booking_events (booking_id, event_type, actor_profile_id, event_metadata)
      VALUES (b.id, 'admin_booking_updated', v_me, jsonb_build_object('released_from_worker', p_profile_id, 'reason', 'specialist archived'));
      v_released := v_released + 1;
    END LOOP;
  END IF;

  UPDATE public.profiles SET archived_at = now(), updated_at = now() WHERE id = p_profile_id;
  PERFORM app_private.audit('profile', p_profile_id, 'profile_archived',
    jsonb_build_object('role', v_p.role, 'reason', left(COALESCE(p_reason, ''), 200), 'released_washes', v_released, 'released_memberships', v_released_members));
  RETURN jsonb_build_object('archived', true, 'released_washes', v_released, 'released_memberships', v_released_members, 'auth_user_id', v_p.auth_user_id);
END $$;

-- Setting a specialist's password is done by Supabase Auth (the server calls it); this checks who it is for and leaves the audit trail.
CREATE OR REPLACE FUNCTION public.admin_begin_password_reset(p_worker_profile_id uuid)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE v_auth uuid;
BEGIN
  PERFORM app_private.require_admin();
  SELECT auth_user_id INTO v_auth FROM public.profiles WHERE id = p_worker_profile_id AND role = 'worker' AND archived_at IS NULL;
  IF v_auth IS NULL THEN RAISE EXCEPTION 'Specialist not found'; END IF;
  PERFORM app_private.audit('profile', p_worker_profile_id, 'worker_password_reset', '{}'::jsonb);
  RETURN v_auth;
END $$;

-- ───────────────────────── a customer's vehicles ─────────────────────────
CREATE OR REPLACE FUNCTION public.admin_save_vehicle(
  p_vehicle_id uuid, p_customer_id uuid, p_vehicle_type public.vehicle_type, p_make text, p_model text,
  p_registration_number text, p_color text DEFAULT NULL, p_address_id uuid DEFAULT NULL, p_parking_location text DEFAULT NULL
) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_model text := trim(COALESCE(p_model, ''));
  v_reg text := upper(regexp_replace(trim(COALESCE(p_registration_number, '')), '\s+', ' ', 'g'));
  v_old public.vehicles%ROWTYPE;
  v_id uuid;
BEGIN
  PERFORM app_private.require_admin();
  IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = p_customer_id AND role = 'customer') THEN RAISE EXCEPTION 'Customer not found'; END IF;
  IF char_length(v_model) < 1 OR char_length(v_model) > 60 THEN RAISE EXCEPTION 'Enter the model'; END IF;
  IF char_length(v_reg) < 4 OR char_length(v_reg) > 20 THEN RAISE EXCEPTION 'Enter the registration number'; END IF;
  IF p_address_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.customer_addresses WHERE id = p_address_id AND customer_profile_id = p_customer_id AND archived_at IS NULL) THEN
    RAISE EXCEPTION 'Address not found';
  END IF;

  BEGIN
    IF p_vehicle_id IS NULL THEN
      INSERT INTO public.vehicles (customer_profile_id, vehicle_type, make, model, registration_number, color, address_id, parking_location)
      VALUES (p_customer_id, p_vehicle_type, COALESCE(trim(p_make), ''), v_model, v_reg, NULLIF(trim(COALESCE(p_color, '')), ''), p_address_id, NULLIF(trim(COALESCE(p_parking_location, '')), ''))
      RETURNING id INTO v_id;
      PERFORM app_private.audit('vehicle', v_id, 'vehicle_created_by_admin', jsonb_build_object('customer_id', p_customer_id, 'registration', v_reg));
    ELSE
      SELECT * INTO v_old FROM public.vehicles WHERE id = p_vehicle_id AND customer_profile_id = p_customer_id FOR UPDATE;
      IF NOT FOUND THEN RAISE EXCEPTION 'Vehicle not found'; END IF;
      IF v_old.vehicle_type <> p_vehicle_type AND EXISTS (SELECT 1 FROM public.bookings WHERE vehicle_id = p_vehicle_id) THEN
        RAISE EXCEPTION 'This vehicle has wash history, so its type cannot be changed. Archive it and add a new one.';
      END IF;
      UPDATE public.vehicles
         SET vehicle_type = p_vehicle_type, make = COALESCE(trim(p_make), ''), model = v_model, registration_number = v_reg,
             color = NULLIF(trim(COALESCE(p_color, '')), ''), address_id = p_address_id,
             parking_location = NULLIF(trim(COALESCE(p_parking_location, '')), ''), updated_at = now()
       WHERE id = p_vehicle_id;
      v_id := p_vehicle_id;
      PERFORM app_private.audit('vehicle', v_id, 'vehicle_updated_by_admin', jsonb_build_object('customer_id', p_customer_id, 'registration', v_reg));
    END IF;
  EXCEPTION WHEN unique_violation THEN
    RAISE EXCEPTION 'This customer already has a vehicle with that registration number';
  END;
  RETURN v_id;
END $$;

CREATE OR REPLACE FUNCTION public.admin_set_vehicle_active(p_vehicle_id uuid, p_active boolean)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE v_v public.vehicles%ROWTYPE;
BEGIN
  PERFORM app_private.require_admin();
  SELECT * INTO v_v FROM public.vehicles WHERE id = p_vehicle_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Vehicle not found'; END IF;
  IF NOT p_active AND (
       EXISTS (SELECT 1 FROM public.bookings WHERE vehicle_id = p_vehicle_id AND status IN ('pending', 'confirmed', 'worker_assigned', 'worker_called', 'call_not_picked_up', 'in_progress'))
    OR EXISTS (SELECT 1 FROM public.membership_services ms JOIN public.memberships m ON m.id = ms.membership_id WHERE ms.vehicle_id = p_vehicle_id AND m.status = 'active')
  ) THEN
    RAISE EXCEPTION 'This vehicle has scheduled washes or an active membership. Cancel those first.';
  END IF;
  BEGIN
    UPDATE public.vehicles SET is_active = p_active, updated_at = now() WHERE id = p_vehicle_id;
  EXCEPTION WHEN unique_violation THEN
    RAISE EXCEPTION 'The customer has another vehicle with this registration number, so this one cannot be restored';
  END;
  PERFORM app_private.audit('vehicle', p_vehicle_id, CASE WHEN p_active THEN 'vehicle_restored' ELSE 'vehicle_archived' END, jsonb_build_object('customer_id', v_v.customer_profile_id));
  RETURN true;
END $$;

-- ───────────────────────── a customer's addresses ─────────────────────────
CREATE OR REPLACE FUNCTION public.admin_save_address(
  p_address_id uuid, p_customer_id uuid, p_label text, p_society_name text, p_building_block text, p_flat_number text,
  p_parking_location text, p_area_locality text DEFAULT 'Kharadi', p_city text DEFAULT 'Pune', p_pincode text DEFAULT '411014', p_is_default boolean DEFAULT false
) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_id uuid;
  v_first boolean;
BEGIN
  PERFORM app_private.require_admin();
  IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = p_customer_id AND role = 'customer') THEN RAISE EXCEPTION 'Customer not found'; END IF;
  IF char_length(trim(COALESCE(p_society_name, ''))) < 2 THEN RAISE EXCEPTION 'Enter the society or building'; END IF;
  IF char_length(trim(COALESCE(p_building_block, ''))) < 1 THEN RAISE EXCEPTION 'Enter the block or wing'; END IF;
  IF char_length(trim(COALESCE(p_flat_number, ''))) < 1 THEN RAISE EXCEPTION 'Enter the flat number'; END IF;
  IF char_length(trim(COALESCE(p_parking_location, ''))) < 2 THEN RAISE EXCEPTION 'Tell us where the vehicle is parked'; END IF;
  IF COALESCE(p_pincode, '') !~ '^\d{6}$' THEN RAISE EXCEPTION 'Enter a 6-digit pincode'; END IF;

  SELECT NOT EXISTS (SELECT 1 FROM public.customer_addresses WHERE customer_profile_id = p_customer_id AND archived_at IS NULL AND id IS DISTINCT FROM p_address_id) INTO v_first;
  IF p_address_id IS NULL THEN
    INSERT INTO public.customer_addresses (customer_profile_id, label, society_name, building_block, flat_number, parking_location, area_locality, city, pincode, is_default)
    VALUES (p_customer_id, COALESCE(NULLIF(trim(p_label), ''), 'Home'), trim(p_society_name), trim(p_building_block), trim(p_flat_number), trim(p_parking_location),
            COALESCE(NULLIF(trim(p_area_locality), ''), 'Kharadi'), COALESCE(NULLIF(trim(p_city), ''), 'Pune'), p_pincode, false)
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.customer_addresses
       SET label = COALESCE(NULLIF(trim(p_label), ''), label), society_name = trim(p_society_name), building_block = trim(p_building_block), flat_number = trim(p_flat_number),
           parking_location = trim(p_parking_location), area_locality = COALESCE(NULLIF(trim(p_area_locality), ''), area_locality),
           city = COALESCE(NULLIF(trim(p_city), ''), city), pincode = p_pincode, updated_at = now()
     WHERE id = p_address_id AND customer_profile_id = p_customer_id AND archived_at IS NULL
     RETURNING id INTO v_id;
    IF v_id IS NULL THEN RAISE EXCEPTION 'Address not found'; END IF;
  END IF;
  IF p_is_default OR v_first THEN
    UPDATE public.customer_addresses SET is_default = false WHERE customer_profile_id = p_customer_id AND is_default AND id <> v_id;
    UPDATE public.customer_addresses SET is_default = true WHERE id = v_id;
  END IF;
  PERFORM app_private.audit('address', v_id, CASE WHEN p_address_id IS NULL THEN 'address_created_by_admin' ELSE 'address_updated_by_admin' END, jsonb_build_object('customer_id', p_customer_id));
  RETURN v_id;
END $$;

CREATE OR REPLACE FUNCTION public.admin_set_address_archived(p_address_id uuid, p_archived boolean)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE v_a public.customer_addresses%ROWTYPE;
BEGIN
  PERFORM app_private.require_admin();
  SELECT * INTO v_a FROM public.customer_addresses WHERE id = p_address_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Address not found'; END IF;
  IF p_archived THEN
    IF EXISTS (SELECT 1 FROM public.bookings WHERE address_id = p_address_id AND status IN ('pending', 'confirmed', 'worker_assigned', 'worker_called', 'call_not_picked_up', 'in_progress')) THEN
      RAISE EXCEPTION 'A scheduled wash uses this address. Change that wash''s address first.';
    END IF;
    UPDATE public.customer_addresses SET archived_at = now(), is_default = false, updated_at = now() WHERE id = p_address_id;
    UPDATE public.vehicles SET address_id = NULL, updated_at = now() WHERE address_id = p_address_id;
  ELSE
    UPDATE public.customer_addresses SET archived_at = NULL, updated_at = now() WHERE id = p_address_id;
  END IF;
  PERFORM app_private.audit('address', p_address_id, CASE WHEN p_archived THEN 'address_archived' ELSE 'address_restored' END, jsonb_build_object('customer_id', v_a.customer_profile_id));
  RETURN true;
END $$;

-- ───────────────────────── washes ─────────────────────────
-- A wash WASHO books for a customer. p_payment:
--   'cash'    the customer paid WASHO directly: a paid offline payment at the rate-card price (a cancellation is refunded by hand)
--   'online'  the customer paid through Razorpay but the booking never got recorded (the browser lost the thread). The admin has checked
--             the Razorpay dashboard and the server has asked Razorpay: p_provider_payment_id / p_provider_amount_cents are what Razorpay
--             reported. The amount must equal the rate-card price, and one Razorpay payment can only be recorded once. A cancellation
--             can then be refunded through Razorpay like any other online payment.
--   'free'    complimentary: price 0, no payment, nothing to refund.
CREATE OR REPLACE FUNCTION public.admin_create_booking(
  p_customer_id uuid, p_vehicle_id uuid, p_service_id uuid, p_scheduled_date date, p_time_slot public.time_slot,
  p_address_id uuid DEFAULT NULL, p_parking_location text DEFAULT NULL, p_payment text DEFAULT 'cash', p_note text DEFAULT NULL,
  p_provider_payment_id text DEFAULT NULL, p_provider_amount_cents integer DEFAULT NULL
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_admin uuid := app_private.require_admin();
  v_vehicle public.vehicles%ROWTYPE;
  v_service public.services%ROWTYPE;
  v_addr uuid := p_address_id;
  v_price integer;
  v_parking text;
  v_booking uuid;
  v_pay uuid;
  v_note text := NULLIF(trim(COALESCE(p_note, '')), '');
BEGIN
  IF p_payment NOT IN ('cash', 'online', 'free') THEN RAISE EXCEPTION 'Choose how this wash is paid'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = p_customer_id AND role = 'customer' AND archived_at IS NULL) THEN RAISE EXCEPTION 'Customer not found'; END IF;
  SELECT * INTO v_vehicle FROM public.vehicles WHERE id = p_vehicle_id AND customer_profile_id = p_customer_id AND is_active;
  IF NOT FOUND THEN RAISE EXCEPTION 'Vehicle not found'; END IF;
  SELECT * INTO v_service FROM public.services WHERE id = p_service_id AND is_active;
  IF NOT FOUND THEN RAISE EXCEPTION 'Service not found'; END IF;
  IF NOT (v_service.vehicle_type = v_vehicle.vehicle_type OR (v_vehicle.vehicle_type = 'suv' AND v_service.vehicle_type = 'car')) THEN
    RAISE EXCEPTION 'This service is not available for that vehicle';
  END IF;
  IF v_addr IS NULL THEN v_addr := v_vehicle.address_id; END IF;
  IF v_addr IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.customer_addresses WHERE id = v_addr AND customer_profile_id = p_customer_id AND archived_at IS NULL) THEN
    RAISE EXCEPTION 'Address not found';
  END IF;
  IF p_scheduled_date IS NULL OR p_scheduled_date < (now() AT TIME ZONE 'Asia/Kolkata')::date THEN RAISE EXCEPTION 'Choose today or a later date'; END IF;
  IF app_private.vehicle_has_live_booking(p_vehicle_id, p_scheduled_date) THEN RAISE EXCEPTION 'This vehicle already has a wash booked that day'; END IF;

  IF p_payment IN ('cash', 'online') THEN
    v_price := app_private.unit_price_cents(v_service.id, v_vehicle.vehicle_type);
    IF v_price IS NULL OR v_price < 100 THEN RAISE EXCEPTION 'No price is set for this service'; END IF;
  ELSE
    v_price := 0;
  END IF;
  IF p_payment = 'online' THEN
    IF NULLIF(trim(COALESCE(p_provider_payment_id, '')), '') IS NULL THEN RAISE EXCEPTION 'Paste the Razorpay payment id'; END IF;
    IF p_provider_amount_cents IS DISTINCT FROM v_price THEN
      RAISE EXCEPTION 'That Razorpay payment is for ₹% but this wash costs ₹%', trim_scale(COALESCE(p_provider_amount_cents, 0) / 100.0), trim_scale(v_price / 100.0);
    END IF;
    IF EXISTS (SELECT 1 FROM public.payments WHERE provider_payment_id = trim(p_provider_payment_id)) THEN
      RAISE EXCEPTION 'That Razorpay payment is already recorded against another booking';
    END IF;
  END IF;
  v_parking := COALESCE(NULLIF(trim(COALESCE(p_parking_location, '')), ''), v_vehicle.parking_location);

  INSERT INTO public.bookings (customer_profile_id, vehicle_id, service_id, booking_type, scheduled_date, time_slot, status, notes, address_id, parking_location, source, price_cents)
  VALUES (p_customer_id, p_vehicle_id, v_service.id, 'on_demand', p_scheduled_date, p_time_slot, 'confirmed',
          COALESCE(v_note, v_parking, 'Booked by WASHO'), v_addr, v_parking, 'admin', v_price)
  RETURNING id INTO v_booking;

  INSERT INTO public.booking_events (booking_id, event_type, actor_profile_id, event_metadata)
  VALUES (v_booking, 'booking_created', v_admin, jsonb_build_object('booking_type', 'on_demand', 'source', 'admin', 'payment', p_payment));

  IF p_payment IN ('cash', 'online') THEN
    INSERT INTO public.payments (customer_profile_id, booking_id, amount_cents, currency, provider, provider_payment_id, status, paid_at, payment_kind, receipt, fulfilment_status, intent)
    VALUES (p_customer_id, v_booking, v_price, 'INR', CASE WHEN p_payment = 'online' THEN 'razorpay' ELSE 'offline' END,
            CASE WHEN p_payment = 'online' THEN trim(p_provider_payment_id) END, 'paid', now(), 'on_demand', app_private.gen_ref('ADM'), 'fulfilled',
            jsonb_build_object('kind', 'on_demand', 'source', 'admin', 'payment', p_payment))
    RETURNING id INTO v_pay;
    INSERT INTO public.booking_events (booking_id, event_type, actor_profile_id, event_metadata)
    VALUES (v_booking, 'payment_received', v_admin,
            jsonb_build_object('payment_id', v_pay, 'provider', CASE WHEN p_payment = 'online' THEN 'razorpay' ELSE 'offline' END, 'amount_cents', v_price));
  END IF;

  INSERT INTO public.notifications (profile_id, category, title, body, reference_id)
  VALUES (p_customer_id, 'booking_confirmed', 'Booking confirmed',
          v_service.name || ' on ' || to_char(p_scheduled_date, 'Dy DD Mon') || ' (' || p_time_slot || ')', v_booking);
  PERFORM app_private.audit('booking', v_booking, 'booking_created_by_admin', jsonb_build_object('customer_id', p_customer_id, 'payment', p_payment, 'amount_cents', v_price));
  RETURN jsonb_build_object('booking_id', v_booking, 'price_cents', v_price, 'payment_id', v_pay);
END $$;

CREATE OR REPLACE FUNCTION public.admin_update_booking_details(p_booking_id uuid, p_address_id uuid DEFAULT NULL, p_parking_location text DEFAULT NULL, p_note text DEFAULT NULL)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_admin uuid := app_private.require_admin();
  v_b public.bookings%ROWTYPE;
  v_note text := NULLIF(trim(COALESCE(p_note, '')), '');
BEGIN
  SELECT * INTO v_b FROM public.bookings WHERE id = p_booking_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Booking not found'; END IF;
  IF v_b.status NOT IN ('pending', 'confirmed', 'worker_assigned', 'worker_called', 'call_not_picked_up') THEN
    RAISE EXCEPTION 'A wash that is % cannot be edited', v_b.status;
  END IF;
  IF p_address_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.customer_addresses WHERE id = p_address_id AND customer_profile_id = v_b.customer_profile_id AND archived_at IS NULL) THEN
    RAISE EXCEPTION 'Address not found';
  END IF;
  UPDATE public.bookings
     SET address_id = COALESCE(p_address_id, address_id),
         parking_location = COALESCE(NULLIF(trim(COALESCE(p_parking_location, '')), ''), parking_location),
         notes = COALESCE(v_note, notes), updated_at = now()
   WHERE id = p_booking_id;
  INSERT INTO public.booking_events (booking_id, event_type, actor_profile_id, event_metadata)
  VALUES (p_booking_id, 'admin_booking_updated', v_admin, jsonb_build_object('address_id', p_address_id, 'parking_location', p_parking_location, 'note', v_note));
  RETURN true;
END $$;

-- ───────────────────────── services and prices ─────────────────────────
CREATE OR REPLACE FUNCTION public.admin_save_service(
  p_service_id uuid, p_code text, p_name text, p_vehicle_type public.vehicle_type, p_description text DEFAULT NULL, p_tagline text DEFAULT NULL,
  p_duration_minutes integer DEFAULT NULL, p_includes jsonb DEFAULT '[]'::jsonb, p_sort_order integer DEFAULT 100
) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_code text := lower(trim(COALESCE(p_code, '')));
  v_name text := trim(COALESCE(p_name, ''));
  v_old public.services%ROWTYPE;
  v_id uuid;
  v_inc jsonb := COALESCE(p_includes, '[]'::jsonb);
BEGIN
  PERFORM app_private.require_admin();
  IF char_length(v_name) < 2 OR char_length(v_name) > 80 THEN RAISE EXCEPTION 'Enter the service name'; END IF;
  IF p_duration_minutes IS NOT NULL AND (p_duration_minutes < 5 OR p_duration_minutes > 600) THEN RAISE EXCEPTION 'Enter a duration between 5 minutes and 10 hours'; END IF;
  IF jsonb_typeof(v_inc) <> 'array' OR jsonb_array_length(v_inc) > 12
     OR EXISTS (SELECT 1 FROM jsonb_array_elements(v_inc) e WHERE jsonb_typeof(e) <> 'string' OR char_length(e #>> '{}') > 80) THEN
    RAISE EXCEPTION 'What is included must be a list of up to 12 short lines';
  END IF;
  IF p_sort_order IS NULL OR p_sort_order < 0 OR p_sort_order > 10000 THEN RAISE EXCEPTION 'Enter a display order between 0 and 10000'; END IF;

  IF p_service_id IS NULL THEN
    IF v_code !~ '^[a-z0-9]+(-[a-z0-9]+)*$' OR char_length(v_code) < 2 OR char_length(v_code) > 40 THEN
      RAISE EXCEPTION 'The code is a short lowercase name like "bike-polish" (letters, numbers and dashes)';
    END IF;
    BEGIN
      INSERT INTO public.services (code, name, vehicle_type, description, tagline, duration_minutes, includes, sort_order, is_active)
      VALUES (v_code, v_name, p_vehicle_type, NULLIF(trim(COALESCE(p_description, '')), ''), NULLIF(trim(COALESCE(p_tagline, '')), ''), p_duration_minutes, v_inc, p_sort_order, true)
      RETURNING id INTO v_id;
    EXCEPTION WHEN unique_violation THEN
      RAISE EXCEPTION 'A service with that code already exists';
    END;
    PERFORM app_private.audit('service', v_id, 'service_created', jsonb_build_object('code', v_code, 'name', v_name));
  ELSE
    SELECT * INTO v_old FROM public.services WHERE id = p_service_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Service not found'; END IF;
    IF v_code <> '' AND v_code <> v_old.code THEN RAISE EXCEPTION 'A service''s code cannot be changed'; END IF;
    IF p_vehicle_type <> v_old.vehicle_type THEN RAISE EXCEPTION 'A service''s vehicle type cannot be changed. Retire it and add a new one.'; END IF;
    UPDATE public.services
       SET name = v_name, description = NULLIF(trim(COALESCE(p_description, '')), ''), tagline = NULLIF(trim(COALESCE(p_tagline, '')), ''),
           duration_minutes = p_duration_minutes, includes = v_inc, sort_order = p_sort_order, updated_at = now()
     WHERE id = p_service_id;
    v_id := p_service_id;
    PERFORM app_private.audit('service', v_id, 'service_updated', jsonb_build_object('code', v_old.code, 'name', v_name));
  END IF;
  RETURN v_id;
END $$;

CREATE OR REPLACE FUNCTION public.admin_set_service_active(p_service_id uuid, p_active boolean)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE v_s public.services%ROWTYPE;
BEGIN
  PERFORM app_private.require_admin();
  SELECT * INTO v_s FROM public.services WHERE id = p_service_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Service not found'; END IF;
  IF NOT p_active AND EXISTS (SELECT 1 FROM public.membership_service_options WHERE service_id = p_service_id) THEN
    RAISE EXCEPTION 'This service is what memberships are built from, so it cannot be retired. Change its price instead.';
  END IF;
  UPDATE public.services SET is_active = p_active, updated_at = now() WHERE id = p_service_id;
  PERFORM app_private.audit('service', p_service_id, CASE WHEN p_active THEN 'service_restored' ELSE 'service_retired' END, jsonb_build_object('code', v_s.code));
  RETURN true;
END $$;

-- The price of one wash. The old rule is closed and a new one starts now, so what was charged before stays readable.
CREATE OR REPLACE FUNCTION public.admin_set_service_price(p_service_id uuid, p_vehicle_type public.vehicle_type, p_price_cents integer)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_s public.services%ROWTYPE;
  v_old public.pricing_rules%ROWTYPE;
  v_version integer;
BEGIN
  PERFORM app_private.require_admin();
  SELECT * INTO v_s FROM public.services WHERE id = p_service_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Service not found'; END IF;
  IF NOT (v_s.vehicle_type = p_vehicle_type OR (p_vehicle_type = 'suv' AND v_s.vehicle_type = 'car')) THEN
    RAISE EXCEPTION 'This service is not offered for that vehicle type';
  END IF;
  IF p_price_cents IS NULL OR p_price_cents < 100 OR p_price_cents > 1000000 THEN RAISE EXCEPTION 'Enter a price between ₹1 and ₹10,000'; END IF;

  SELECT * INTO v_old FROM public.pricing_rules
   WHERE service_id = p_service_id AND vehicle_type = p_vehicle_type AND duration_months = 1 AND quantity_tier = 1
     AND active AND valid_from <= now() AND (valid_to IS NULL OR valid_to > now())
   ORDER BY rule_version DESC LIMIT 1 FOR UPDATE;
  IF FOUND AND v_old.base_amount_cents = p_price_cents THEN
    RETURN jsonb_build_object('changed', false, 'price_cents', p_price_cents);
  END IF;

  IF FOUND THEN
    IF v_old.valid_from >= now() THEN
      -- started in this very transaction: nothing can have used it yet
      UPDATE public.pricing_rules SET base_amount_cents = p_price_cents, updated_at = now() WHERE id = v_old.id;
      PERFORM app_private.audit('service', p_service_id, 'service_price_changed', jsonb_build_object('vehicle_type', p_vehicle_type, 'from_cents', v_old.base_amount_cents, 'to_cents', p_price_cents));
      RETURN jsonb_build_object('changed', true, 'price_cents', p_price_cents);
    END IF;
    UPDATE public.pricing_rules SET valid_to = now(), updated_at = now() WHERE id = v_old.id;
  END IF;

  SELECT COALESCE(max(rule_version), 0) + 1 INTO v_version FROM public.pricing_rules
   WHERE service_id = p_service_id AND vehicle_type = p_vehicle_type AND duration_months = 1 AND quantity_tier = 1;
  INSERT INTO public.pricing_rules (service_id, vehicle_type, duration_months, quantity_tier, base_amount_cents, discount_percent, active, rule_version, valid_from)
  VALUES (p_service_id, p_vehicle_type, 1, 1, p_price_cents, 0, true, v_version, now());
  PERFORM app_private.audit('service', p_service_id, 'service_price_changed',
    jsonb_build_object('vehicle_type', p_vehicle_type, 'from_cents', v_old.base_amount_cents, 'to_cents', p_price_cents, 'rule_version', v_version));
  RETURN jsonb_build_object('changed', true, 'price_cents', p_price_cents);
END $$;

CREATE OR REPLACE FUNCTION public.admin_set_discount(p_kind text, p_key integer, p_discount_bp integer, p_label text)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE v_label text := trim(COALESCE(p_label, ''));
BEGIN
  PERFORM app_private.require_admin();
  IF p_kind NOT IN ('frequency', 'duration') THEN RAISE EXCEPTION 'A discount is either for washes a week or for membership length'; END IF;
  IF p_key IS NULL OR p_key < 1 OR p_key > 12 THEN RAISE EXCEPTION 'Enter a number between 1 and 12'; END IF;
  IF p_kind = 'frequency' AND p_key > 7 THEN RAISE EXCEPTION 'Washes a week is between 1 and 7'; END IF;
  IF p_kind = 'duration' AND p_key NOT IN (1, 3, 6, 12) THEN RAISE EXCEPTION 'Membership length is 1, 3, 6 or 12 months'; END IF;
  IF p_discount_bp IS NULL OR p_discount_bp < 0 OR p_discount_bp > 5000 THEN RAISE EXCEPTION 'A discount is between 0%% and 50%%'; END IF;
  IF char_length(v_label) < 2 OR char_length(v_label) > 60 THEN RAISE EXCEPTION 'Give the discount a short label'; END IF;
  UPDATE public.membership_discount_rules SET active = false WHERE kind = p_kind AND key_value = p_key AND active;
  INSERT INTO public.membership_discount_rules (kind, key_value, discount_bp, label, active) VALUES (p_kind, p_key, p_discount_bp, v_label, true);
  PERFORM app_private.audit('pricing', NULL, 'discount_set', jsonb_build_object('kind', p_kind, 'key', p_key, 'discount_bp', p_discount_bp, 'label', v_label));
  RETURN true;
END $$;

CREATE OR REPLACE FUNCTION public.admin_remove_discount(p_kind text, p_key integer)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  PERFORM app_private.require_admin();
  UPDATE public.membership_discount_rules SET active = false WHERE kind = p_kind AND key_value = p_key AND active;
  IF NOT FOUND THEN RAISE EXCEPTION 'Discount not found'; END IF;
  PERFORM app_private.audit('pricing', NULL, 'discount_removed', jsonb_build_object('kind', p_kind, 'key', p_key));
  RETURN true;
END $$;

CREATE OR REPLACE FUNCTION public.admin_set_pricing_setting(p_key text, p_value integer)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE v_old integer;
BEGIN
  PERFORM app_private.require_admin();
  IF p_value IS NULL OR NOT (
       (p_key = 'max_total_discount_bp' AND p_value BETWEEN 0 AND 5000)
    OR (p_key = 'weeks_per_month' AND p_value BETWEEN 1 AND 5)
    OR (p_key = 'quote_validity_days' AND p_value BETWEEN 1 AND 30)
    OR (p_key = 'membership_min_lead_days' AND p_value BETWEEN 0 AND 30)
    OR (p_key = 'on_demand_min_lead_hours' AND p_value BETWEEN 0 AND 72)
    OR (p_key = 'payment_intent_minutes' AND p_value BETWEEN 5 AND 120)
  ) THEN
    RAISE EXCEPTION 'That setting or value is not allowed';
  END IF;
  SELECT value_int INTO v_old FROM public.pricing_settings WHERE key = p_key FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Setting not found'; END IF;
  UPDATE public.pricing_settings SET value_int = p_value, updated_at = now() WHERE key = p_key;
  PERFORM app_private.audit('pricing', NULL, 'pricing_setting_changed', jsonb_build_object('key', p_key, 'from', v_old, 'to', p_value));
  RETURN true;
END $$;

-- ───────────────────────── grants: admins only, checked inside each function ─────────────────────────
DO $$
DECLARE f text;
BEGIN
  FOREACH f IN ARRAY ARRAY[
    'admin_update_customer_profile(uuid, text, text)',
    'admin_set_profile_archived(uuid, boolean, text)',
    'admin_begin_password_reset(uuid)',
    'admin_save_vehicle(uuid, uuid, public.vehicle_type, text, text, text, text, uuid, text)',
    'admin_set_vehicle_active(uuid, boolean)',
    'admin_save_address(uuid, uuid, text, text, text, text, text, text, text, text, boolean)',
    'admin_set_address_archived(uuid, boolean)',
    'admin_create_booking(uuid, uuid, uuid, date, public.time_slot, uuid, text, text, text, text, integer)',
    'admin_update_booking_details(uuid, uuid, text, text)',
    'admin_save_service(uuid, text, text, public.vehicle_type, text, text, integer, jsonb, integer)',
    'admin_set_service_active(uuid, boolean)',
    'admin_set_service_price(uuid, public.vehicle_type, integer)',
    'admin_set_discount(text, integer, integer, text)',
    'admin_remove_discount(text, integer)',
    'admin_set_pricing_setting(text, integer)'
  ] LOOP
    EXECUTE format('REVOKE ALL ON FUNCTION public.%s FROM PUBLIC, anon', f);
    EXECUTE format('GRANT EXECUTE ON FUNCTION public.%s TO authenticated', f); -- is_admin() inside
  END LOOP;
END $$;

-- ═════════════ 20261004000014_campaigns.sql ═════════════
-- 20261004000014_campaigns.sql
-- SAFE / additive and re-runnable. Free-wash campaigns (the Navratri offer) and the welcome offer on wash packs.
--
-- What a campaign is
--   * WASHO creates one in the Admin page: when claims open and close, the last day a free wash may be done, a cap on the total
--     and (optionally) on washes per day, how long the pack offer lasts, and the three pack rates. Nothing is seeded: no campaign
--     exists until an admin creates it, and it stays off until an admin switches it on.
--   * A customer claims ONE free body wash for their vehicle by picking a day and a time. claim_campaign_wash() checks every rule
--     and creates the booking in one step, so two people can never take the last free wash. The wash is an ordinary booking
--     (price 0, no payment, source 'website'), so specialists, the Washes tab and History treat it like any other.
--   * Rules, all enforced here: the campaign is on and open; the total and per-day caps; new customers only (no earlier wash and no
--     membership); one per verified phone (a profile), one per vehicle plate and one per flat (society + block + flat), so a second
--     number does not get a second wash; the date is inside the window; the usual lead time and one wash per vehicle per day.
--   * Cancelling the free wash gives the claim back (they can claim again while claims are open). A booking that ends as a no-show
--     keeps the claim used up. A completed wash starts the pack offer.
--
-- The pack offer
--   * After the free wash is COMPLETED, for pack_offer_days, the customer's wash-pack price uses the campaign's rates instead of the
--     normal frequency discount (never lower than the normal one): 1 a week, 2 a week, 3 or more a week. It still stacks with the
--     length discount and the usual combined cap. It is used once: the membership bought with it is recorded on the claim.
--   * It is applied inside compute_membership_quote() for the signed-in customer, so the estimate they see, the price stored on
--     the request and the amount charged all come from the same place. Anonymous visitors and everyone else get the normal price.
--
-- Nothing here changes existing rows. It adds two tables, one trigger on bookings (acts only on a booking that has a claim) and one
-- on memberships (acts only on a membership priced with the offer), and replaces compute_membership_quote() with the same logic
-- plus the offer.

-- ───────────────────────── tables ─────────────────────────
CREATE TABLE IF NOT EXISTS public.campaigns (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  code text NOT NULL,
  name text NOT NULL,
  description text,
  is_active boolean NOT NULL DEFAULT false,
  claim_opens_on date NOT NULL,
  claim_closes_on date NOT NULL,
  use_by_date date NOT NULL,
  total_cap integer NOT NULL,
  daily_cap integer,
  new_customers_only boolean NOT NULL DEFAULT true,
  pack_offer_days integer NOT NULL DEFAULT 14,
  pack_offer_bp_1 integer NOT NULL DEFAULT 500,
  pack_offer_bp_2 integer NOT NULL DEFAULT 1000,
  pack_offer_bp_3plus integer NOT NULL DEFAULT 1500,
  created_by uuid REFERENCES public.profiles(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT campaigns_code_check CHECK (code ~ '^[a-z0-9]+(-[a-z0-9]+)*$' AND char_length(code) BETWEEN 3 AND 40),
  CONSTRAINT campaigns_name_check CHECK (char_length(btrim(name)) BETWEEN 3 AND 80),
  CONSTRAINT campaigns_description_check CHECK (description IS NULL OR char_length(description) <= 400),
  CONSTRAINT campaigns_window_check CHECK (claim_closes_on >= claim_opens_on AND use_by_date >= claim_opens_on),
  CONSTRAINT campaigns_total_cap_check CHECK (total_cap BETWEEN 1 AND 100000),
  CONSTRAINT campaigns_daily_cap_check CHECK (daily_cap IS NULL OR daily_cap BETWEEN 1 AND 10000),
  CONSTRAINT campaigns_offer_days_check CHECK (pack_offer_days BETWEEN 1 AND 365),
  CONSTRAINT campaigns_offer_bp_check CHECK (pack_offer_bp_1 BETWEEN 0 AND 5000 AND pack_offer_bp_2 BETWEEN 0 AND 5000 AND pack_offer_bp_3plus BETWEEN 0 AND 5000)
);
CREATE UNIQUE INDEX IF NOT EXISTS ux_campaigns_code ON public.campaigns (code);

CREATE TABLE IF NOT EXISTS public.campaign_claims (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  campaign_id uuid NOT NULL REFERENCES public.campaigns(id) ON DELETE RESTRICT,
  customer_profile_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE RESTRICT,
  booking_id uuid NOT NULL REFERENCES public.bookings(id) ON DELETE CASCADE,
  plate text NOT NULL,
  flat_key text,
  status text NOT NULL DEFAULT 'booked',
  claimed_at timestamptz NOT NULL DEFAULT now(),
  completed_at timestamptz,
  offer_expires_at timestamptz,
  offer_membership_id uuid REFERENCES public.memberships(id) ON DELETE SET NULL,
  offer_used_at timestamptz,
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT campaign_claims_status_check CHECK (status IN ('booked', 'completed', 'released', 'forfeited'))
);
CREATE UNIQUE INDEX IF NOT EXISTS ux_campaign_claims_booking ON public.campaign_claims (booking_id);
-- One live claim per phone, per plate and per flat. A released claim (the wash was cancelled) frees all three again.
CREATE UNIQUE INDEX IF NOT EXISTS ux_campaign_claims_customer ON public.campaign_claims (campaign_id, customer_profile_id) WHERE status <> 'released';
CREATE UNIQUE INDEX IF NOT EXISTS ux_campaign_claims_plate ON public.campaign_claims (campaign_id, plate) WHERE status <> 'released';
CREATE UNIQUE INDEX IF NOT EXISTS ux_campaign_claims_flat ON public.campaign_claims (campaign_id, flat_key) WHERE status <> 'released' AND flat_key IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_campaign_claims_customer ON public.campaign_claims (customer_profile_id);

-- Read-only for people (admins see everything, a customer sees their own claim and its campaign). Every write goes through the functions below.
ALTER TABLE public.campaign_claims ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS campaign_claims_read ON public.campaign_claims;
CREATE POLICY campaign_claims_read ON public.campaign_claims FOR SELECT TO authenticated
  USING (customer_profile_id = public.current_profile_id() OR public.is_admin());
REVOKE ALL ON public.campaign_claims FROM anon, authenticated;
GRANT SELECT ON public.campaign_claims TO authenticated;

ALTER TABLE public.campaigns ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS campaigns_read ON public.campaigns;
CREATE POLICY campaigns_read ON public.campaigns FOR SELECT TO authenticated
  USING (public.is_admin() OR EXISTS (SELECT 1 FROM public.campaign_claims cl WHERE cl.campaign_id = campaigns.id AND cl.customer_profile_id = public.current_profile_id()));
REVOKE ALL ON public.campaigns FROM anon, authenticated;
GRANT SELECT ON public.campaigns TO authenticated;

-- ───────────────────────── helpers ─────────────────────────
-- "The same flat": society + block + flat number, ignoring case and spaces.
CREATE OR REPLACE FUNCTION app_private.flat_key(p_address_id uuid) RETURNS text
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT lower(regexp_replace(a.society_name || '|' || a.building_block || '|' || a.flat_number, '\s+', '', 'g'))
    FROM public.customer_addresses a WHERE a.id = p_address_id;
$$;
REVOKE ALL ON FUNCTION app_private.flat_key(uuid) FROM PUBLIC, anon, authenticated;

-- A new customer has never had a wash that was not cancelled, and has never held a membership.
CREATE OR REPLACE FUNCTION app_private.campaign_is_new_customer(p_profile_id uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT NOT EXISTS (SELECT 1 FROM public.bookings WHERE customer_profile_id = p_profile_id AND status <> 'cancelled')
     AND NOT EXISTS (SELECT 1 FROM public.memberships WHERE customer_profile_id = p_profile_id);
$$;
REVOKE ALL ON FUNCTION app_private.campaign_is_new_customer(uuid) FROM PUBLIC, anon, authenticated;

-- ───────────────────────── claim a free wash ─────────────────────────
CREATE OR REPLACE FUNCTION public.claim_campaign_wash(
  p_campaign_id uuid,
  p_vehicle_id uuid,
  p_scheduled_date date,
  p_time_slot public.time_slot,
  p_address_id uuid DEFAULT NULL,
  p_parking_location text DEFAULT NULL,
  p_target_completion_time text DEFAULT NULL
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_profile uuid := public.current_profile_id();
  v_today date := (now() AT TIME ZONE 'Asia/Kolkata')::date;
  c public.campaigns%ROWTYPE;
  v_vehicle public.vehicles%ROWTYPE;
  v_service public.services%ROWTYPE;
  v_addr uuid;
  v_flat text;
  v_parking text;
  v_claimed integer;
  v_day integer;
  v_booking uuid;
  v_claim uuid;
BEGIN
  IF v_profile IS NULL OR NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = v_profile AND role = 'customer' AND archived_at IS NULL) THEN
    RAISE EXCEPTION 'Customer profile not found' USING ERRCODE = '42501';
  END IF;

  -- Claims for one campaign go through one at a time, so the caps cannot be beaten by two people claiming together.
  SELECT * INTO c FROM public.campaigns WHERE id = p_campaign_id FOR UPDATE;
  IF NOT FOUND OR NOT c.is_active THEN RAISE EXCEPTION 'This offer is not running right now'; END IF;
  IF v_today < c.claim_opens_on THEN RAISE EXCEPTION 'This offer opens on %', to_char(c.claim_opens_on, 'FMDD Mon'); END IF;
  IF v_today > c.claim_closes_on THEN RAISE EXCEPTION 'This offer has ended'; END IF;

  SELECT count(*) INTO v_claimed FROM public.campaign_claims WHERE campaign_id = c.id AND status <> 'released';
  IF v_claimed >= c.total_cap THEN RAISE EXCEPTION 'All the free washes have been claimed. Thank you for your interest!'; END IF;

  IF EXISTS (SELECT 1 FROM public.campaign_claims WHERE campaign_id = c.id AND customer_profile_id = v_profile AND status <> 'released') THEN
    RAISE EXCEPTION 'You have already claimed your free wash';
  END IF;
  IF c.new_customers_only AND NOT app_private.campaign_is_new_customer(v_profile) THEN
    RAISE EXCEPTION 'This offer is for new WASHO customers';
  END IF;

  SELECT * INTO v_vehicle FROM public.vehicles WHERE id = p_vehicle_id AND customer_profile_id = v_profile AND is_active;
  IF NOT FOUND THEN RAISE EXCEPTION 'Vehicle not found'; END IF;
  IF EXISTS (SELECT 1 FROM public.campaign_claims WHERE campaign_id = c.id AND plate = v_vehicle.registration_normalized AND status <> 'released') THEN
    RAISE EXCEPTION 'A free wash has already been claimed for this vehicle';
  END IF;
  IF c.new_customers_only AND EXISTS (
       SELECT 1 FROM public.bookings b JOIN public.vehicles v ON v.id = b.vehicle_id
        WHERE v.registration_normalized = v_vehicle.registration_normalized AND b.status <> 'cancelled') THEN
    RAISE EXCEPTION 'This vehicle has already been washed by WASHO, so it is not eligible for the free wash';
  END IF;

  -- The free wash is the body wash for the vehicle (an SUV uses the car body wash, as everywhere else).
  SELECT s.* INTO v_service
    FROM public.membership_service_options o JOIN public.services s ON s.id = o.service_id AND s.is_active
   WHERE o.vehicle_type = v_vehicle.vehicle_type AND o.wash_kind = 'body';
  IF NOT FOUND THEN RAISE EXCEPTION 'The free body wash is not available for this vehicle'; END IF;

  v_addr := COALESCE(p_address_id, v_vehicle.address_id);
  IF v_addr IS NULL THEN
    SELECT id INTO v_addr FROM public.customer_addresses WHERE customer_profile_id = v_profile AND archived_at IS NULL ORDER BY is_default DESC, created_at LIMIT 1;
  END IF;
  IF v_addr IS NULL THEN RAISE EXCEPTION 'Add your address first, so our specialist knows where to come'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.customer_addresses WHERE id = v_addr AND customer_profile_id = v_profile AND archived_at IS NULL) THEN
    RAISE EXCEPTION 'Address not found';
  END IF;
  v_flat := app_private.flat_key(v_addr);
  IF v_flat IS NOT NULL AND EXISTS (SELECT 1 FROM public.campaign_claims WHERE campaign_id = c.id AND flat_key = v_flat AND status <> 'released') THEN
    RAISE EXCEPTION 'A free wash has already been claimed for this address';
  END IF;

  IF p_scheduled_date IS NULL OR p_scheduled_date < v_today THEN RAISE EXCEPTION 'Choose today or a later date'; END IF;
  IF p_scheduled_date > c.use_by_date THEN RAISE EXCEPTION 'The free wash must be on or before %', to_char(c.use_by_date, 'FMDD Mon'); END IF;
  IF app_private.slot_start(p_scheduled_date, p_time_slot) < now() + make_interval(hours => app_private.setting('on_demand_min_lead_hours')) THEN
    RAISE EXCEPTION 'That slot starts too soon. Please choose a later one.';
  END IF;
  IF app_private.vehicle_has_live_booking(v_vehicle.id, p_scheduled_date) THEN
    RAISE EXCEPTION 'This vehicle already has a wash booked that day';
  END IF;
  IF c.daily_cap IS NOT NULL THEN
    SELECT count(*) INTO v_day FROM public.campaign_claims cl JOIN public.bookings b ON b.id = cl.booking_id
     WHERE cl.campaign_id = c.id AND cl.status <> 'released' AND b.scheduled_date = p_scheduled_date;
    IF v_day >= c.daily_cap THEN RAISE EXCEPTION 'That day is fully booked for free washes. Please choose another day.'; END IF;
  END IF;

  v_parking := COALESCE(NULLIF(trim(COALESCE(p_parking_location, '')), ''), v_vehicle.parking_location,
                        (SELECT parking_location FROM public.customer_addresses WHERE id = v_addr));
  BEGIN
    INSERT INTO public.bookings (customer_profile_id, vehicle_id, service_id, booking_type, scheduled_date, time_slot, status,
                                 notes, address_id, parking_location, target_completion_time, source, price_cents)
    VALUES (v_profile, v_vehicle.id, v_service.id, 'on_demand', p_scheduled_date, p_time_slot, 'confirmed',
            c.name || ' (free wash)' || COALESCE(E'\n' || v_parking, ''), v_addr, v_parking, NULLIF(p_target_completion_time, ''), 'website', 0)
    RETURNING id INTO v_booking;
    INSERT INTO public.campaign_claims (campaign_id, customer_profile_id, booking_id, plate, flat_key)
    VALUES (c.id, v_profile, v_booking, v_vehicle.registration_normalized, v_flat)
    RETURNING id INTO v_claim;
  EXCEPTION WHEN unique_violation THEN
    -- the unique indexes are the last line of defence when two requests slip past the checks above
    IF SQLERRM LIKE '%ux_campaign_claims_plate%' THEN RAISE EXCEPTION 'A free wash has already been claimed for this vehicle'; END IF;
    IF SQLERRM LIKE '%ux_campaign_claims_flat%' THEN RAISE EXCEPTION 'A free wash has already been claimed for this address'; END IF;
    IF SQLERRM LIKE '%ux_campaign_claims_customer%' THEN RAISE EXCEPTION 'You have already claimed your free wash'; END IF;
    IF SQLERRM LIKE '%ux_bookings_vehicle_day_live%' THEN RAISE EXCEPTION 'This vehicle already has a wash booked that day'; END IF;
    RAISE;
  END;

  INSERT INTO public.booking_events (booking_id, event_type, actor_profile_id, event_metadata)
  VALUES (v_booking, 'booking_created', v_profile, jsonb_build_object('booking_type', 'on_demand', 'source', 'website', 'payment', 'free', 'campaign', c.code));
  INSERT INTO public.notifications (profile_id, category, title, body, reference_id)
  VALUES (v_profile, 'booking_confirmed', 'Your free wash is booked',
          v_service.name || ' on ' || to_char(p_scheduled_date, 'Dy DD Mon') || ' (' || p_time_slot || ')', v_booking);
  PERFORM app_private.audit('booking', v_booking, 'campaign_wash_claimed', jsonb_build_object('campaign', c.code, 'claim_id', v_claim, 'scheduled_date', p_scheduled_date));

  RETURN jsonb_build_object('booking_id', v_booking, 'claim_id', v_claim, 'campaign_name', c.name, 'service_name', v_service.name);
END $$;
REVOKE ALL ON FUNCTION public.claim_campaign_wash(uuid, uuid, date, public.time_slot, uuid, text, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.claim_campaign_wash(uuid, uuid, date, public.time_slot, uuid, text, text) TO authenticated;

-- ───────────────────────── keep the claim in step with its wash ─────────────────────────
CREATE OR REPLACE FUNCTION app_private.sync_campaign_claim() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  cl public.campaign_claims%ROWTYPE;
  c public.campaigns%ROWTYPE;
  v_last_day date;
BEGIN
  SELECT * INTO cl FROM public.campaign_claims WHERE booking_id = NEW.id FOR UPDATE;
  IF NOT FOUND OR cl.status <> 'booked' THEN RETURN NEW; END IF;
  SELECT * INTO c FROM public.campaigns WHERE id = cl.campaign_id;

  IF NEW.status = 'completed' THEN
    -- the offer lasts through the end of its last day (Pune time)
    v_last_day := (now() AT TIME ZONE 'Asia/Kolkata')::date + c.pack_offer_days;
    UPDATE public.campaign_claims
       SET status = 'completed', completed_at = now(), updated_at = now(),
           offer_expires_at = ((v_last_day::timestamp + interval '23 hours 59 minutes 59 seconds') AT TIME ZONE 'Asia/Kolkata')
     WHERE id = cl.id;
    INSERT INTO public.notifications (profile_id, category, title, body, reference_id)
    VALUES (cl.customer_profile_id, 'wash_completed', 'Your free wash is done',
            'Start a wash pack by ' || to_char(v_last_day, 'FMDD Mon') || ' and save ' || trim_scale(c.pack_offer_bp_1 / 100.0)::text || '% to ' || trim_scale(GREATEST(c.pack_offer_bp_1, c.pack_offer_bp_2, c.pack_offer_bp_3plus) / 100.0)::text || '%.',
            cl.booking_id);
  ELSIF NEW.status = 'cancelled' THEN
    UPDATE public.campaign_claims SET status = 'released', updated_at = now() WHERE id = cl.id;
  ELSIF NEW.status = 'no_show' THEN
    UPDATE public.campaign_claims SET status = 'forfeited', updated_at = now() WHERE id = cl.id;
  END IF;
  RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION app_private.sync_campaign_claim() FROM PUBLIC, anon, authenticated;
DROP TRIGGER IF EXISTS bookings_sync_campaign_claim ON public.bookings;
CREATE TRIGGER bookings_sync_campaign_claim AFTER UPDATE OF status ON public.bookings
  FOR EACH ROW WHEN (OLD.status IS DISTINCT FROM NEW.status) EXECUTE FUNCTION app_private.sync_campaign_claim();

-- A membership priced with the welcome offer uses it up (the first membership to be created with it).
CREATE OR REPLACE FUNCTION app_private.consume_campaign_offer() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE v_claim uuid := NULLIF(NEW.pricing_snapshot #>> '{campaign_offer,claim_id}', '')::uuid;
BEGIN
  IF v_claim IS NOT NULL THEN
    UPDATE public.campaign_claims SET offer_membership_id = NEW.id, offer_used_at = now(), updated_at = now()
     WHERE id = v_claim AND customer_profile_id = NEW.customer_profile_id AND offer_membership_id IS NULL;
  END IF;
  RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION app_private.consume_campaign_offer() FROM PUBLIC, anon, authenticated;
DROP TRIGGER IF EXISTS memberships_consume_campaign_offer ON public.memberships;
CREATE TRIGGER memberships_consume_campaign_offer AFTER INSERT ON public.memberships
  FOR EACH ROW WHEN (NEW.pricing_snapshot ? 'campaign_offer') EXECUTE FUNCTION app_private.consume_campaign_offer();

-- ───────────────────────── what the website shows ─────────────────────────
-- The campaign people can claim now (or that opens soon), how many are left, what THIS visitor can do about it, and their pack offer
-- if they have one (which outlives the campaign). Anonymous visitors get the campaign only.
CREATE OR REPLACE FUNCTION public.get_campaign_status() RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_today date := (now() AT TIME ZONE 'Asia/Kolkata')::date;
  v_profile uuid := public.current_profile_id();
  v_customer boolean := v_profile IS NOT NULL AND EXISTS (SELECT 1 FROM public.profiles WHERE id = v_profile AND role = 'customer');
  c public.campaigns%ROWTYPE;
  cl public.campaign_claims%ROWTYPE;
  v_claimed integer;
  v_state text;
  v_full jsonb;
  v_campaign jsonb := NULL;
  v_me jsonb := NULL;
  v_offer jsonb := NULL;
BEGIN
  SELECT * INTO c FROM public.campaigns WHERE is_active AND claim_closes_on >= v_today
   ORDER BY (claim_opens_on > v_today), claim_opens_on DESC LIMIT 1;
  IF FOUND THEN
    SELECT count(*) INTO v_claimed FROM public.campaign_claims WHERE campaign_id = c.id AND status <> 'released';
    v_state := CASE WHEN v_today < c.claim_opens_on THEN 'upcoming' WHEN v_claimed >= c.total_cap THEN 'full' ELSE 'open' END;
    SELECT COALESCE(jsonb_agg(d.day ORDER BY d.day), '[]'::jsonb) INTO v_full
      FROM (SELECT b.scheduled_date AS day FROM public.campaign_claims x JOIN public.bookings b ON b.id = x.booking_id
             WHERE c.daily_cap IS NOT NULL AND x.campaign_id = c.id AND x.status <> 'released' AND b.scheduled_date >= v_today
             GROUP BY b.scheduled_date HAVING count(*) >= c.daily_cap) d;
    v_campaign := jsonb_build_object(
      'id', c.id, 'code', c.code, 'name', c.name, 'description', c.description, 'state', v_state,
      'claim_opens_on', c.claim_opens_on, 'claim_closes_on', c.claim_closes_on, 'use_by_date', c.use_by_date,
      'total_cap', c.total_cap, 'spots_left', GREATEST(c.total_cap - v_claimed, 0), 'full_dates', v_full,
      'new_customers_only', c.new_customers_only,
      'pack_offer', jsonb_build_object('days', c.pack_offer_days, 'bp_1', c.pack_offer_bp_1, 'bp_2', c.pack_offer_bp_2, 'bp_3plus', c.pack_offer_bp_3plus));

    IF v_customer THEN
      SELECT * INTO cl FROM public.campaign_claims WHERE campaign_id = c.id AND customer_profile_id = v_profile AND status <> 'released' ORDER BY claimed_at DESC LIMIT 1;
      IF FOUND THEN
        v_me := jsonb_build_object('state', cl.status, 'booking_id', cl.booking_id,
          'scheduled_date', (SELECT b.scheduled_date FROM public.bookings b WHERE b.id = cl.booking_id),
          'time_slot', (SELECT b.time_slot FROM public.bookings b WHERE b.id = cl.booking_id));
      ELSIF c.new_customers_only AND NOT app_private.campaign_is_new_customer(v_profile) THEN
        v_me := jsonb_build_object('state', 'ineligible', 'reason', 'existing_customer');
      ELSE
        v_me := jsonb_build_object('state', 'eligible');
      END IF;
    END IF;
  END IF;

  IF v_customer THEN
    SELECT jsonb_build_object('claim_id', x.id, 'campaign_name', k.name, 'expires_at', x.offer_expires_at,
                              'bp_1', k.pack_offer_bp_1, 'bp_2', k.pack_offer_bp_2, 'bp_3plus', k.pack_offer_bp_3plus)
      INTO v_offer
      FROM public.campaign_claims x JOIN public.campaigns k ON k.id = x.campaign_id
     WHERE x.customer_profile_id = v_profile AND x.status = 'completed' AND x.offer_membership_id IS NULL AND x.offer_expires_at > now()
     ORDER BY x.offer_expires_at DESC LIMIT 1;
  END IF;

  RETURN jsonb_build_object('campaign', v_campaign, 'me', v_me, 'offer', v_offer);
END $$;
REVOKE ALL ON FUNCTION public.get_campaign_status() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_campaign_status() TO anon, authenticated, service_role;

-- ───────────────────────── the pack price, with the welcome offer ─────────────────────────
-- Same calculator as before (migration 10). The one addition: a signed-in customer whose free wash is done, inside their offer window
-- and not yet used, gets the campaign's rate for this many washes a week in place of the normal frequency discount (never lower).
CREATE OR REPLACE FUNCTION app_private.compute_membership_quote(p_vehicle_type public.vehicle_type, p_weekly_pattern jsonb, p_duration_months integer)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_freq integer;
  v_weeks integer := app_private.setting('weeks_per_month');
  v_cap_bp integer := app_private.setting('max_total_discount_bp');
  v_bodies integer;
  v_deeps integer;
  v_lines jsonb := '[]'::jsonb;
  v_subtotal bigint := 0;
  v_freq_bp integer;
  v_freq_label text;
  v_dur_bp integer;
  v_freq_cents bigint;
  v_dur_cents bigint;
  v_combined bigint;
  v_cap_cents bigint;
  v_cap_adj bigint := 0;
  v_total_discount bigint;
  v_offer jsonb;
  rec record;
BEGIN
  IF p_weekly_pattern IS NULL OR jsonb_typeof(p_weekly_pattern) <> 'array' THEN
    RAISE EXCEPTION 'Choose your washes for the week';
  END IF;
  v_freq := jsonb_array_length(p_weekly_pattern);
  IF v_freq NOT BETWEEN 1 AND 7 THEN
    RAISE EXCEPTION 'A membership has 1 to 7 washes a week';
  END IF;

  IF (SELECT count(DISTINCT (e->>'weekday')) FROM jsonb_array_elements(p_weekly_pattern) e) <> v_freq THEN
    RAISE EXCEPTION 'Choose a different day for each wash';
  END IF;
  IF EXISTS (SELECT 1 FROM jsonb_array_elements(p_weekly_pattern) e
              WHERE (e->>'weekday') IS NULL OR (e->>'weekday') !~ '^[0-6]$' OR (e->>'kind') NOT IN ('body', 'deep') OR (e->>'kind') IS NULL) THEN
    RAISE EXCEPTION 'Each wash needs a weekday (0-6) and a kind (body or deep)';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.membership_discount_rules WHERE active AND kind = 'duration' AND key_value = p_duration_months) THEN
    RAISE EXCEPTION 'Membership length must be 1, 3, 6 or 12 months';
  END IF;

  SELECT count(*) FILTER (WHERE e->>'kind' = 'body'), count(*) FILTER (WHERE e->>'kind' = 'deep')
    INTO v_bodies, v_deeps FROM jsonb_array_elements(p_weekly_pattern) e;

  -- Composition rules
  IF p_vehicle_type = 'bike' THEN
    IF v_deeps > 0 THEN RAISE EXCEPTION 'Bikes have one wash type'; END IF;
  ELSIF v_freq = 2 AND NOT (v_bodies = 1 AND v_deeps = 1) THEN
    RAISE EXCEPTION '2 washes a week is 1 body wash + 1 deep cleaning';
  ELSIF v_freq >= 3 AND (v_bodies < 1 OR v_deeps < 1) THEN
    RAISE EXCEPTION '% washes a week mixes body washes and deep cleanings', v_freq;
  END IF;

  -- Lines: one per service
  FOR rec IN
    SELECT o.service_id, s.code, s.name, k.kind, k.n AS per_week
      FROM (SELECT e->>'kind' AS kind, count(*)::int AS n FROM jsonb_array_elements(p_weekly_pattern) e GROUP BY 1) k
      LEFT JOIN public.membership_service_options o ON o.vehicle_type = p_vehicle_type AND o.wash_kind = k.kind
      LEFT JOIN public.services s ON s.id = o.service_id
     ORDER BY k.kind
  LOOP
    IF rec.service_id IS NULL THEN
      RAISE EXCEPTION 'No % wash is offered for this vehicle', rec.kind;
    END IF;
    DECLARE
      v_unit integer := app_private.unit_price_cents(rec.service_id, p_vehicle_type);
      v_qty integer := rec.per_week * v_weeks * p_duration_months;
    BEGIN
      IF v_unit IS NULL THEN RAISE EXCEPTION 'No price is set for % on this vehicle', rec.name; END IF;
      v_lines := v_lines || jsonb_build_array(jsonb_build_object(
        'service_id', rec.service_id, 'code', rec.code, 'name', rec.name, 'kind', rec.kind,
        'per_week', rec.per_week, 'quantity', v_qty, 'unit_cents', v_unit, 'line_cents', v_unit::bigint * v_qty));
      v_subtotal := v_subtotal + v_unit::bigint * v_qty;
    END;
  END LOOP;

  SELECT discount_bp, label INTO v_freq_bp, v_freq_label FROM public.membership_discount_rules WHERE active AND kind = 'frequency' AND key_value = v_freq;
  SELECT discount_bp INTO v_dur_bp  FROM public.membership_discount_rules WHERE active AND kind = 'duration'  AND key_value = p_duration_months;
  v_freq_bp := COALESCE(v_freq_bp, 0);
  v_dur_bp := COALESCE(v_dur_bp, 0);

  -- The welcome offer for a customer whose free-wash campaign wash is done (their own rate for this many washes a week).
  SELECT jsonb_build_object('claim_id', cl.id, 'campaign_id', k.id, 'name', k.name, 'bp', r.bp)
    INTO v_offer
    FROM public.campaign_claims cl
    JOIN public.campaigns k ON k.id = cl.campaign_id
    CROSS JOIN LATERAL (SELECT CASE WHEN v_freq = 1 THEN k.pack_offer_bp_1 WHEN v_freq = 2 THEN k.pack_offer_bp_2 ELSE k.pack_offer_bp_3plus END AS bp) r
   WHERE cl.customer_profile_id = public.current_profile_id()
     AND cl.status = 'completed' AND cl.offer_membership_id IS NULL AND cl.offer_expires_at > now()
   ORDER BY r.bp DESC LIMIT 1;
  IF v_offer IS NOT NULL AND (v_offer->>'bp')::int > v_freq_bp THEN
    v_freq_bp := (v_offer->>'bp')::int;
    v_freq_label := 'Welcome offer · ' || v_freq || CASE WHEN v_freq = 1 THEN ' wash a week' ELSE ' washes a week' END;
  ELSE
    v_offer := NULL;
  END IF;

  -- Sequential: frequency off the subtotal, then duration off what remains. Half-up rounding to the paisa.
  v_freq_cents := round(v_subtotal::numeric * v_freq_bp / 10000);
  v_dur_cents  := round((v_subtotal - v_freq_cents)::numeric * v_dur_bp / 10000);
  v_combined   := v_freq_cents + v_dur_cents;
  v_cap_cents  := round(v_subtotal::numeric * v_cap_bp / 10000);

  IF v_combined > v_cap_cents THEN
    v_cap_adj := v_combined - v_cap_cents;   -- the part of the discount the cap takes back
    v_total_discount := v_cap_cents;
  ELSE
    v_total_discount := v_combined;
  END IF;

  RETURN jsonb_build_object(
    'vehicle_type', p_vehicle_type,
    'frequency_per_week', v_freq,
    'duration_months', p_duration_months,
    'weeks_per_month', v_weeks,
    'washes_total', v_freq * v_weeks * p_duration_months,
    'lines', v_lines,
    'subtotal_cents', v_subtotal,
    'frequency_discount', jsonb_build_object('bp', v_freq_bp, 'cents', v_freq_cents, 'label', v_freq_label),
    'duration_discount',  jsonb_build_object('bp', v_dur_bp,  'cents', v_dur_cents,  'label', (SELECT label FROM public.membership_discount_rules WHERE active AND kind='duration'  AND key_value=p_duration_months)),
    'cap', jsonb_build_object('max_bp', v_cap_bp, 'applied', v_cap_adj > 0, 'adjustment_cents', v_cap_adj),
    'total_discount_cents', v_total_discount,
    'final_cents', v_subtotal - v_total_discount,
    'rounding', 'half_up_to_paisa'
  ) || CASE WHEN v_offer IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('campaign_offer', v_offer) END;
END;
$$;
REVOKE ALL ON FUNCTION app_private.compute_membership_quote(public.vehicle_type, jsonb, integer) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION app_private.compute_membership_quote(public.vehicle_type, jsonb, integer) TO service_role;

-- ───────────────────────── admin: create, edit, switch on and off ─────────────────────────
-- p_id NULL creates (the code is fixed once created: it can be in links and on posters). Returns the campaign id.
CREATE OR REPLACE FUNCTION public.admin_save_campaign(
  p_id uuid, p_code text, p_name text, p_description text,
  p_claim_opens_on date, p_claim_closes_on date, p_use_by_date date,
  p_total_cap integer, p_daily_cap integer, p_pack_offer_days integer,
  p_bp_1 integer, p_bp_2 integer, p_bp_3plus integer, p_active boolean DEFAULT NULL
) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_admin uuid := app_private.require_admin();
  v_cap integer := app_private.setting('max_total_discount_bp');
  v_name text := btrim(COALESCE(p_name, ''));
  v_desc text := NULLIF(btrim(COALESCE(p_description, '')), '');
  v_code text := lower(btrim(COALESCE(p_code, '')));
  v_claimed integer;
  v_id uuid := p_id;
BEGIN
  IF char_length(v_name) NOT BETWEEN 3 AND 80 THEN RAISE EXCEPTION 'Give the campaign a name (3 to 80 characters)'; END IF;
  IF v_desc IS NOT NULL AND char_length(v_desc) > 400 THEN RAISE EXCEPTION 'Keep the description under 400 characters'; END IF;
  IF p_claim_opens_on IS NULL OR p_claim_closes_on IS NULL OR p_use_by_date IS NULL THEN RAISE EXCEPTION 'Set when claims open and close, and the last day to use the wash'; END IF;
  IF p_claim_closes_on < p_claim_opens_on THEN RAISE EXCEPTION 'Claims cannot close before they open'; END IF;
  IF p_use_by_date < p_claim_opens_on THEN RAISE EXCEPTION 'The last day to use the wash cannot be before claims open'; END IF;
  IF p_total_cap IS NULL OR p_total_cap < 1 OR p_total_cap > 100000 THEN RAISE EXCEPTION 'Set how many free washes there are (1 or more)'; END IF;
  IF p_daily_cap IS NOT NULL AND (p_daily_cap < 1 OR p_daily_cap > 10000) THEN RAISE EXCEPTION 'The daily limit must be 1 or more, or empty for no daily limit'; END IF;
  IF p_pack_offer_days IS NULL OR p_pack_offer_days < 1 OR p_pack_offer_days > 365 THEN RAISE EXCEPTION 'The pack offer lasts 1 to 365 days'; END IF;
  IF p_bp_1 IS NULL OR p_bp_2 IS NULL OR p_bp_3plus IS NULL OR LEAST(p_bp_1, p_bp_2, p_bp_3plus) < 0 THEN RAISE EXCEPTION 'Enter the three pack discounts'; END IF;
  IF GREATEST(p_bp_1, p_bp_2, p_bp_3plus) > v_cap THEN
    RAISE EXCEPTION 'A pack discount cannot be more than the % percent combined discount cap', trim_scale(v_cap / 100.0);
  END IF;

  IF v_id IS NULL THEN
    IF v_code !~ '^[a-z0-9]+(-[a-z0-9]+)*$' OR char_length(v_code) NOT BETWEEN 3 AND 40 THEN
      RAISE EXCEPTION 'The short name is 3 to 40 letters, numbers and dashes, for example navratri-2026';
    END IF;
    IF EXISTS (SELECT 1 FROM public.campaigns WHERE code = v_code) THEN RAISE EXCEPTION 'There is already a campaign called %', v_code; END IF;
    INSERT INTO public.campaigns (code, name, description, is_active, claim_opens_on, claim_closes_on, use_by_date, total_cap, daily_cap,
                                  pack_offer_days, pack_offer_bp_1, pack_offer_bp_2, pack_offer_bp_3plus, created_by)
    VALUES (v_code, v_name, v_desc, COALESCE(p_active, false), p_claim_opens_on, p_claim_closes_on, p_use_by_date, p_total_cap, p_daily_cap,
            p_pack_offer_days, p_bp_1, p_bp_2, p_bp_3plus, v_admin)
    RETURNING id INTO v_id;
    PERFORM app_private.audit('campaign', v_id, 'campaign_created', jsonb_build_object('code', v_code, 'total_cap', p_total_cap, 'daily_cap', p_daily_cap));
  ELSE
    PERFORM 1 FROM public.campaigns WHERE id = v_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Campaign not found'; END IF;
    SELECT count(*) INTO v_claimed FROM public.campaign_claims WHERE campaign_id = v_id AND status <> 'released';
    IF p_total_cap < v_claimed THEN RAISE EXCEPTION '% free washes are already claimed, so the total cannot go below that', v_claimed; END IF;
    UPDATE public.campaigns
       SET name = v_name, description = v_desc, claim_opens_on = p_claim_opens_on, claim_closes_on = p_claim_closes_on, use_by_date = p_use_by_date,
           total_cap = p_total_cap, daily_cap = p_daily_cap, pack_offer_days = p_pack_offer_days,
           pack_offer_bp_1 = p_bp_1, pack_offer_bp_2 = p_bp_2, pack_offer_bp_3plus = p_bp_3plus,
           is_active = COALESCE(p_active, is_active), updated_at = now()
     WHERE id = v_id;
    PERFORM app_private.audit('campaign', v_id, 'campaign_updated', jsonb_build_object('total_cap', p_total_cap, 'daily_cap', p_daily_cap));
  END IF;
  RETURN v_id;
END $$;
REVOKE ALL ON FUNCTION public.admin_save_campaign(uuid, text, text, text, date, date, date, integer, integer, integer, integer, integer, integer, boolean) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.admin_save_campaign(uuid, text, text, text, date, date, date, integer, integer, integer, integer, integer, integer, boolean) TO authenticated; -- is_admin() inside

CREATE OR REPLACE FUNCTION public.admin_set_campaign_active(p_id uuid, p_active boolean) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE v_admin uuid := app_private.require_admin();
BEGIN
  UPDATE public.campaigns SET is_active = COALESCE(p_active, false), updated_at = now() WHERE id = p_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Campaign not found'; END IF;
  PERFORM app_private.audit('campaign', p_id, CASE WHEN p_active THEN 'campaign_switched_on' ELSE 'campaign_switched_off' END, '{}'::jsonb);
  RETURN COALESCE(p_active, false);
END $$;
REVOKE ALL ON FUNCTION public.admin_set_campaign_active(uuid, boolean) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.admin_set_campaign_active(uuid, boolean) TO authenticated; -- is_admin() inside

COMMIT;
